/* base/core.css */
/* OpenCodian Styles */

/* Dark mode filter for Lobehub icons (most are black, need inversion on dark bg) */
.theme-dark {
  --lobehub-icon-filter-system: invert(1);
  --lobehub-icon-filter-monochrome: brightness(0) invert(1);
  --opencodian-glass-base: color-mix(in srgb, var(--background-primary) 68%, transparent);
  --opencodian-glass-base-strong: color-mix(in srgb, var(--background-secondary) 62%, transparent);
  --opencodian-glass-base-soft: color-mix(in srgb, var(--background-primary) 46%, transparent);
  --opencodian-glass-specular: rgba(255, 255, 255, 0.14);
  --opencodian-glass-specular-soft: rgba(255, 255, 255, 0.06);
  --opencodian-glass-border: rgba(255, 255, 255, 0.16);
  --opencodian-glass-border-strong: rgba(255, 255, 255, 0.24);
  --opencodian-glass-shadow: rgba(15, 23, 42, 0.22);
  --opencodian-glass-shadow-strong: rgba(15, 23, 42, 0.3);
  --opencodian-glass-highlight: color-mix(in srgb, var(--interactive-accent) 10%, transparent);
  --opencodian-glass-highlight-strong: color-mix(in srgb, var(--interactive-accent) 16%, transparent);
  --opencodian-composer-lens-bg: rgba(2, 6, 12, 0.14);
  --opencodian-composer-lens-bg-strong: rgba(4, 8, 16, 0.18);
  --opencodian-composer-lens-bg-solid: color-mix(in srgb, var(--background-secondary) 88%, #040810);
  --opencodian-composer-lens-border: rgba(255, 255, 255, 0.04);
  --opencodian-composer-lens-border-strong: rgba(255, 255, 255, 0.08);
  --opencodian-composer-lens-shadow: rgba(2, 6, 23, 0.14);
  --opencodian-composer-lens-shadow-strong: rgba(2, 6, 23, 0.2);
  --opencodian-composer-liquid-tint: rgba(2, 6, 12, 0.32);
  --opencodian-composer-liquid-density: rgba(255, 255, 255, 0.03);
  --opencodian-composer-liquid-base-opacity: 0.26;
  --opencodian-composer-liquid-frost-opacity: 0.52;
  --opencodian-composer-liquid-refract-opacity: 0.34;
  --opencodian-composer-liquid-dispersion-opacity: 0.08;
  --opencodian-composer-liquid-highlight: rgba(173, 216, 255, 0.1);
  --opencodian-composer-liquid-highlight-strong: rgba(196, 230, 255, 0.16);
  --opencodian-composer-liquid-spectrum-end: rgba(151, 211, 255, 0.12);
  --opencodian-composer-embedded-fill: color-mix(in srgb, var(--background-primary) 8%, transparent);
  --opencodian-composer-embedded-fill-strong: color-mix(in srgb, var(--background-primary) 12%, transparent);
  --opencodian-composer-embedded-border: rgba(255, 255, 255, 0.06);
  --opencodian-composer-embedded-border-strong: rgba(255, 255, 255, 0.12);
  --opencodian-composer-hotspot-bg: color-mix(in srgb, var(--interactive-accent) 78%, var(--background-primary));
  --opencodian-composer-hotspot-bg-hover: color-mix(in srgb, var(--interactive-accent) 86%, var(--background-primary));
  --opencodian-composer-hotspot-shadow: color-mix(in srgb, var(--interactive-accent) 22%, transparent);
  --opencodian-composer-hotspot-shadow-strong: color-mix(in srgb, var(--interactive-accent) 30%, transparent);
  --opencodian-composer-danger-bg: color-mix(in srgb, var(--background-modifier-error) 74%, var(--background-primary));
  --opencodian-composer-danger-bg-hover: color-mix(in srgb, var(--background-modifier-error) 82%, var(--background-primary));
  --opencodian-composer-danger-shadow: color-mix(in srgb, var(--background-modifier-error) 18%, transparent);
  --opencodian-composer-danger-shadow-strong: color-mix(in srgb, var(--background-modifier-error) 24%, transparent);
}

.theme-light {
  --lobehub-icon-filter-system: none;
  --lobehub-icon-filter-monochrome: brightness(0) saturate(100%);
  --opencodian-glass-base: color-mix(in srgb, var(--background-primary) 42%, transparent);
  --opencodian-glass-base-strong: color-mix(in srgb, var(--background-secondary) 36%, transparent);
  --opencodian-glass-base-soft: color-mix(in srgb, var(--background-primary) 24%, transparent);
  --opencodian-glass-specular: rgba(255, 255, 255, 0.72);
  --opencodian-glass-specular-soft: rgba(255, 255, 255, 0.28);
  --opencodian-glass-border: rgba(255, 255, 255, 0.46);
  --opencodian-glass-border-strong: rgba(255, 255, 255, 0.7);
  --opencodian-glass-shadow: rgba(15, 23, 42, 0.12);
  --opencodian-glass-shadow-strong: rgba(15, 23, 42, 0.18);
  --opencodian-glass-highlight: color-mix(in srgb, var(--interactive-accent) 12%, transparent);
  --opencodian-glass-highlight-strong: color-mix(in srgb, var(--interactive-accent) 20%, transparent);
  --opencodian-composer-lens-bg: color-mix(in srgb, var(--background-primary) 86%, transparent);
  --opencodian-composer-lens-bg-strong: color-mix(in srgb, var(--background-secondary) 82%, transparent);
  --opencodian-composer-lens-bg-solid: var(--background-secondary);
  --opencodian-composer-lens-border: rgba(255, 255, 255, 0.56);
  --opencodian-composer-lens-border-strong: rgba(255, 255, 255, 0.74);
  --opencodian-composer-lens-shadow: rgba(15, 23, 42, 0.08);
  --opencodian-composer-lens-shadow-strong: rgba(15, 23, 42, 0.12);
  --opencodian-composer-liquid-tint: rgba(255, 255, 255, 0.3);
  --opencodian-composer-liquid-density: rgba(255, 255, 255, 0.18);
  --opencodian-composer-liquid-base-opacity: 0.22;
  --opencodian-composer-liquid-frost-opacity: 0.42;
  --opencodian-composer-liquid-refract-opacity: 0.24;
  --opencodian-composer-liquid-dispersion-opacity: 0.04;
  --opencodian-composer-liquid-highlight: rgba(154, 201, 255, 0.14);
  --opencodian-composer-liquid-highlight-strong: rgba(194, 225, 255, 0.2);
  --opencodian-composer-liquid-spectrum-end: rgba(131, 197, 255, 0.1);
  --opencodian-composer-embedded-fill: color-mix(in srgb, var(--background-primary) 72%, transparent);
  --opencodian-composer-embedded-fill-strong: color-mix(in srgb, var(--background-primary) 82%, transparent);
  --opencodian-composer-embedded-border: rgba(255, 255, 255, 0.44);
  --opencodian-composer-embedded-border-strong: rgba(255, 255, 255, 0.6);
  --opencodian-composer-hotspot-bg: color-mix(in srgb, var(--interactive-accent) 76%, white);
  --opencodian-composer-hotspot-bg-hover: color-mix(in srgb, var(--interactive-accent) 84%, white);
  --opencodian-composer-hotspot-shadow: color-mix(in srgb, var(--interactive-accent) 16%, transparent);
  --opencodian-composer-hotspot-shadow-strong: color-mix(in srgb, var(--interactive-accent) 22%, transparent);
  --opencodian-composer-danger-bg: color-mix(in srgb, var(--background-modifier-error) 76%, white);
  --opencodian-composer-danger-bg-hover: color-mix(in srgb, var(--background-modifier-error) 84%, white);
  --opencodian-composer-danger-shadow: color-mix(in srgb, var(--background-modifier-error) 14%, transparent);
  --opencodian-composer-danger-shadow-strong: color-mix(in srgb, var(--background-modifier-error) 18%, transparent);
}

:root {
  --lobehub-icon-filter: var(--lobehub-icon-filter-system, none);
  --opencodian-accent: var(--interactive-accent);
  --opencodian-accent-hover: var(--interactive-accent-hover);
  --opencodian-accent-contrast: var(--text-on-accent);
  --opencodian-accent-text: var(--text-accent);
  --opencodian-surface: var(--background-primary);
  --opencodian-surface-elevated: var(--background-secondary);
  --opencodian-surface-mix: color-mix(in srgb, var(--background-primary) 88%, var(--background-secondary));
  --opencodian-surface-mix-strong: color-mix(in srgb, var(--background-primary) 82%, var(--background-secondary));
  --opencodian-surface-mix-soft: color-mix(in srgb, var(--background-secondary) 92%, var(--background-primary));
  --opencodian-glass: color-mix(in srgb, var(--background-primary) 88%, transparent);
  --opencodian-glass-strong: color-mix(in srgb, var(--background-primary) 78%, transparent);
  --opencodian-glass-elevated: color-mix(in srgb, var(--background-secondary) 92%, transparent);
  --opencodian-glass-soft: color-mix(in srgb, var(--background-primary) 96%, transparent);
  --opencodian-overlay: color-mix(in srgb, var(--background-primary) 52%, transparent);
  --opencodian-overlay-strong: color-mix(in srgb, var(--background-primary) 38%, transparent);
  --opencodian-border-soft: color-mix(in srgb, var(--background-modifier-border) 72%, transparent);
  --opencodian-border-strong: color-mix(in srgb, var(--background-modifier-border-hover) 88%, transparent);
  --opencodian-highlight-soft: color-mix(in srgb, var(--background-modifier-hover) 36%, transparent);
  --opencodian-highlight: color-mix(in srgb, var(--background-modifier-hover) 58%, transparent);
  --opencodian-highlight-strong: color-mix(in srgb, var(--background-modifier-hover) 78%, transparent);
  --opencodian-inset-light: color-mix(in srgb, var(--background-modifier-hover) 64%, transparent);
  --opencodian-inset-light-strong: color-mix(in srgb, var(--background-modifier-hover) 82%, transparent);
  --opencodian-inset-shadow: color-mix(in srgb, var(--background-modifier-border) 52%, transparent);
  --opencodian-shadow-xs: 0 2px 8px color-mix(in srgb, var(--text-normal) 10%, transparent);
  --opencodian-shadow-sm: 0 4px 16px color-mix(in srgb, var(--text-normal) 10%, transparent);
  --opencodian-shadow: 0 8px 24px color-mix(in srgb, var(--text-normal) 12%, transparent);
  --opencodian-shadow-md: 0 10px 26px color-mix(in srgb, var(--text-normal) 12%, transparent);
  --opencodian-shadow-lg: 0 18px 42px color-mix(in srgb, var(--text-normal) 14%, transparent);
  --opencodian-shadow-xl: 0 24px 56px color-mix(in srgb, var(--text-normal) 18%, transparent);
  --opencodian-text-strong: color-mix(in srgb, var(--text-normal) 90%, var(--text-muted));
  --opencodian-accent-subtle: color-mix(in srgb, var(--interactive-accent) 10%, transparent);
  --opencodian-accent-border: color-mix(in srgb, var(--interactive-accent) 32%, transparent);
  --opencodian-glass-base: color-mix(in srgb, var(--background-primary) 60%, transparent);
  --opencodian-glass-base-strong: color-mix(in srgb, var(--background-secondary) 52%, transparent);
  --opencodian-glass-base-soft: color-mix(in srgb, var(--background-primary) 34%, transparent);
  --opencodian-glass-specular: rgba(255, 255, 255, 0.22);
  --opencodian-glass-specular-soft: rgba(255, 255, 255, 0.1);
  --opencodian-glass-border: rgba(255, 255, 255, 0.26);
  --opencodian-glass-border-strong: rgba(255, 255, 255, 0.38);
  --opencodian-glass-shadow: rgba(15, 23, 42, 0.14);
  --opencodian-glass-shadow-strong: rgba(15, 23, 42, 0.22);
  --opencodian-glass-highlight: color-mix(in srgb, var(--interactive-accent) 12%, transparent);
  --opencodian-glass-highlight-strong: color-mix(in srgb, var(--interactive-accent) 18%, transparent);
  --opencodian-composer-lens-bg: rgba(2, 6, 12, 0.16);
  --opencodian-composer-lens-bg-strong: rgba(4, 8, 16, 0.2);
  --opencodian-composer-lens-bg-solid: color-mix(in srgb, var(--background-secondary) 88%, #040810);
  --opencodian-composer-lens-border: rgba(255, 255, 255, 0.06);
  --opencodian-composer-lens-border-strong: rgba(255, 255, 255, 0.1);
  --opencodian-composer-lens-shadow: rgba(2, 6, 23, 0.12);
  --opencodian-composer-lens-shadow-strong: rgba(2, 6, 23, 0.18);
  --opencodian-composer-liquid-tint: rgba(2, 6, 12, 0.34);
  --opencodian-composer-liquid-density: rgba(255, 255, 255, 0.04);
  --opencodian-composer-liquid-base-opacity: 0.24;
  --opencodian-composer-liquid-frost-opacity: 0.48;
  --opencodian-composer-liquid-refract-opacity: 0.3;
  --opencodian-composer-liquid-dispersion-opacity: 0.06;
  --opencodian-composer-liquid-highlight: rgba(173, 216, 255, 0.12);
  --opencodian-composer-liquid-highlight-strong: rgba(196, 230, 255, 0.18);
  --opencodian-composer-liquid-spectrum-end: rgba(151, 211, 255, 0.12);
  --opencodian-composer-embedded-fill: color-mix(in srgb, var(--background-primary) 8%, transparent);
  --opencodian-composer-embedded-fill-strong: color-mix(in srgb, var(--background-primary) 12%, transparent);
  --opencodian-composer-embedded-border: rgba(255, 255, 255, 0.07);
  --opencodian-composer-embedded-border-strong: rgba(255, 255, 255, 0.13);
  --opencodian-composer-hotspot-bg: color-mix(in srgb, var(--interactive-accent) 78%, var(--background-primary));
  --opencodian-composer-hotspot-bg-hover: color-mix(in srgb, var(--interactive-accent) 86%, var(--background-primary));
  --opencodian-composer-hotspot-shadow: color-mix(in srgb, var(--interactive-accent) 20%, transparent);
  --opencodian-composer-hotspot-shadow-strong: color-mix(in srgb, var(--interactive-accent) 28%, transparent);
  --opencodian-composer-danger-bg: color-mix(in srgb, var(--background-modifier-error) 74%, var(--background-primary));
  --opencodian-composer-danger-bg-hover: color-mix(in srgb, var(--background-modifier-error) 82%, var(--background-primary));
  --opencodian-composer-danger-shadow: color-mix(in srgb, var(--background-modifier-error) 16%, transparent);
  --opencodian-composer-danger-shadow-strong: color-mix(in srgb, var(--background-modifier-error) 22%, transparent);
}

/* Status tokens must live on body: Obsidian defines --text-success/--text-error/--text-warning/--color-* only on body,
   so :root declarations referencing them resolve to guaranteed-invalid and never reach descendants. */
body {
  --opencodian-status-warning: var(--text-warning, var(--color-orange, var(--interactive-accent)));
  --opencodian-status-warning-subtle: color-mix(in srgb, var(--opencodian-status-warning) 10%, transparent);
  --opencodian-status-warning-border: color-mix(in srgb, var(--opencodian-status-warning) 28%, transparent);
  --opencodian-status-success: var(--text-success, var(--background-modifier-success));
  --opencodian-status-success-subtle: color-mix(in srgb, var(--opencodian-status-success) 10%, transparent);
  --opencodian-status-success-border: color-mix(in srgb, var(--opencodian-status-success) 24%, transparent);
  --opencodian-status-error: var(--text-error, var(--background-modifier-error));
  --opencodian-status-error-subtle: color-mix(in srgb, var(--opencodian-status-error) 10%, transparent);
  --opencodian-status-error-border: color-mix(in srgb, var(--opencodian-status-error) 24%, transparent);
  --opencodian-status-info: var(--color-blue, var(--interactive-accent));
  --opencodian-status-info-subtle: color-mix(in srgb, var(--opencodian-status-info) 10%, transparent);
  --opencodian-status-info-border: color-mix(in srgb, var(--opencodian-status-info) 28%, transparent);
}

/* AA tuning: raw status hues fail 4.5:1 as small chip text in one or both themes, so the
   text-level tokens are mixed toward --text-normal per theme (dark: lighten error/info;
   light: darken all four). -subtle/-border derive from these base tokens automatically. */
.theme-dark {
  --opencodian-status-error: color-mix(in srgb, var(--text-error, var(--background-modifier-error)) 70%, var(--text-normal));
  --opencodian-status-info: color-mix(in srgb, var(--color-blue, var(--interactive-accent)) 55%, var(--text-normal));
}

.theme-light {
  --opencodian-status-warning: color-mix(in srgb, var(--text-warning, var(--color-orange, var(--interactive-accent))) 60%, var(--text-normal));
  --opencodian-status-success: color-mix(in srgb, var(--text-success, var(--background-modifier-success)) 60%, var(--text-normal));
  --opencodian-status-error: color-mix(in srgb, var(--text-error, var(--background-modifier-error)) 65%, var(--text-normal));
  --opencodian-status-info: color-mix(in srgb, var(--color-blue, var(--interactive-accent)) 70%, var(--text-normal));
}

body[data-opencodian-provider-icon-mode="system"] {
  --lobehub-icon-filter: var(--lobehub-icon-filter-system, none);
}

body[data-opencodian-provider-icon-mode="monochrome"] {
  --lobehub-icon-filter: var(--lobehub-icon-filter-monochrome, none);
}

body[data-opencodian-provider-icon-mode="color"] {
  --lobehub-icon-filter: none;
}

.opencodian-provider-icon-image {
  filter: var(--lobehub-icon-filter, none);
}

/* Own the chat view's vertical gutters instead of stacking Obsidian's generic
   32px bottom padding with the composer's inset. Keep device safe areas. */
.workspace-leaf-content[data-type="opencodian-view"] > .view-content {
  --opencodian-chat-edge-gap: var(--size-4-3, 12px);
  /* Neutralize the host's horizontal view padding: the chat frame inset is owned
     by --opencodian-chat-inset-x on .opencodian-container so it is user-tunable. */
  padding-inline: 0;
  padding-top: max(var(--safe-area-inset-top, 0px), var(--opencodian-chat-edge-gap));
  padding-bottom: max(var(--safe-area-inset-bottom, 0px), var(--opencodian-chat-edge-gap));
}

.opencodian-container {
  --opencodian-chat-inset-x: 12px;
  --opencodian-composer-inset-x: 0px;
  --opencodian-composer-inset-y: 12px;
  --opencodian-composer-max-height: 240px;
  --interactive-accent: var(--opencodian-accent);
  --interactive-accent-hover: var(--opencodian-accent-hover);
  --text-on-accent: var(--opencodian-accent-contrast);
  --text-accent: var(--opencodian-accent-text);
  --opencodian-chat-surface: var(--background-secondary);
  --opencodian-chat-font-size: 13px;
  --opencodian-composer-stack-height: 0px;
  --opencodian-messages-pad-top: 12px;
  --opencodian-messages-pad-x: 0px;
  container-type: inline-size;
  --opencodian-message-pad-x: 21px;
  --opencodian-content-pad-x: 10px;
  --opencodian-content-pad-y: 5px;
  --opencodian-sticky-header-gap: 6px;
  --opencodian-sticky-push-gap: 0px;
  --opencodian-sticky-mask-height: 18px;
  --opencodian-sticky-mask-blur: 0px;
  --opencodian-theme-bg-opacity: 0.92;
  --opencodian-theme-bg-blur: 2px;
  --opencodian-theme-bg-scale: 1.08;
  --opencodian-theme-bg-bleed: 28px;
  --opencodian-theme-bg-dim: 28%;
  --opencodian-theme-bg-edge-fade: 28px;
  --opencodian-theme-bg-overlay-opacity: 32%;
  --opencodian-theme-bg-overlay-opacity-strong: 42%;
  --opencodian-theme-bg-mask-opacity: 48%;
  --opencodian-theme-bg-highlight-opacity: 14%;
  --opencodian-theme-bg-saturation: 108%;
  --opencodian-theme-bg-brightness: 94%;
  --opencodian-theme-bg-size: cover;
  --opencodian-theme-bg-focus-x: 50%;
  --opencodian-theme-bg-focus-y: 50%;
  --opencodian-user-radius: 16px;
  --opencodian-user-tail-radius: 4px;
  --opencodian-user-blur: 12px;
  --opencodian-user-shadow-blur: 28px;
  /* Solid user bubble: derived from the resolved theme surface so it adapts
     to dark/light themes automatically (text-normal mix lifts it off the
     chat background). */
  --opencodian-user-bubble-bg: color-mix(in srgb, var(--opencodian-chat-surface) 90%, var(--text-normal) 10%);
  --opencodian-user-bubble-bg-hover: color-mix(in srgb, var(--opencodian-chat-surface) 86%, var(--text-normal) 14%);
  --opencodian-user-bubble-border: color-mix(in srgb, var(--background-modifier-border) 88%, transparent);
  --opencodian-user-bubble-border-hover: var(--background-modifier-border-hover);
  --opencodian-user-time-font-size: 11px;
  --opencodian-user-time-font-weight: 400;
  --opencodian-user-time-color: var(--text-muted);
  --opencodian-assistant-radius: 14px;
  --opencodian-assistant-pad-y: 0px;
  --opencodian-assistant-pad-x: var(--opencodian-message-pad-x);
  --opencodian-assistant-content-pad-y: var(--opencodian-content-pad-y);
  --opencodian-assistant-content-pad-x: var(--opencodian-content-pad-x);
  --opencodian-assistant-bg-opacity: 72%;
  --opencodian-assistant-blur: 10px;
  --opencodian-assistant-shadow-blur: 24px;
  --opencodian-assistant-meta-font-size: 10px;
  --opencodian-assistant-meta-color: var(--text-muted);
  --opencodian-assistant-time-font-size: 10px;
  --opencodian-assistant-time-font-weight: 400;
  --opencodian-assistant-time-color: var(--text-muted);
  --opencodian-assistant-model-id-font-size: 10px;
  --opencodian-assistant-model-id-font-weight: 400;
  --opencodian-assistant-model-id-color: var(--text-faint, var(--text-muted));
  --opencodian-input-radius: 12px;
  --opencodian-input-bg-opacity: 72%;
  --opencodian-input-blur: 18px;
  --opencodian-input-shadow-blur: 28px;
  --opencodian-composer-font-family: "OpenCodian Newsreader", Georgia, serif;
  /* Layered composer spacing scale (context-strip → textarea → input-row → runtime-dock). */
  --opencodian-composer-gap-xs: 6px;
  --opencodian-composer-gap-sm: 8px;
  --opencodian-composer-pad-x: 12px;
  --opencodian-gr-glass-bg-alpha: 0.48;
  --opencodian-gr-glass-blur: 26px;
  --opencodian-gr-glass-saturation: 170%;
  --opencodian-gr-glass-brightness: 108%;
  --opencodian-gr-card-bg-alpha: 0.52;
  --opencodian-gr-card-blur: 20px;
  --opencodian-gr-card-saturation: 150%;
  --opencodian-gr-card-brightness: 100%;
  --opencodian-gr-pill-bg-alpha: 0.05;
  --opencodian-gr-pill-blur: 8px;
  --opencodian-gr-pill-saturation: 130%;
  --opencodian-gr-pill-brightness: 100%;
  --opencodian-scrollbar-width: 8px;
  --opencodian-scrollbar-radius: 999px;
  --opencodian-scrollbar-track-opacity: 22%;
  --opencodian-scrollbar-thumb-opacity: 68%;
  --opencodian-scrollbar-thumb-hover-opacity: 82%;
  --opencodian-scrollbar-edge-padding: 2px;
  --opencodian-scrollbar-shadow-opacity: 46%;
  display: flex;
  flex-direction: column;
  height: 100%;
  max-height: 100vh; /* Ensure container doesn't exceed viewport */
  padding-inline: var(--opencodian-chat-inset-x);
  overflow: hidden;
  position: relative; /* Create positioning context */
}

