  --opencodian-glass-base-strong: color-mix(in srgb, white 94%, var(--background-secondary));
  --opencodian-glass-base-soft: color-mix(in srgb, white 90%, var(--background-secondary));
  --opencodian-glass-specular: rgba(255, 255, 255, 0.04);
  --opencodian-glass-specular-soft: rgba(255, 255, 255, 0.02);
  --opencodian-glass-border: rgba(148, 163, 184, 0.22);
  --opencodian-glass-border-strong: rgba(148, 163, 184, 0.3);
  --opencodian-glass-shadow: rgba(15, 23, 42, 0);
  --opencodian-glass-shadow-strong: rgba(15, 23, 42, 0);
  --opencodian-glass-highlight: color-mix(in srgb, var(--interactive-accent) 6%, transparent);
  --opencodian-glass-highlight-strong: color-mix(in srgb, var(--interactive-accent) 10%, transparent);
  --opencodian-shadow-xs: none;
  --opencodian-shadow-sm: none;
  --opencodian-shadow: none;
  --opencodian-shadow-md: none;
  --opencodian-shadow-lg: none;
  --opencodian-shadow-xl: none;
}

.theme-dark .opencodian-container.opencodian-theme-soft {
  --opencodian-glass-base: color-mix(in srgb, var(--background-primary) 78%, transparent);
  --opencodian-glass-base-strong: color-mix(in srgb, var(--background-secondary) 72%, transparent);
  --opencodian-glass-base-soft: color-mix(in srgb, var(--background-primary) 62%, transparent);
