  --opencodian-glass-specular: rgba(255, 255, 255, 0.82);
  --opencodian-glass-specular-soft: rgba(255, 255, 255, 0.38);
  --opencodian-glass-border: rgba(255, 255, 255, 0.56);
  --opencodian-glass-border-strong: rgba(255, 255, 255, 0.7);
  --opencodian-glass-shadow: rgba(15, 23, 42, 0.08);
  --opencodian-glass-shadow-strong: rgba(15, 23, 42, 0.12);
  --opencodian-shadow-xs: 0 2px 8px color-mix(in srgb, var(--text-normal) 8%, transparent);
  --opencodian-shadow-sm: 0 8px 18px color-mix(in srgb, var(--text-normal) 10%, transparent);
  --opencodian-shadow: 0 12px 30px color-mix(in srgb, var(--text-normal) 12%, transparent);
  --opencodian-shadow-md: 0 16px 34px color-mix(in srgb, var(--text-normal) 13%, transparent);
}

.theme-dark .opencodian-container.opencodian-theme-sharp {
  --opencodian-glass-base: color-mix(in srgb, var(--background-secondary) 84%, transparent);
  --opencodian-glass-base-strong: color-mix(in srgb, var(--background-secondary) 78%, transparent);
  --opencodian-glass-base-soft: color-mix(in srgb, var(--background-primary) 72%, transparent);
  --opencodian-glass-specular: rgba(255, 255, 255, 0.08);
  --opencodian-glass-specular-soft: rgba(255, 255, 255, 0.03);
  --opencodian-glass-border: rgba(148, 163, 184, 0.2);
  --opencodian-glass-border-strong: rgba(148, 163, 184, 0.34);
  --opencodian-glass-shadow: rgba(2, 6, 23, 0.22);
  --opencodian-glass-shadow-strong: rgba(2, 6, 23, 0.3);
  --opencodian-shadow-xs: 0 1px 4px color-mix(in srgb, var(--text-normal) 16%, transparent);
  --opencodian-shadow-sm: 0 3px 10px color-mix(in srgb, var(--text-normal) 18%, transparent);
  --opencodian-shadow: 0 8px 18px color-mix(in srgb, var(--text-normal) 22%, transparent);
  --opencodian-shadow-md: 0 10px 22px color-mix(in srgb, var(--text-normal) 24%, transparent);
