.theme-light .opencodian-container.opencodian-theme-sharp {
  --opencodian-glass-base: color-mix(in srgb, white 92%, var(--background-secondary));
  --opencodian-glass-base-strong: color-mix(in srgb, white 86%, var(--background-secondary));
  --opencodian-glass-base-soft: color-mix(in srgb, white 94%, var(--background-primary));
  --opencodian-glass-specular: rgba(255, 255, 255, 0.46);
