  --opencodian-shadow: 0 8px 18px color-mix(in srgb, var(--text-normal) 18%, transparent);
  --opencodian-shadow-md: 0 10px 22px color-mix(in srgb, var(--text-normal) 20%, transparent);
  --opencodian-shadow-lg: 0 14px 28px color-mix(in srgb, var(--text-normal) 22%, transparent);
}


/* ── shadcn: neutral bordered surfaces, docked composer, message-pane-only scroll ── */

.opencodian-container.opencodian-theme-shadcn {
  /* shadcn surface tokens derived from the Obsidian theme so custom vault themes keep working. */
  --opencodian-shadcn-border: color-mix(in srgb, var(--background-modifier-border) 92%, transparent);
  --opencodian-shadcn-surface: var(--background-primary);
  --opencodian-shadcn-muted: color-mix(in srgb, var(--background-primary) 94%, var(--text-normal));
  --opencodian-shadcn-muted-hover: color-mix(in srgb, var(--background-primary) 90%, var(--text-normal));
  --opencodian-shadcn-ring: color-mix(in srgb, var(--opencodian-accent) 18%, transparent);
  --opencodian-shadcn-shadow-sm: 0 1px 2px 0 color-mix(in srgb, var(--text-normal) 6%, transparent);
  /* Neutralize the glass pipeline: flat opaque surfaces, no specular, no glow. */
  --opencodian-glass-base: var(--background-primary);
  --opencodian-glass-base-strong: var(--background-primary);
  --opencodian-glass-base-soft: var(--background-primary);
  --opencodian-glass-specular: transparent;
  --opencodian-glass-specular-soft: transparent;
  --opencodian-glass-border: var(--opencodian-shadcn-border);
  --opencodian-glass-border-strong: var(--opencodian-shadcn-border);
  --opencodian-glass-shadow: transparent;
  --opencodian-glass-shadow-strong: transparent;
  --opencodian-glass-highlight: transparent;
  --opencodian-glass-highlight-strong: transparent;
  --opencodian-shadow-xs: none;
  --opencodian-shadow-sm: none;
  --opencodian-shadow: none;
  --opencodian-shadow-md: none;
  --opencodian-shadow-lg: none;
  --opencodian-shadow-xl: none;
  --opencodian-user-bubble-bg: var(--opencodian-shadcn-muted);
  --opencodian-user-bubble-bg-hover: var(--opencodian-shadcn-muted-hover);
  --opencodian-user-bubble-border: var(--opencodian-shadcn-border);
  --opencodian-user-bubble-border-hover: var(--opencodian-shadcn-border);
  --opencodian-composer-lens-bg-solid: var(--opencodian-shadcn-surface);
  --opencodian-composer-lens-border: var(--opencodian-shadcn-border);
  --opencodian-composer-lens-border-strong: var(--opencodian-shadcn-border);
  --opencodian-composer-lens-shadow: transparent;
  --opencodian-composer-lens-shadow-strong: transparent;
}

/* shadcn's primary flips between zinc-900 (light) and zinc-50 (dark), so the
   accent is defined per theme here instead of as static preset CSS variables. */
.theme-dark .opencodian-container.opencodian-theme-shadcn {
  --opencodian-accent: #fafafa;
  --opencodian-accent-hover: #e4e4e7;
  --opencodian-accent-contrast: #18181b;
  --opencodian-accent-text: #fafafa;
}

.theme-light .opencodian-container.opencodian-theme-shadcn {
  --opencodian-accent: #18181b;
  --opencodian-accent-hover: #27272a;
  --opencodian-accent-contrast: #fafafa;
  --opencodian-accent-text: #18181b;
}

/*
 * shadcn layout: dock the composer in the container flow instead of floating
 * it over the messages pane. The messages pane then ends at the composer's top
 * edge, so its scroll area no longer extends to the panel bottom underneath
 * the input and the --opencodian-composer-stack-height scroll padding is unused.
 */
.opencodian-container.opencodian-theme-shadcn .opencodian-input-area {
  position: static;
  padding: var(--opencodian-composer-inset-y, 12px) var(--opencodian-composer-inset-x, 12px) var(--opencodian-composer-inset-y, 12px);
}

.opencodian-container.opencodian-theme-shadcn .opencodian-messages {
  padding-bottom: 16px;
}

.opencodian-container.opencodian-theme-shadcn .opencodian-header {
  border-bottom: 1px solid var(--opencodian-shadcn-border);
}

.opencodian-container.opencodian-theme-shadcn .opencodian-composer-shell {
  border-radius: var(--opencodian-input-radius);
  border: 1px solid var(--opencodian-shadcn-border);
  box-shadow: var(--opencodian-shadcn-shadow-sm);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

/* Image attachment chips insert above the padded content layer; in the bordered
   shadcn card they must carry the content inset instead of sitting flush at the edge. */
.opencodian-container.opencodian-theme-shadcn .opencodian-composer-image-chips {
  margin: 10px 12px 0;
}

.opencodian-container.opencodian-theme-shadcn .opencodian-composer-shell:focus-within {
  border-color: color-mix(in srgb, var(--opencodian-accent) 42%, var(--opencodian-shadcn-border));
  box-shadow: 0 0 0 3px var(--opencodian-shadcn-ring), var(--opencodian-shadcn-shadow-sm);
}

/* Flat shadcn surfaces: no lift/glide on hover. */
.opencodian-container.opencodian-theme-shadcn .opencodian-message--user:hover .opencodian-message-content {
  transform: none;
  box-shadow: none;
}

.opencodian-container.opencodian-theme-shadcn .opencodian-message--assistant:hover .opencodian-message-content {
  transform: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}


/* Header - transparent, no border */
.opencodian-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--opencodian-chat-edge-gap, 12px) 16px;
}

.opencodian-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 16px;
  color: var(--text-normal);
}

.opencodian-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 25px;
  flex-shrink: 0;
}

.opencodian-logo svg {
  width: 100%;
  height: 100%;
  display: block;
}

.svg-icon.opencodian-app-icon .opencodian-app-icon-layer--dark {
  display: none;
}

.theme-dark .svg-icon.opencodian-app-icon .opencodian-app-icon-layer--light {
  display: none;
}

.theme-dark .svg-icon.opencodian-app-icon .opencodian-app-icon-layer--dark {
  display: inline;
}

.opencodian-title-text {
  display: block;
  width: auto;
  height: 16px;
  object-fit: contain;
  user-select: none;
  -webkit-user-drag: none;
}

.opencodian-header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.opencodian-header-action-group {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.opencodian-header-status-group {
  position: relative;
  min-width: 28px;
  overflow: visible;
}

.opencodian-header-status-group::before {
  content: '';
  flex: 0 0 28px;
  width: 28px;
  height: 28px;
}

.opencodian-header-conversation-group,
.opencodian-header-config-group {
  padding-inline-start: 0;
}

.opencodian-server-status-badge {
  --opencodian-server-status-label-ch: 4;
  --opencodian-server-status-expanded-width: 92px;
  --opencodian-server-status-inline-chrome-width: 46px;
  display: inline-flex;
  align-items: center;
  gap: 0;
  justify-content: center;
  position: absolute;
  inset-block-start: 0;
  inset-inline-end: calc(100% - 28px);
  width: 28px;
  min-width: 28px;
  max-width: min(220px, 48vw);
  height: 28px;
  box-sizing: border-box;
  padding: 0;
  margin: 0;
  isolation: isolate;
  border-radius: 999px;
  border: 1px solid var(--opencodian-glass-border);
  background:
    linear-gradient(
      180deg,
      var(--opencodian-glass-specular) 0%,
      color-mix(in srgb, var(--opencodian-glass-specular-soft) 88%, transparent) 46%,
      transparent 100%
    ),
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--opencodian-glass-base-strong) 96%, transparent) 0%,
      color-mix(in srgb, var(--opencodian-glass-base) 82%, transparent) 100%
    );
  backdrop-filter: blur(18px) saturate(1.15);
  -webkit-backdrop-filter: blur(18px) saturate(1.15);
  box-shadow:
    0 5px 14px color-mix(in srgb, var(--opencodian-glass-shadow) 82%, transparent),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 88%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border) 48%, transparent) inset;
  color: var(--text-muted);
  cursor: pointer;
  font: inherit;
  overflow: hidden;
  transition:
    color 0.16s ease,
    border-color 0.16s ease,
    box-shadow 0.16s ease,
    transform 0.16s ease,
    width 0.16s ease;
}

/* The shared tooltip trigger is positioned relatively; keep this badge as the local overlay owner. */
.opencodian-server-status-badge.opencodian-tooltip-trigger {
  position: absolute;
}

.opencodian-server-status-badge:hover,
.opencodian-server-status-badge:focus-visible {
  width: min(var(--opencodian-server-status-expanded-width), 220px, 48vw);
  justify-content: flex-start;
  gap: 6px;
  padding-inline: 8px 14px;
  z-index: 8;
  color: var(--text-normal);
  border-color: var(--opencodian-glass-border-strong);
  box-shadow:
    0 7px 18px color-mix(in srgb, var(--opencodian-glass-shadow-strong) 84%, transparent),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 95%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border-hover) 64%, transparent) inset;
  transform: translateY(-1px);
}

.opencodian-server-status-badge:focus-visible {
  outline: 2px solid var(--background-modifier-border-focus, var(--interactive-accent));
  outline-offset: 2px;
}

.opencodian-server-status-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  flex: 0 0 16px;
  width: 16px;
  height: 16px;
  color: currentColor;
  margin: 0;
  transform: translate3d(0, 0, 0);
}

.opencodian-server-status-icon::before {
  content: "";
  display: block;
  width: 16px;
  height: 16px;
  background-color: currentColor;
  opacity: 0;
  transform: scale(0.94);
  transition:
    opacity 0.15s ease,
    transform 0.16s ease;
  -webkit-mask-image: var(--opencodian-server-status-icon-url);
  mask-image: var(--opencodian-server-status-icon-url);
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
}

.opencodian-server-status-icon.has-svg-icon::before {
  opacity: 0.92;
  transform: scale(1);
}

.opencodian-server-status-icon-fallback {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  inset: 0;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  opacity: 0.86;
}

.opencodian-server-status-icon.has-svg-icon .opencodian-server-status-icon-fallback {
  opacity: 0;
}

.opencodian-server-status-icon.has-inline-brandmark::before {
  display: none;
}

.opencodian-server-status-icon.has-lobehub-icon::before {
  display: none;
}

.opencodian-server-status-icon.has-lobehub-icon .opencodian-agent-switcher-lobehub-icon,
.opencodian-server-status-icon.has-lobehub-icon .opencodian-agent-switcher-lobehub-img {
  width: 16px;
  height: 16px;
}

/* Pi is an embedded filled mark, independent of the connection-state color.
   Its 800-unit artwork carries symmetric whitespace, so the 22px box centers
   naturally in the 28px badge; do not nudge it off-center to dodge the
   status dot (the dot is sized/positioned to stay clear of the glyph ink). */
.opencodian-server-status-icon[data-backend-icon='pi'] > svg.opencodian-pi {
  flex: 0 0 22px;
  width: 22px;
  height: 22px;
  color: var(--text-normal);
}

.opencodian-server-status-icon-brandmark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 17px;
  color: currentColor;
}

.opencodian-server-status-icon-brandmark svg {
  display: block;
  width: 100%;
  height: 100%;
}

.opencodian-server-status-state {
  position: absolute;
  /* Hug the badge rim so the dot stays outside centered backend-icon ink. */
  inset-inline-end: 2px;
  inset-block-end: 2px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.95;
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--background-primary) 82%, transparent),
    0 0 0 4px color-mix(in srgb, currentColor 16%, transparent);
  transition:
    border-radius 0.16s ease,
    box-shadow 0.16s ease,
    opacity 0.16s ease,
    transform 0.16s ease;
}

.opencodian-server-status-text {
  display: inline-block;
  flex: 1 1 auto;
  min-width: 0;
  max-width: 0;
  color: currentColor;
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: clip;
  opacity: 0;
  pointer-events: none;
  transform: translate3d(-4px, 0, 0);
  transition:
    max-width 0.16s ease,
    opacity 0.16s ease,
    transform 0.16s ease;
}

.opencodian-server-status-badge:hover .opencodian-server-status-text,
.opencodian-server-status-badge:focus-visible .opencodian-server-status-text {
  max-width: calc(
    min(var(--opencodian-server-status-expanded-width), 220px, 48vw)
    - var(--opencodian-server-status-inline-chrome-width)
  );
  opacity: 1;
  transform: translate3d(0, 0, 0);
}

.opencodian-server-status-badge.is-checking,
.opencodian-server-status-badge.is-starting {
  color: var(--text-accent);
}

.opencodian-server-status-badge.is-checking .opencodian-server-status-state,
.opencodian-server-status-badge.is-starting .opencodian-server-status-state {
  animation: opencodian-status-badge-pulse 1.6s ease-in-out infinite;
}

.opencodian-server-status-badge.is-running,
.opencodian-server-status-badge.is-external {
  color: var(--color-green);
}

.opencodian-server-status-badge.is-offline {
  color: var(--text-error);
}

.opencodian-server-status-badge.is-offline .opencodian-server-status-state {
  border-radius: 2px;
  opacity: 0.9;
  transform: rotate(45deg) scale(0.92);
  box-shadow:
