  transform: translateY(-50%) translateX(0);
}

.opencodian-tab-bar[data-layout="below-header-vertical"] .opencodian-tab-bar-item:not(.is-streaming) .opencodian-tab-bar-state {
  position: absolute;
  right: -3px;
  bottom: -3px;
  width: 14px;
  height: 14px;
  border-radius: 999px;
  background: var(--background-primary);
  box-shadow: 0 1px 4px color-mix(in srgb, var(--text-normal) 18%, transparent);
}

.opencodian-tab-bar[data-layout="below-header-vertical"] .opencodian-tab-bar-item.has-background-task .opencodian-tab-bar-state {
  background: color-mix(in srgb, var(--text-warning) 12%, var(--background-primary));
  box-shadow: 0 1px 6px color-mix(in srgb, var(--text-warning) 28%, transparent);
}

.opencodian-tab-overflow-menu {
  position: fixed;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--background-primary) 96%, var(--background-secondary));
  border: 1px solid var(--background-modifier-border);
  box-shadow: 0 16px 36px color-mix(in srgb, var(--text-normal) 18%, transparent);
  overflow-y: auto;
  z-index: 1300;
}

.opencodian-tab-overflow-menu-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
  padding: 8px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--text-normal);
  cursor: pointer;
  text-align: left;
}

.opencodian-tab-overflow-menu-item:hover,
.opencodian-tab-overflow-menu-item:focus-visible {
  background: var(--background-modifier-hover);
  outline: none;
}

.opencodian-tab-overflow-menu-item.is-active {
  background: color-mix(in srgb, var(--interactive-accent) 16%, var(--background-secondary));
}

.opencodian-tab-overflow-menu-item.needs-attention:not(.is-active) {
  color: var(--text-warning);
}

.opencodian-tab-overflow-menu-item.has-background-task:not(.is-active) {
  background: color-mix(in srgb, var(--text-warning) 8%, transparent);
}

.opencodian-tab-overflow-menu-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: var(--background-modifier-hover);
  color: var(--text-normal);
  font-size: 11px;
  font-weight: 700;
  flex: 0 0 auto;
}

.opencodian-tab-overflow-menu-title {
  min-width: 0;
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 600;
}

.opencodian-tab-overflow-menu-state {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: var(--interactive-accent);
}

.opencodian-tab-overflow-menu-state svg {
  width: 14px;
  height: 14px;
}

.opencodian-tab-overflow-menu-state.is-background-task {
  width: 18px;
  color: var(--text-warning);
}

.opencodian-tab-overflow-menu-state.is-streaming svg {
  animation: opencodian-spin 0.9s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-tab-bar-item,
  .opencodian-tab-bar-title,
  .opencodian-tab-bar-state,
  .opencodian-tab-bar-overflow,
  .opencodian-tab-overflow-menu-item {
    transition: none;
  }
}

@keyframes opencodian-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes opencodian-tab-background-pulse {
  0%, 100% {
    opacity: 0.35;
    transform: scale(0.92);
  }
  50% {
    opacity: 0.88;
    transform: scale(1.08);
  }
}

@keyframes opencodian-tab-background-ring {
