    opacity: 0.78;
    transform: scale(0.8);
  }
  100% {
    opacity: 0;
    transform: scale(1.25);
  }
}

@keyframes opencodian-tab-background-dots {
  0%, 80%, 100% {
    opacity: 0.34;
    transform: translateY(0) scale(0.9);
  }
  40% {
    opacity: 1;
    transform: translateY(-1px) scale(1.18);
