.opencodian-theme-background-layer {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 0;
  background: var(--opencodian-chat-surface);
  opacity: 0;
  transition: opacity 0.28s ease;
}

.opencodian-theme-background-image {
  position: absolute;
  top: calc(-1 * var(--opencodian-theme-bg-bleed));
  left: calc(-1 * var(--opencodian-theme-bg-bleed));
  width: calc(100% + (var(--opencodian-theme-bg-bleed) * 2));
  height: calc(100% + (var(--opencodian-theme-bg-bleed) * 2));
  background-repeat: no-repeat;
  background-size: var(--opencodian-theme-bg-size);
  background-position: var(--opencodian-theme-bg-focus-x) var(--opencodian-theme-bg-focus-y);
  transform: translateZ(0) scale(var(--opencodian-theme-bg-scale));
  transform-origin: center;
  filter:
    blur(var(--opencodian-theme-bg-blur))
    saturate(var(--opencodian-theme-bg-saturation))
    brightness(var(--opencodian-theme-bg-brightness));
  opacity: var(--opencodian-theme-bg-opacity);
  -webkit-mask-image: radial-gradient(
    140% 122% at 50% 50%,
    rgba(0, 0, 0, 1) calc(100% - var(--opencodian-theme-bg-edge-fade)),
    rgba(0, 0, 0, 0.82) calc(100% - (var(--opencodian-theme-bg-edge-fade) * 0.52)),
    rgba(0, 0, 0, 0.2) calc(100% - (var(--opencodian-theme-bg-edge-fade) * 0.12)),
    transparent 100%
  );
  -webkit-mask-repeat: no-repeat;
  mask-image: radial-gradient(
    140% 122% at 50% 50%,
    rgba(0, 0, 0, 1) calc(100% - var(--opencodian-theme-bg-edge-fade)),
    rgba(0, 0, 0, 0.82) calc(100% - (var(--opencodian-theme-bg-edge-fade) * 0.52)),
    rgba(0, 0, 0, 0.2) calc(100% - (var(--opencodian-theme-bg-edge-fade) * 0.12)),
    transparent 100%
  );
  mask-repeat: no-repeat;
  transition: opacity 0.28s ease, transform 0.32s ease, filter 0.28s ease;
}

.opencodian-messages-shell::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  opacity: 0;
  transition: opacity 0.28s ease;
  background:
    radial-gradient(
      120% 84% at 50% 0%,
      color-mix(in srgb, white var(--opencodian-theme-bg-highlight-opacity), transparent) 0%,
      transparent 58%
    ),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--opencodian-chat-surface) var(--opencodian-theme-bg-overlay-opacity-strong), transparent) 0%,
      color-mix(in srgb, var(--opencodian-chat-surface) var(--opencodian-theme-bg-overlay-opacity), transparent) 26%,
      color-mix(in srgb, var(--opencodian-chat-surface) calc(var(--opencodian-theme-bg-overlay-opacity) - 6%), transparent) 100%
    );
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--background-modifier-border) 34%, transparent),
    inset 0 18px 36px color-mix(in srgb, var(--opencodian-chat-surface) 12%, transparent);
