    column-gap: 8px;
  }

  .opencodian-messages-shell--session-rail .opencodian-messages {
    grid-column: 2;
    grid-row: 1;
    min-width: 0;
  }

  .opencodian-session-rail {
    display: flex;
    grid-column: 1;
    grid-row: 1;
    z-index: 2;
