    display: flex;
    min-height: 0;
    flex: 1;
    flex-direction: column;
    gap: 4px;
    overflow: auto;
    scrollbar-width: thin;
  }

  .opencodian-session-rail-list > [role="listitem"] {
    display: block;
    min-width: 0;
  }

  .opencodian-session-rail button.opencodian-session-rail-item {
    display: grid;
    width: 100%;
    min-width: 0;
    height: auto !important;
    min-height: 52px;
    grid-template-rows: auto auto;
    align-content: center;
    gap: 2px;
    padding: 6px 8px;
    border: 1px solid transparent;
    border-radius: 6px;
    background: transparent;
    color: var(--text-muted);
    text-align: left;
  }

  .opencodian-session-rail button.opencodian-session-rail-item:hover {
    background: var(--background-modifier-hover);
    color: var(--text-normal);
  }

  .opencodian-session-rail button.opencodian-session-rail-item.is-current {
    border-color: color-mix(in srgb, var(--interactive-accent) 42%, var(--background-modifier-border));
    background: color-mix(in srgb, var(--interactive-accent) 13%, var(--background-secondary));
    color: var(--text-normal);
    font-weight: 600;
  }

  .opencodian-session-rail button.opencodian-session-rail-item:focus-visible {
    outline: 2px solid var(--interactive-accent);
    outline-offset: 1px;
  }

  .opencodian-session-rail-item-title,
  .opencodian-session-rail-item-date {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    line-height: 1.4;
  }

  .opencodian-session-rail-item-title {
    font-size: 12px;
  }

  .opencodian-session-rail-item-date,
  .opencodian-session-rail-empty {
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.4;
  }

  .opencodian-session-rail-empty {
    padding: 8px;
  }
}

