.opencodian-messages--sticky-mask .opencodian-turn-header::before {
  content: "";
  position: absolute;
  top: 0;
  right: calc(-1 * var(--opencodian-messages-pad-x));
  bottom: 0;
  left: calc(-1 * var(--opencodian-messages-pad-x));
