.opencodian-messages--sticky-mask .opencodian-turn-header::after {
  content: "";
  position: absolute;
  top: calc(100% - 1px);
  right: calc(-1 * var(--opencodian-messages-pad-x));
  left: calc(-1 * var(--opencodian-messages-pad-x));
  height: var(--opencodian-sticky-mask-height);
