    color-mix(in srgb, var(--opencodian-chat-surface) var(--opencodian-theme-bg-mask-opacity), transparent) 0%,
    color-mix(in srgb, var(--opencodian-chat-surface) var(--opencodian-theme-bg-overlay-opacity), transparent) 35%,
