/* utils/markdown.css */
/* ============================================================
   Markdown Rendering Styles
   ============================================================ */

/* Markdown content container */
:is(.opencodian-message-text, .streaming-text-block).markdown-rendered {
  /* Reset the bubble styles for markdown content */
  background: transparent;
  padding: 0;
}

.opencodian-message--user .opencodian-message-text.markdown-rendered {
  display: inline-block;
  width: fit-content;
  max-width: 100%;
}

.opencodian-message--user .opencodian-message-text.markdown-rendered > :first-child:last-child {
  margin-block: 0;
}

.opencodian-message--assistant :is(.opencodian-message-text, .streaming-text-block) {
  /* Ensure markdown content is readable */
  overflow-wrap: break-word;
}

:is(.opencodian-message-text, .streaming-text-block) {
  --opencodian-markdown-inline-code-bg:
    color-mix(in srgb, var(--background-modifier-hover) 56%, var(--background-secondary) 44%);
  --opencodian-markdown-code-block-bg:
    color-mix(in srgb, var(--code-background) 88%, var(--background-primary) 12%);
  --opencodian-markdown-code-block-border:
    color-mix(in srgb, var(--background-modifier-border) 64%, var(--text-muted) 36%);
  --opencodian-markdown-code-language-bg:
    color-mix(in srgb, var(--background-primary) 78%, var(--background-modifier-hover));
}

/* Code block panel: Tailwind Typography keeps fenced code in one distinct pre surface. */
.markdown-code-wrapper {
  position: relative;
  margin: 0.75em 0;
  border: 1px solid var(--opencodian-markdown-code-block-border);
  border-radius: 8px;
  background: var(--opencodian-markdown-code-block-bg);
  box-shadow: none;
  overflow: hidden;
}

.markdown-code-wrapper.has-language pre {
  padding-top: 2.4em;
}

.markdown-code-wrapper pre {
  margin: 0;
  padding: 0.9em 1em;
  background: transparent;
  color: inherit;
  font-family: var(--font-monospace);
  line-height: 1.6;
  overflow-x: auto;
}

/* Language label and copy button */
.markdown-code-lang-label {
  position: absolute;
  top: 0.3em;
  right: 0.5em;
  font-size: 0.75em;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0.2em 0.5em;
  border: 1px solid var(--opencodian-markdown-code-block-border);
  border-radius: 4px;
  background: var(--opencodian-markdown-code-language-bg);
  font-family: var(--font-monospace);
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}

.markdown-code-lang-label:hover {
  background: var(--interactive-hover);
  color: var(--text-normal);
}

.markdown-code-wrapper .copy-code-button {
  display: none !important;
}

/* Inline code: the compact shadcn-style token, deliberately unlike a code panel. */
:is(.opencodian-message-text, .streaming-text-block) code {
  position: relative;
  display: inline-block;
  font-family: var(--font-monospace);
  font-size: 0.9em;
  font-weight: 600;
  background: var(--opencodian-markdown-inline-code-bg);
  padding: 0.2em 0.3em;
  border: 0;
  border-radius: 4px;
  box-shadow: none;
  color: var(--code-normal, var(--text-normal));
  white-space: break-spaces;
  overflow-wrap: anywhere;
  word-break: break-word;
  vertical-align: baseline;
}

:is(.opencodian-message-text, .streaming-text-block) pre code {
  display: block;
  box-sizing: border-box;
  width: 100%;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  color: inherit;
  font-size: inherit;
  font-family: inherit;
  font-weight: inherit;
  line-height: inherit;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}

:is(.opencodian-message-text, .streaming-text-block) pre code::before,
:is(.opencodian-message-text, .streaming-text-block) pre code::after {
  content: none;
}

/* MathJax is mathematical typography, never a code chip or code panel. */
:is(.opencodian-message-text, .streaming-text-block) :is(
  .math.math-inline,
  .math-inline,
  .katex:not(.katex-display .katex),
  mjx-container:not([display="true"])
) {
  color: var(--text-normal);
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

:is(.opencodian-message-text, .streaming-text-block) :is(.math.math-block, .math-block, .katex-display, mjx-container[display="true"]) {
  margin: 0.85em 0;
  padding: 0.2em 0;
  color: var(--text-normal);
  background: transparent !important;
  border: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
  overflow-x: auto;
  overflow-y: hidden;
}

/* Images */
.markdown-embedded-image {
  display: inline-block;
  margin: 0.5em 0;
  max-width: 100%;
}

.markdown-embedded-image img {
  max-width: 100%;
  border-radius: 4px;
  display: block;
}

.markdown-embedded-image.has-intrinsic-placeholder img {
  aspect-ratio: auto 16 / 9;
}

/* File links */
.markdown-file-link {
  color: var(--link-color);
  cursor: pointer;
  text-decoration: none;
  border-bottom: 1px solid var(--link-color);
}

.markdown-file-link:hover {
  color: var(--link-color-hover);
  border-bottom-color: var(--link-color-hover);
}

/* Headings */
:is(.opencodian-message-text, .streaming-text-block) h1,
:is(.opencodian-message-text, .streaming-text-block) h2,
:is(.opencodian-message-text, .streaming-text-block) h3,
:is(.opencodian-message-text, .streaming-text-block) h4,
:is(.opencodian-message-text, .streaming-text-block) h5,
:is(.opencodian-message-text, .streaming-text-block) h6 {
  margin-top: 1em;
  margin-bottom: 0.5em;
  font-weight: 600;
  line-height: 1.3;
}

:is(.opencodian-message-text, .streaming-text-block) h1 { font-size: 1.5em; }
:is(.opencodian-message-text, .streaming-text-block) h2 { font-size: 1.3em; }
:is(.opencodian-message-text, .streaming-text-block) h3 { font-size: 1.1em; }
:is(.opencodian-message-text, .streaming-text-block) h4,
:is(.opencodian-message-text, .streaming-text-block) h5,
:is(.opencodian-message-text, .streaming-text-block) h6 { font-size: 1em; }

/* Lists */
:is(.opencodian-message-text, .streaming-text-block) ul,
:is(.opencodian-message-text, .streaming-text-block) ol {
  margin: 0.5em 0;
  padding-left: 1.5em;
}

:is(.opencodian-message-text, .streaming-text-block) li {
  margin: 0.25em 0;
}

/* Blockquotes */
:is(.opencodian-message-text, .streaming-text-block) blockquote {
  margin: 0.5em 0;
  padding-left: 1em;
  border-left: 3px solid var(--blockquote-border);
  color: var(--blockquote-color);
}

/* Tables */
:is(.opencodian-message-text, .streaming-text-block) table {
  --opencodian-table-border-color:
    color-mix(in srgb, var(--background-modifier-border-hover, var(--background-modifier-border)) 78%, var(--text-muted) 22%);
  --opencodian-table-header-bg:
    color-mix(in srgb, var(--background-secondary) 88%, var(--interactive-accent) 12%);
  --opencodian-table-row-alt-bg:
    color-mix(in srgb, var(--background-secondary-alt, var(--background-secondary)) 78%, transparent);
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin: 0.75em 0;
  display: table;
  max-width: 100%;
  background: color-mix(in srgb, var(--background-primary) 82%, var(--background-secondary) 18%);
  box-shadow: inset 0 0 0 1px var(--opencodian-table-border-color);
  border-radius: 10px;
}

:is(.opencodian-message-text, .streaming-text-block) th,
:is(.opencodian-message-text, .streaming-text-block) td {
  padding: 0.5em;
  border: 1px solid var(--opencodian-table-border-color);
  text-align: left;
  vertical-align: top;
  overflow-wrap: anywhere;
  word-break: break-word;
}

:is(.opencodian-message-text, .streaming-text-block) th {
  background: var(--opencodian-table-header-bg);
  font-weight: 700;
}

:is(.opencodian-message-text, .streaming-text-block) tbody tr:nth-child(even) td {
  background: var(--opencodian-table-row-alt-bg);
}

:is(.opencodian-message-text, .streaming-text-block) :is(th, td) a {
  overflow-wrap: anywhere;
  word-break: break-all;
}

/* Horizontal rule */
:is(.opencodian-message-text, .streaming-text-block) hr {
  border: none;
  border-top: 1px solid var(--background-modifier-border);
  margin: 1em 0;
}

/* Links */
:is(.opencodian-message-text, .streaming-text-block) a {
  color: var(--link-color);
  text-decoration: none;
}

:is(.opencodian-message-text, .streaming-text-block) a:hover {
  color: var(--link-color-hover);
  text-decoration: underline;
}

/* Rendering error */
.markdown-render-error {
  color: var(--text-error);
  padding: 1em;
  background: var(--background-modifier-error);
  border-radius: 4px;
  border: 1px solid var(--background-modifier-error-hover);
}



/* components/composer-popover-frame.css */
/*
 * Shared Composer Popover + Command frame
 *
 * One quiet sheet: background-primary, 1px background-modifier-border,
 * 10px radius, restrained host shadow. No glass, gradients, nested
 * cards, colored rails, or selected-row outlines. Default, hover,
 * keyboard-highlight, and selected rows all share the same low-sat
 * background-modifier-hover surface; selection is communicated by the
 * per-selector checkmark and label weight, never by border, shadow,
 * or left color rail.
 */

.opencodian-composer-popover-frame {
  overflow: hidden;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-primary);
  box-shadow: 0 4px 14px var(--background-modifier-box-shadow);
}

.opencodian-composer-popover-header,
.opencodian-composer-popover-footer {
  display: flex;
  align-items: center;
  min-height: 36px;
  padding: 0 12px;
  color: var(--text-muted);
}

.opencodian-composer-popover-header {
  justify-content: space-between;
  border-bottom: 1px solid var(--background-modifier-border);
}

.opencodian-composer-popover-title {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0;
  text-overflow: ellipsis;
  text-transform: none;
  white-space: nowrap;
}

.opencodian-composer-popover-section {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.opencodian-composer-popover-footer {
  gap: 10px;
  border-top: 1px solid var(--background-modifier-border);
  font-size: 11px;
}

.opencodian-composer-popover-escape-key {
  padding: 1px 5px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 4px;
  font: inherit;
}

.opencodian-composer-popover-content {
  min-width: 0;
}

.opencodian-composer-popover-section,
.opencodian-composer-popover-state {
  padding: 8px 12px;
}

.opencodian-composer-popover-state {
  color: var(--text-muted);
  font-size: 12px;
}

/*
 * Command item row. Compact by default; rows that render a description
 * grow naturally with their content. Transparent at rest; one quiet
 * hover/keyboard/selected surface. Selection is signaled by the
 * per-selector checkmark and label weight only.
 */
.opencodian-composer-popover-option {
  box-sizing: border-box;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) 18px;
  align-items: center;
  column-gap: 8px;
  min-height: 32px;
  padding: 6px 8px;
  border-radius: 6px;
  background: transparent;
}

.opencodian-composer-popover-option:hover,
.opencodian-composer-popover-option.is-highlighted,
.opencodian-composer-popover-option.is-selected {
  background: var(--background-modifier-hover);
}

.opencodian-composer-popover-option:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: -2px;
}

.opencodian-composer-popover-option-icon,
.opencodian-composer-popover-option-check {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  color: var(--text-muted);
}

.opencodian-composer-popover-option-main,
.opencodian-composer-popover-option-text {
  min-width: 0;
}

.opencodian-composer-popover-option-title {
  overflow: hidden;
  color: var(--text-normal);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-composer-popover-option.is-selected .opencodian-composer-popover-option-title,
.opencodian-composer-popover-option.is-selected .opencodian-agent-option-label,
.opencodian-composer-popover-option.is-selected .opencodian-permission-option-label,
.opencodian-composer-popover-option.is-selected .opencodian-model-option-name {
  font-weight: 600;
}

.opencodian-composer-popover-option-description {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-composer-popover-frame,
  .opencodian-composer-popover-option {
    scroll-behavior: auto;
    transition: none;
  }
}


/* components/agent-selector.css */
/* ============================================================
   Agent Selector
   ============================================================ */

.opencodian-agent-selector {
  flex-shrink: 0;
  position: relative;
  display: inline-flex;
  align-items: center;
}

.opencodian-agent-trigger {
  display: flex;
  align-items: center;
  min-height: var(--opencodian-input-toolbar-control-height, 30px);
  padding: 3px 7px;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 54%, transparent);
  border-radius: 999px;
  cursor: pointer;
  background: color-mix(in srgb, var(--background-primary) 54%, transparent);
  box-shadow: 0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 30%, transparent) inset;
  transition:
    background-color 0.15s ease-out,
    border-color 0.15s ease-out,
    box-shadow 0.15s ease-out,
    color 0.15s ease-out;
  user-select: none;
  font-size: 11px;
  color: var(--text-normal);
}

.opencodian-agent-trigger:hover {
  color: var(--text-normal);
  background: color-mix(in srgb, var(--opencodian-composer-embedded-fill) 24%, var(--background-primary));
  border-color: color-mix(in srgb, var(--background-modifier-border) 78%, var(--text-muted));
}

.opencodian-agent-trigger.is-open {
  color: var(--text-normal);
  background: color-mix(in srgb, var(--opencodian-composer-embedded-fill) 24%, transparent);
  border-color: color-mix(in srgb, var(--interactive-accent) 52%, var(--background-modifier-border));
}

.opencodian-agent-trigger.is-selected {
  color: var(--text-warning);
  background: color-mix(in srgb, var(--text-warning) 8%, transparent);
  border-color: color-mix(in srgb, var(--text-warning) 26%, var(--background-modifier-border));
}

.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger {
  padding: 3px 5px;
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  color: color-mix(in srgb, var(--text-normal) 78%, var(--text-muted));
  filter: none;
}

.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger:hover,
.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger.is-open {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  color: var(--text-normal);
  filter: brightness(1.04) saturate(1.02);
}

.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger.is-selected {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  color: color-mix(in srgb, var(--text-warning) 88%, var(--text-normal));
}

.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger.is-selected:hover,
.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger.is-selected.is-open {
  color: color-mix(in srgb, var(--text-warning) 96%, var(--text-normal));
}

.opencodian-agent-trigger:focus-visible {
  outline: 2px solid var(--background-modifier-border-focus);
  outline-offset: 2px;
}

.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--interactive-accent) 58%, transparent);
  outline-offset: 3px;
}

.opencodian-agent-trigger-content {
  display: flex;
  align-items: center;
  gap: 5px;
  max-width: 140px;
}

.opencodian-agent-trigger-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  opacity: 0.62;
}

.opencodian-agent-trigger:hover .opencodian-agent-trigger-icon,
.opencodian-agent-trigger.is-open .opencodian-agent-trigger-icon {
  opacity: 1;
}

.opencodian-agent-trigger-icon svg {
  width: 12px;
  height: 12px;
}

.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger-icon svg {
  opacity: 0.96;
  filter:
    drop-shadow(0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 84%, transparent))
    drop-shadow(0 -1px 0 color-mix(in srgb, var(--opencodian-glass-shadow-strong) 48%, transparent));
}

.opencodian-agent-trigger-chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--text-muted);
  transition: transform 0.16s cubic-bezier(0.22, 1, 0.36, 1);
}

.opencodian-agent-trigger.is-open .opencodian-agent-trigger-chevron {
  transform: rotate(180deg);
}

.opencodian-composer-shell--action-buttons-etched .opencodian-agent-trigger-chevron {
  color: currentColor;
  opacity: 0.7;
}

.opencodian-agent-trigger-chevron svg {
  width: 12px;
  height: 12px;
}

.opencodian-agent-trigger-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}

.opencodian-agent-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  box-sizing: border-box;
  width: 340px;
  min-width: 272px;
  max-width: 340px;
  max-height: 320px;
  margin-bottom: 6px;
  z-index: 1000;
  overflow-y: auto;
  overflow-x: hidden;
  animation: agent-dropdown-open 0.18s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes agent-dropdown-open {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(6px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.opencodian-agent-dropdown-heading {
  padding: 6px 10px 2px;
  color: var(--text-faint);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: normal;
  text-transform: none;
}

.opencodian-agent-option {
  align-items: start;
  cursor: pointer;
  font-size: 13px;
  color: var(--text-normal);
  user-select: none;
}

/*
 * Command items: the marker dot is hidden. Selection is expressed by
 * the shared checkmark and 600 label weight only; "default" is still
 * labeled by the compact default badge.
 */
.opencodian-agent-option-marker {
  display: none;
}

.opencodian-agent-option-check {
  grid-column: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  margin-top: 1px;
  color: var(--interactive-accent);
  opacity: 0;
}

.opencodian-agent-option-check svg {
  width: 14px;
  height: 14px;
}

.opencodian-agent-option.is-selected .opencodian-agent-option-check {
  color: var(--text-normal);
  opacity: 1;
}

.opencodian-agent-option.is-selected .opencodian-agent-option-label {
  font-weight: 600;
}

.opencodian-agent-option-content {
  grid-column: 2;
  min-width: 0;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.opencodian-agent-option-main {
  display: flex;
  min-width: 0;
}

.opencodian-agent-option-label-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.opencodian-agent-option-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
  line-height: 1.3;
}

.opencodian-agent-option-meta {
  display: flex;
  align-items: center;
  flex: 0 1 auto;
  flex-wrap: nowrap;
  gap: 5px;
  min-width: 0;
}

.opencodian-agent-option-mode {
  flex-shrink: 0;
  padding: 0 5px 1px;
  border-radius: 5px;
  background: color-mix(in srgb, var(--text-muted) 12%, transparent);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: 0.02em;
}

.opencodian-agent-option-mode.is-default-mode {
  max-width: 86px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  background: color-mix(in srgb, var(--text-muted) 10%, transparent);
  color: var(--text-muted);
}

.opencodian-agent-option-desc,
.opencodian-agent-dropdown-state {
  font-size: 11px;
  line-height: 1.4;
  color: var(--text-muted);
}

.opencodian-agent-option-desc {
  display: -webkit-box;
  overflow: hidden;
  word-break: break-word;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.opencodian-agent-dropdown-state {
  margin: 2px 4px 0;
  padding: 8px 10px;
  border-radius: 6px;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-agent-trigger,
  .opencodian-agent-trigger-chevron,
  .opencodian-agent-option,
  .opencodian-agent-dropdown {
    transition: none;
  }

  .opencodian-agent-dropdown {
    animation: none;
  }
}


/* components/agent-switcher.css */
.opencodian-settings-tabbed {
  position: relative;
}

.opencodian-agent-switcher-hover-zone {
  display: none;
}

.opencodian-agent-switcher-floating {
  position: fixed;
  left: var(--opencodian-agent-switcher-fixed-left, 0);
  top: 50%;
  /* Match Obsidian's modal layer: visible over the owning settings modal, below later child modals. */
  z-index: 50;
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 4px;
  padding: 6px 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border-hover) 56%, transparent);
  border-left: 0;
  border-radius: 0 10px 10px 0;
  background: color-mix(in srgb, var(--background-secondary) 92%, transparent);
  box-shadow:
    inset 1px 0 0 color-mix(in srgb, var(--background-primary) 42%, transparent),
    0 8px 18px color-mix(in srgb, var(--text-normal) 8%, transparent);
  opacity: 0.72;
  pointer-events: auto;
  transform: translateY(-50%);
  transition:
    width 180ms cubic-bezier(0.22, 1, 0.36, 1),
    padding 180ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 140ms ease,
    background 140ms ease,
    border-color 140ms ease,
    box-shadow 140ms ease;
}

body:has(.modal-container .modal:not(.mod-settings)) .opencodian-agent-switcher-floating {
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
}

.opencodian-agent-switcher-floating.is-hidden-behind-modal {
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
}

.opencodian-agent-switcher-floating:hover,
.opencodian-agent-switcher-floating:focus-within {
  width: 40px;
  padding: 6px 3px;
  opacity: 1;
  border-color: color-mix(in srgb, var(--interactive-accent) 34%, var(--background-modifier-border-hover));
  background: color-mix(in srgb, var(--background-secondary) 98%, transparent);
  box-shadow:
    inset 1px 0 0 color-mix(in srgb, var(--background-primary) 54%, transparent),
    0 10px 22px color-mix(in srgb, var(--text-normal) 12%, transparent);
}

.opencodian-agent-switcher-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--text-normal);
  cursor: pointer;
  opacity: 0;
  transform: translateX(-8px);
  transition:
    opacity 120ms ease,
    transform 160ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 150ms ease,
    background 150ms ease,
    border-color 150ms ease;
}

.opencodian-agent-switcher-floating:hover .opencodian-agent-switcher-icon,
.opencodian-agent-switcher-floating:focus-within .opencodian-agent-switcher-icon {
  opacity: 1;
  transform: translateX(0);
}

.opencodian-agent-switcher-icon:hover {
  background: color-mix(in srgb, var(--background-modifier-hover) 70%, transparent);
  box-shadow: 0 4px 12px color-mix(in srgb, var(--text-normal) 10%, transparent);
  transform: translateX(0) translateY(-1px);
}

.opencodian-agent-switcher-icon:active {
  transform: scale(0.95);
}

.opencodian-agent-switcher-icon.opencodian-agent-switcher-clicked {
  animation: agent-icon-click 220ms ease;
}

.opencodian-agent-switcher-icon.opencodian-agent-switcher-selected {
  border-color: color-mix(in srgb, var(--interactive-accent) 42%, var(--background-modifier-border-hover));
  background: color-mix(in srgb, var(--interactive-accent) 12%, var(--background-secondary-alt));
}

.opencodian-agent-switcher-icon--lobehub svg {
  display: none;
}

.opencodian-agent-switcher-lobehub-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  pointer-events: none;
}

.opencodian-agent-switcher-lobehub-img {
  display: block;
  width: 18px;
  height: 18px;
  object-fit: contain;
}

.opencodian-agent-switcher-lobehub-img--dark {
  display: none;
}

body.theme-dark .opencodian-agent-switcher-lobehub-img--light {
  display: none;
}

body.theme-dark .opencodian-agent-switcher-lobehub-img--dark {
  display: block;
}

.opencodian-agent-switcher-icon.entering {
  animation: none;
}

.opencodian-agent-switcher-header-icons {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  min-width: 0;
  padding: 1px;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 58%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--background-secondary) 42%, transparent);
}

.opencodian-agent-switcher-header-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: var(--text-normal);
  cursor: pointer;
  transition:
    background 140ms ease,
    border-color 140ms ease,
    box-shadow 140ms ease,
    transform 140ms cubic-bezier(0.22, 1, 0.36, 1);
}

.opencodian-agent-switcher-header-icon:hover {
  background: color-mix(in srgb, var(--background-modifier-hover) 82%, transparent);
  transform: translateY(-1px);
}

.opencodian-agent-switcher-header-icon:active {
  transform: scale(0.95);
}

.opencodian-agent-switcher-header-icon:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

.opencodian-agent-switcher-header-icon.opencodian-agent-switcher-selected {
  border-color: color-mix(in srgb, var(--interactive-accent) 42%, var(--background-modifier-border-hover));
  background: color-mix(in srgb, var(--interactive-accent) 12%, var(--background-secondary-alt));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--interactive-accent) 12%, transparent);
}

.opencodian-agent-switcher-header-icon.opencodian-agent-switcher-clicked {
  animation: agent-icon-click 220ms ease;
}

@keyframes agent-icon-click {
  0% { transform: scale(0.95); }
  60% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

.opencodian-agent-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 0;
}

.opencodian-agent-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 16px;
  background: var(--background-secondary);
  color: var(--text-muted);
  cursor: pointer;
  font-size: 12px;
  transition: background 150ms ease, color 150ms ease;
}

.opencodian-agent-chip:hover {
  background: var(--background-secondary-alt);
}

.opencodian-agent-chip.opencodian-agent-chip-selected {
  border-color: var(--interactive-accent);
  background: var(--interactive-accent);
  color: var(--text-on-accent);
}


/* components/model-selector.css */
/* ============================================================
   Model Selector - Opencode Style
   ============================================================ */

.opencodian-model-selector {
  flex-shrink: 0;
  position: relative;
  display: inline-flex;
  align-items: center;
}

/* Trigger Button */
.opencodian-model-trigger {
  display: flex;
  align-items: center;
  min-height: var(--opencodian-input-toolbar-control-height, 30px);
  padding: 3px 7px;
  border-radius: 999px;
  cursor: pointer;
  background: color-mix(in srgb, var(--background-primary) 54%, transparent);
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 54%, transparent);
  box-shadow: 0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 30%, transparent) inset;
  transition: color 0.15s ease-out, opacity 0.15s ease-out, background-color 0.15s ease-out, border-color 0.15s ease-out, box-shadow 0.15s ease-out, transform 0.15s ease-out;
  user-select: none;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-normal);
}

.opencodian-model-trigger:hover {
  background: color-mix(in srgb, var(--opencodian-composer-embedded-fill) 24%, var(--background-primary));
  border-color: color-mix(in srgb, var(--background-modifier-border) 78%, var(--text-muted));
  color: var(--text-normal);
  transform: translateY(-1px);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--opencodian-glass-shadow-strong) 20%, transparent), 0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 30%, transparent) inset;
}

.opencodian-model-trigger.is-open {
  background: color-mix(in srgb, var(--opencodian-composer-embedded-fill) 24%, transparent);
  border-color: color-mix(in srgb, var(--interactive-accent) 52%, var(--background-modifier-border));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--interactive-accent) 14%, transparent), 0 2px 12px color-mix(in srgb, var(--interactive-accent) 10%, transparent), 0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 30%, transparent) inset;
  transform: translateY(-1px);
}

.opencodian-model-trigger.is-unavailable {
  color: var(--text-warning);
}

.opencodian-model-trigger.is-unconfigured {
  color: var(--text-error);
  background: color-mix(in srgb, var(--text-error) 10%, transparent);
  border-color: color-mix(in srgb, var(--text-error) 26%, var(--background-modifier-border));
}

.opencodian-model-trigger.is-unconfigured:hover,
.opencodian-model-trigger.is-unconfigured.is-open {
  background: color-mix(in srgb, var(--text-error) 14%, transparent);
}

.opencodian-model-trigger-content {
  display: flex;
  align-items: center;
  gap: 5px;
  max-width: 150px;
}

/* Provider Icon - Lobehub SVG icons */
.opencodian-model-trigger-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  opacity: 0.7;
  transition: opacity 0.15s ease;
}

.opencodian-model-trigger:hover .opencodian-model-trigger-icon,
.opencodian-model-trigger.is-open .opencodian-model-trigger-icon {
  opacity: 1;
}

.opencodian-model-trigger-icon img {
  width: 12px;
  height: 12px;
  object-fit: contain;
  /* Invert colors in dark mode for better visibility */
  filter: var(--lobehub-icon-filter, none);
}

.opencodian-model-trigger-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}

.opencodian-model-trigger.is-unconfigured .opencodian-model-trigger-text {
  font-weight: 700;
  letter-spacing: 0.02em;
}

.opencodian-model-trigger.is-unconfigured .opencodian-model-trigger-icon {
  opacity: 1;
}

.opencodian-model-trigger-chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--text-muted);
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), color 0.15s ease;
}

.opencodian-model-trigger:hover .opencodian-model-trigger-chevron {
  color: var(--text-normal);
}

.opencodian-model-trigger.is-open .opencodian-model-trigger-chevron {
  transform: rotate(180deg);
  color: var(--interactive-accent);
}

.opencodian-model-trigger:focus-visible {
  outline: 2px solid var(--background-modifier-border-focus);
  outline-offset: 2px;
}

.opencodian-composer-shell--action-buttons-etched .opencodian-model-trigger {
  padding: 3px 5px;
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  color: color-mix(in srgb, var(--text-normal) 78%, var(--text-muted));
}

.opencodian-composer-shell--action-buttons-etched .opencodian-model-trigger:hover,
.opencodian-composer-shell--action-buttons-etched .opencodian-model-trigger.is-open {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  color: var(--text-normal);
  filter: brightness(1.04) saturate(1.02);
}

.opencodian-composer-shell--action-buttons-etched .opencodian-model-trigger.is-unavailable {
  color: color-mix(in srgb, var(--text-warning) 88%, var(--text-normal));
}

.opencodian-composer-shell--action-buttons-etched .opencodian-model-trigger.is-unconfigured {
  color: color-mix(in srgb, var(--text-error) 88%, var(--text-normal));
}

.opencodian-composer-shell--action-buttons-etched .opencodian-model-trigger:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--interactive-accent) 58%, transparent);
  outline-offset: 3px;
}

.opencodian-model-trigger-chevron svg {
  width: 12px;
  height: 12px;
}

/* Dropdown - Popover style */
.opencodian-model-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 6px;
  box-sizing: border-box;
  width: 340px;
  min-width: 280px;
  max-width: 340px;
  z-index: 1000;
}

.opencodian-model-dropdown .opencodian-composer-popover-frame {
  max-height: 432px;
  display: flex;
  flex-direction: column;
}

.opencodian-model-dropdown .opencodian-composer-popover-content {
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  padding: 0;
}

/*
 * CommandInput strip: one full-width row with a bottom separator.
 * No inner rounded card, no secondary surface; the input shares the
 * shared frame surface directly.
 */
.opencodian-model-dropdown-search {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--background-modifier-border);
  background: transparent;
}

.opencodian-model-dropdown-search-container {
  display: contents;
}

.opencodian-model-dropdown-search-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--text-muted);
}

.opencodian-model-dropdown-search-icon svg {
  width: 14px;
  height: 14px;
}

.opencodian-model-dropdown-search-input {
  flex: 1;
  min-width: 0;
  min-height: 20px;
  padding: 0;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text-normal);
  font-size: 13px;
  line-height: 1.4;
}

.opencodian-model-dropdown-search-input::placeholder {
  color: var(--text-faint);
  opacity: 1;
  font-weight: 400;
}

.opencodian-model-dropdown .opencodian-model-dropdown-search-input {
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
}

/* Scrollable List Container */
.opencodian-model-dropdown-scroll {
  flex: 1 1 auto;
  min-height: 0;
  max-height: 280px;
  padding: 0;
  position: relative;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb-bg) transparent;
}

.opencodian-model-dropdown-scroll::-webkit-scrollbar {
  width: 5px;
}

.opencodian-model-dropdown-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.opencodian-model-dropdown-scroll::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb-bg);
  border-radius: 999px;
}

.opencodian-model-dropdown-scroll::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-active-thumb-bg);
}

/* Loading State */
.opencodian-model-dropdown-loading {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 48px 16px;
  color: var(--text-muted);
  font-size: 13px;
}

/* Empty State */
.opencodian-model-dropdown-empty {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 48px 16px;
  color: var(--text-muted);
  font-size: 13px;
}

/* Groups Container */
.opencodian-model-groups {
  display: block;
  /*
   * Vertical breathing room lives on the inner groups wrapper, not on the
   * scroll container. A scroll-container padding-top would push the
   * sticky provider header's inset to the content-box edge (y=4px),
   * exposing a transparent strip at the scrollport top where model rows
   * bleed through during scroll. Keeping the scrollport edge flush with
   * the first header lets position:sticky clamp to y=0 reliably.
   */
  padding: 4px 0;
}

/* Model Group */
.opencodian-model-group {
  display: block;
}

/*
 * Provider group heading: sticky shadcn CommandGroupHeading-style label.
 * It must read as a group heading, not as a selectable model row and not
 * as placeholder text. Direction A flattens the heading onto the popover
 * surface with a fully opaque --background-primary background and no
 * tonal band or full-width separator; hierarchy comes from icon
 * ownership, the empty shared leading slot, whitespace, and typography.
 * Text uses --text-muted (never --text-faint, which is reserved for the
 * search placeholder) so the provider label stays legible even in
 * pink/saturated light themes.
 */
.opencodian-model-provider-header {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 26px;
  padding: 5px 12px 4px;
  background: var(--background-primary);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0;
  text-transform: none;
}

.opencodian-model-group-options {
  display: block;
  padding: 0 4px;
}

.opencodian-model-provider-header-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 12px;
  height: 12px;
  opacity: 0.55;
}

.opencodian-model-provider-header-icon img,
img.opencodian-model-provider-header-icon {
  /* The renderer injects 14px inline styles; keep the header icon at the
   * contracted 12px spec without touching the TypeScript renderer. */
  width: 12px !important;
  height: 12px !important;
  object-fit: contain;
  filter: var(--lobehub-icon-filter, none);
}

.opencodian-model-provider-header-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Model Option */
.opencodian-model-option {
  width: 100%;
  color: var(--text-normal);
  cursor: pointer;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.35;
  user-select: none;
}

.opencodian-model-option-name {
  grid-column: 2;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 400;
}

.opencodian-model-option.is-selected .opencodian-model-option-name {
  font-weight: 600;
}

.opencodian-model-option-check {
  grid-column: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  color: var(--interactive-accent);
  opacity: 0;
}

.opencodian-model-option.is-selected .opencodian-model-option-check {
  color: var(--text-normal);
  opacity: 1;
}

.opencodian-model-option-icon {
  grid-column: 1;
}

.opencodian-model-option.is-configured-only {
  grid-template-columns: 22px minmax(0, 1fr) auto 18px;
  color: var(--text-muted);
  cursor: default;
  opacity: 0.72;
}

.opencodian-model-option.is-configured-only:hover,
.opencodian-model-option.is-configured-only.is-highlighted,
.opencodian-model-option.is-configured-only.is-selected {
  background: transparent;
}

.opencodian-model-option.is-configured-only .opencodian-model-option-check {
  grid-column: 4;
}

.opencodian-model-option-availability {
  grid-column: 3;
  min-width: 48px;
  padding: 2px 5px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 4px;
  background: var(--background-secondary);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.2;
  text-align: center;
  white-space: nowrap;
}

/* Settings */
.vertical-tab-content:has(.opencodian-settings),
.vertical-tab-content-container:has(.opencodian-settings) {
  padding-top: 0 !important;
}

/* Settings in editor-area leaf */
.workspace-leaf-content[data-type="opencodian-settings-view"] > .view-content.opencodian-settings {
  padding: 12px 48px 32px !important;
}
.workspace-leaf-content[data-type="opencodian-settings-view"] > .view-content.opencodian-settings.opencodian-settings--classic {
  padding-top: 0 !important;
}
.workspace-leaf-content[data-type="opencodian-settings-view"] > .view-content.opencodian-settings.opencodian-settings--tabbed .opencodian-settings-panel-title {
  margin-left: 0 !important;
}

.opencodian-settings {
  --opencodian-settings-scrollbar-size: 8px;
  --opencodian-settings-scrollbar-radius: 999px;
  --opencodian-settings-scrollbar-track:
    color-mix(in srgb, var(--background-secondary-alt, var(--background-secondary)) 22%, transparent);
  --opencodian-settings-scrollbar-track-border:
    color-mix(in srgb, var(--background-modifier-border) 28%, transparent);
  --opencodian-settings-scrollbar-thumb:
    color-mix(in srgb, var(--scrollbar-thumb-bg, rgba(var(--mono-rgb-100), 0.15)) 68%, transparent);
  --opencodian-settings-scrollbar-thumb-soft:
    color-mix(in srgb, var(--scrollbar-thumb-bg, rgba(var(--mono-rgb-100), 0.15)) 44%, transparent);
  --opencodian-settings-scrollbar-thumb-hover:
    color-mix(in srgb, var(--scrollbar-active-thumb-bg, rgba(var(--mono-rgb-100), 0.35)) 82%, transparent);
  --opencodian-settings-scrollbar-specular:
    color-mix(in srgb, var(--background-primary) 68%, transparent);
  --opencodian-settings-scrollbar-shadow:
    color-mix(in srgb, var(--background-modifier-border-hover) 46%, transparent);
  overflow-y: auto;
  max-height: 100%;
  padding-right: 6px;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: var(--opencodian-settings-scrollbar-thumb) transparent;
  padding: 0 20px 20px;
}

.opencodian-settings.opencodian-settings--tabbed .opencodian-settings-panel-title {
  justify-content: space-between;
}

.opencodian-settings:hover {
  scrollbar-color: var(--opencodian-settings-scrollbar-thumb-hover) transparent;
}

.opencodian-settings::-webkit-scrollbar {
  width: var(--opencodian-settings-scrollbar-size);
  height: var(--opencodian-settings-scrollbar-size);
}

.opencodian-settings::-webkit-scrollbar-track {
  background: var(--opencodian-settings-scrollbar-track);
  border-radius: var(--opencodian-settings-scrollbar-radius);
  box-shadow: inset 0 0 0 1px var(--opencodian-settings-scrollbar-track-border);
}

.opencodian-settings::-webkit-scrollbar-thumb {
  background:
    linear-gradient(
      180deg,
      var(--opencodian-settings-scrollbar-specular) 0%,
      color-mix(in srgb, var(--opencodian-settings-scrollbar-specular) 42%, transparent) 22%,
      transparent 100%
    ),
    linear-gradient(
      180deg,
      var(--opencodian-settings-scrollbar-thumb) 0%,
      var(--opencodian-settings-scrollbar-thumb-soft) 100%
    );
}

/* Settings tooltip layer — body-level fixed overlay for [data-settings-tooltip] triggers */
.opencodian-settings-tooltip-layer {
  position: fixed;
  top: 0;
  left: 0;
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  z-index: 2300;
  transition: opacity 0.12s ease;
}

.opencodian-settings-tooltip-layer.is-visible {
  opacity: 1;
  visibility: visible;
}

.opencodian-settings-tooltip-bubble {
  width: max-content;
  max-width: min(240px, calc(100vw - 32px));
  padding: 7px 10px;
  border-radius: 8px;
  background: rgba(12, 12, 12, 0.94);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: #fff;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.3;
  text-align: left;
  white-space: pre-wrap;
  overflow-wrap: break-word;
  word-break: normal;
  box-shadow: none;
}

.opencodian-settings-tooltip-arrow {
  position: absolute;
  width: 8px;
  height: 8px;
  background: rgba(12, 12, 12, 0.94);
  transform: rotate(45deg);
}

.opencodian-settings-tooltip-layer[data-placement="top"] .opencodian-settings-tooltip-arrow {
  bottom: -4px;
  left: var(--opencodian-settings-tooltip-arrow-offset, 16px);
  border-right: 1px solid rgba(255, 255, 255, 0.08);
