  position: relative;
  min-height: 136px;
  border-radius: 12px;
  overflow: hidden;
  background:
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--background-modifier-border-hover) 46%, transparent),
      color-mix(in srgb, var(--background-primary) 86%, transparent)
    );
  border: 1px solid color-mix(in srgb, var(--background-modifier-border-hover) 72%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 18%, transparent);
}

.opencodian-theme-background-preview.is-draggable {
  cursor: grab;
}

.opencodian-theme-background-preview.is-dragging {
  cursor: grabbing;
}

.opencodian-theme-background-preview.is-loading::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      transparent 0%,
      color-mix(in srgb, white 24%, transparent) 50%,
      transparent 100%
    );
  transform: translateX(-100%);
  animation: opencodian-theme-background-shimmer 1.3s ease-in-out infinite;
}

.opencodian-theme-background-preview-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  text-align: center;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-muted);
}

.opencodian-theme-background-preview-image,
.opencodian-theme-background-preview-overlay {
  position: absolute;
  inset: 0;
}

.opencodian-theme-background-preview-image {
  width: 100%;
  height: 100%;
  background-repeat: no-repeat;
  transform-origin: center;
  -webkit-mask-image: radial-gradient(
    140% 122% at 50% 50%,
    rgba(0, 0, 0, 1) calc(100% - var(--opencodian-theme-background-preview-edge-fade)),
    rgba(0, 0, 0, 0.82) calc(100% - (var(--opencodian-theme-background-preview-edge-fade) * 0.52)),
    rgba(0, 0, 0, 0.2) calc(100% - (var(--opencodian-theme-background-preview-edge-fade) * 0.12)),
    transparent 100%
  );
  -webkit-mask-repeat: no-repeat;
  mask-image: radial-gradient(
    140% 122% at 50% 50%,
    rgba(0, 0, 0, 1) calc(100% - var(--opencodian-theme-background-preview-edge-fade)),
    rgba(0, 0, 0, 0.82) calc(100% - (var(--opencodian-theme-background-preview-edge-fade) * 0.52)),
    rgba(0, 0, 0, 0.2) calc(100% - (var(--opencodian-theme-background-preview-edge-fade) * 0.12)),
    transparent 100%
  );
  mask-repeat: no-repeat;
}

.opencodian-theme-background-preview-overlay {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-secondary) 26%, transparent) 0%,
      color-mix(in srgb, var(--background-secondary) 10%, transparent) 100%
    );
  pointer-events: none;
}

.opencodian-theme-background-meta {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.opencodian-theme-background-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-normal);
}

.opencodian-theme-background-copy {
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-muted);
}

.opencodian-theme-background-note {
  font-size: 11px;
  line-height: 1.45;
  color: var(--text-faint, var(--text-muted));
}

.opencodian-theme-background-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
}

.opencodian-theme-reset-btn[disabled] {
  opacity: 0.5;
  cursor: default;
}

@keyframes opencodian-theme-background-shimmer {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(100%);
  }
}

.opencodian-style-section .opencodian-style-group > .opencodian-style-group-title {
  display: block;
  width: 100%;
  margin: 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text-muted);
  padding-left: 0;
  text-indent: 0;
  line-height: 1.35;
  text-align: left;
}

.opencodian-style-section .opencodian-style-group > .opencodian-style-group-desc {
  display: block;
  width: 100%;
  margin: 0;
  font-size: 11px;
  line-height: 1.35;
  color: var(--text-muted);
  padding-left: 0;
  text-indent: 0;
  text-align: left;
}

/* The (0,4,0) selector variants keep these columns authoritative inside
   settings sections/content shells, where the general form-row contract
   (0,3,0) would otherwise override them. Container-relative floors keep
   the label column from collapsing to zero width in narrow panes. */
.opencodian-style-setting,
.opencodian-settings .opencodian-settings-section .opencodian-style-setting.setting-item,
.opencodian-settings .opencodian-settings-content-shell .opencodian-style-setting.setting-item {
  display: grid;
  grid-template-columns: minmax(min(180px, 45%), 1fr) minmax(min(360px, 55%), 360px);
  column-gap: 20px;
  row-gap: var(--opencodian-settings-space-md, 8px);
  align-items: center;
}

.opencodian-style-setting.opencodian-style-setting-long-text,
.opencodian-settings .opencodian-settings-section .opencodian-style-setting.opencodian-style-setting-long-text.setting-item,
.opencodian-settings .opencodian-settings-content-shell .opencodian-style-setting.opencodian-style-setting-long-text.setting-item {
  grid-template-columns: minmax(min(180px, 45%), 1fr) minmax(min(360px, 55%), min(520px, 100%));
}

.opencodian-style-setting .setting-item-control {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  width: 100%;
  min-width: 0;
  max-width: 360px;
}

.opencodian-style-setting.opencodian-style-setting-long-text .setting-item-control {
  width: 100%;
  min-width: 0;
  max-width: 520px;
}

.opencodian-style-setting .setting-item-info,
.opencodian-style-reset-setting .setting-item-info {
  padding-left: 0;
}

.opencodian-style-setting .setting-item-info {
  min-width: 0;
  padding-right: 8px;
}

.opencodian-style-group-body .setting-item:first-child {
  border-top: none;
}

.opencodian-style-setting-control {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  flex-wrap: nowrap;
  justify-content: flex-end;
}

.opencodian-style-step-btn,
.opencodian-style-reset-btn {
  display: inline-flex;
  flex: 0 0 28px;
  align-items: center;
  justify-content: center;
  width: 28px;
  min-width: 28px;
  max-width: 28px;
  height: 28px;
  padding: 0;
  box-sizing: border-box;
  border-radius: 8px;
  border: 1px solid var(--background-modifier-border);
  background: var(--button-background);
  color: var(--button-text-color);
  cursor: pointer;
  font-size: 15px;
  line-height: 1;
  transition: background-color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.opencodian-style-step-btn:hover,
.opencodian-style-reset-btn:hover {
  background: var(--button-background-hover);
  border-color: var(--background-modifier-border-hover);
  transform: translateY(-1px);
}

.opencodian-style-slider {
  appearance: none;
  -webkit-appearance: none;
  flex: 0 0 160px;
  width: 160px;
  min-width: 160px;
  max-width: 160px;
  height: 28px;
  margin: 0;
  background: transparent;
  cursor: pointer;
  accent-color: var(--interactive-accent);
}

.opencodian-style-slider:focus {
  outline: none;
}

.opencodian-style-slider::-webkit-slider-runnable-track {
  height: 8px;
  border-radius: 999px;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-modifier-border-hover) 72%, transparent) 0%,
      color-mix(in srgb, var(--background-modifier-border) 88%, transparent) 100%
    );
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 88%, transparent);
}

.opencodian-style-slider::-webkit-slider-thumb {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  margin-top: -6px;
  border-radius: 999px;
  border: 2px solid var(--background-primary);
  background:
    radial-gradient(circle at 30% 30%, var(--background-primary) 0%, transparent 35%),
    var(--interactive-accent);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--interactive-accent) 55%, var(--background-modifier-border)),
    0 3px 10px color-mix(in srgb, var(--interactive-accent) 24%, transparent);
  transition: transform 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
}

.opencodian-style-slider:hover::-webkit-slider-thumb {
  transform: scale(1.06);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--interactive-accent) 70%, var(--background-modifier-border-hover)),
    0 4px 12px color-mix(in srgb, var(--interactive-accent) 28%, transparent);
}

.opencodian-style-slider:focus-visible::-webkit-slider-thumb {
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--interactive-accent) 24%, var(--background-primary)),
    0 0 0 4px color-mix(in srgb, var(--interactive-accent) 16%, transparent),
    0 4px 12px color-mix(in srgb, var(--interactive-accent) 28%, transparent);
}

.opencodian-style-slider::-moz-range-track {
  height: 8px;
  border-radius: 999px;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-modifier-border-hover) 72%, transparent) 0%,
      color-mix(in srgb, var(--background-modifier-border) 88%, transparent) 100%
    );
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 88%, transparent);
}

.opencodian-style-slider::-moz-range-progress {
  height: 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--interactive-accent) 72%, var(--background-modifier-border-hover));
}

.opencodian-style-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 999px;
  border: 2px solid var(--background-primary);
  background:
    radial-gradient(circle at 30% 30%, var(--background-primary) 0%, transparent 35%),
    var(--interactive-accent);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--interactive-accent) 55%, var(--background-modifier-border)),
    0 3px 10px color-mix(in srgb, var(--interactive-accent) 24%, transparent);
  transition: transform 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
}

.opencodian-style-slider:hover::-moz-range-thumb {
  transform: scale(1.06);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--interactive-accent) 70%, var(--background-modifier-border-hover)),
    0 4px 12px color-mix(in srgb, var(--interactive-accent) 28%, transparent);
}

.opencodian-style-slider:focus-visible::-moz-range-thumb {
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--interactive-accent) 24%, var(--background-primary)),
    0 0 0 4px color-mix(in srgb, var(--interactive-accent) 16%, transparent),
    0 4px 12px color-mix(in srgb, var(--interactive-accent) 28%, transparent);
}

.opencodian-style-number-wrap {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
  padding: 0 6px;
  min-width: 78px;
  height: 28px;
  border-radius: 8px;
  border: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
  box-sizing: border-box;
}

.opencodian-style-number {
  flex: 0 0 var(--opencodian-style-number-width, calc(4ch + 1.8em));
  width: var(--opencodian-style-number-width, calc(4ch + 1.8em));
  min-width: var(--opencodian-style-number-width, calc(4ch + 1.8em));
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-normal);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.opencodian-style-number:focus {
  outline: none;
}

.opencodian-style-color-control {
  position: relative;
}

.opencodian-style-color-preview,
.opencodian-style-secondary-btn {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  height: 28px;
  padding: 0 10px;
  box-sizing: border-box;
  border-radius: 8px;
  border: 1px solid var(--background-modifier-border);
  background: var(--button-background);
  color: var(--button-text-color);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.opencodian-style-color-preview:hover,
.opencodian-style-secondary-btn:hover {
  background: var(--button-background-hover);
  border-color: var(--background-modifier-border-hover);
  transform: translateY(-1px);
}

.opencodian-style-color-preview {
  width: 28px;
  min-width: 28px;
  padding: 0;
  background:
    linear-gradient(45deg, rgb(255 255 255 / 0.72) 25%, transparent 25%, transparent 75%, rgb(255 255 255 / 0.72) 75%),
    linear-gradient(45deg, rgb(255 255 255 / 0.72) 25%, transparent 25%, transparent 75%, rgb(255 255 255 / 0.72) 75%);
  background-position: 0 0, 6px 6px;
  background-size: 12px 12px;
}

.opencodian-style-color-value {
  display: inline-flex;
  flex: 1 1 auto;
  align-items: center;
  min-width: 0;
  height: 28px;
  padding: 0 8px;
  border-radius: 8px;
  border: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
  color: var(--text-muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  box-sizing: border-box;
}

.opencodian-style-color-input {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  border: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(100%);
  white-space: nowrap;
}

.opencodian-style-unit {
  font-size: 12px;
  color: var(--text-muted);
  white-space: nowrap;
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  .opencodian-model-dropdown-search-container,
  .opencodian-model-dropdown-scroll::-webkit-scrollbar-thumb,
  .opencodian-model-provider-header,
  .opencodian-model-option-check,
  .opencodian-model-trigger,
  .opencodian-model-trigger-chevron {
    transition: none !important;
    animation: none !important;
  }

  .opencodian-model-trigger:hover {
    transform: none !important;
  }

  .opencodian-model-trigger.is-open {
    transform: none !important;
  }

  .opencodian-model-option.is-selected .opencodian-model-option-check {
    transform: none !important;
  }
}

@media (max-width: 900px) {
  .opencodian-theme-style-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .opencodian-theme-background-card {
    grid-template-columns: 1fr;
  }

  .opencodian-theme-background-preview {
    min-height: 168px;
  }

  .opencodian-style-setting {
    grid-template-columns: 1fr;
  }

  .opencodian-style-setting .setting-item-control {
    width: 100%;
    min-width: 0;
    max-width: none;
    justify-content: flex-start;
  }

  .opencodian-style-setting-control {
    justify-content: flex-start;
    flex-wrap: wrap;
  }
}

@media (max-width: 560px) {
  .opencodian-theme-style-grid {
    grid-template-columns: 1fr;
  }
}

.opencodian-style-reset-setting .setting-item-info {
  opacity: 0.82;
}

.opencodian-style-reset-setting {
  margin-top: 24px;
  padding-top: 24px;
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-style-reset-setting button {
  background: var(--button-background);
  color: var(--button-text-color);
  border: 1px solid var(--background-modifier-border);
}

.opencodian-style-reset-setting button:hover {
  background: var(--button-background-hover);
  border-color: var(--background-modifier-border-hover);
}

.opencodian-style-textarea {
  width: min(520px, 100%);
  font-family: var(--font-monospace);
}

.opencodian-style-textarea.is-invalid {
  border-color: var(--text-error);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--text-error) 24%, transparent);
}

.opencodian-style-validation {
  margin-top: 6px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--text-error);
}

/* Scrollbar styling - apply to scroll container */
.opencodian-messages-scroll,
.opencodian-messages,
.opencodian-history-scroll {
  scrollbar-width: thin;
  scrollbar-color:
    color-mix(
      in srgb,
      var(--scrollbar-thumb-bg, var(--background-modifier-border)) var(--opencodian-scrollbar-thumb-opacity),
      transparent
    )
    color-mix(
      in srgb,
      var(--background-secondary-alt, var(--background-secondary)) var(--opencodian-scrollbar-track-opacity),
      transparent
    );
}

.opencodian-messages-scroll:hover,
.opencodian-messages:hover,
.opencodian-history-scroll:hover {
  scrollbar-color:
    color-mix(
      in srgb,
      var(--scrollbar-active-thumb-bg, var(--background-modifier-border-hover)) var(--opencodian-scrollbar-thumb-hover-opacity),
      transparent
    )
    color-mix(
      in srgb,
      var(--background-secondary-alt, var(--background-secondary)) var(--opencodian-scrollbar-track-opacity),
      transparent
    );
}

.opencodian-messages-scroll::-webkit-scrollbar,
.opencodian-messages::-webkit-scrollbar,
.opencodian-history-scroll::-webkit-scrollbar {
  width: var(--opencodian-scrollbar-width);
  height: var(--opencodian-scrollbar-width);
}

.opencodian-messages-scroll::-webkit-scrollbar-track,
.opencodian-messages::-webkit-scrollbar-track,
.opencodian-history-scroll::-webkit-scrollbar-track {
  background: color-mix(
    in srgb,
    var(--background-secondary-alt, var(--background-secondary)) var(--opencodian-scrollbar-track-opacity),
    transparent
  );
  border-radius: var(--opencodian-scrollbar-radius);
}

.opencodian-messages-scroll::-webkit-scrollbar-thumb,
.opencodian-messages::-webkit-scrollbar-thumb,
.opencodian-history-scroll::-webkit-scrollbar-thumb {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-primary) 72%, transparent) 0%,
      color-mix(in srgb, var(--background-primary) 28%, transparent) 26%,
      transparent 100%
    ),
    linear-gradient(
      180deg,
      color-mix(
        in srgb,
        var(--scrollbar-thumb-bg, var(--background-modifier-border)) var(--opencodian-scrollbar-thumb-opacity),
        transparent
      ) 0%,
      color-mix(
        in srgb,
        var(--scrollbar-thumb-bg, var(--background-modifier-border)) 38%,
        transparent
      ) 100%
    );
  border-radius: var(--opencodian-scrollbar-radius);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--background-primary) 72%, transparent),
    0 2px 8px color-mix(
      in srgb,
      var(--background-modifier-border-hover) var(--opencodian-scrollbar-shadow-opacity),
      transparent
    );
}

.opencodian-messages-scroll::-webkit-scrollbar-thumb:hover,
.opencodian-messages::-webkit-scrollbar-thumb:hover,
.opencodian-history-scroll::-webkit-scrollbar-thumb:hover {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-primary) 88%, transparent) 0%,
      color-mix(in srgb, var(--background-primary) 36%, transparent) 22%,
      transparent 100%
    ),
    linear-gradient(
      180deg,
      color-mix(
        in srgb,
        var(--scrollbar-active-thumb-bg, var(--background-modifier-border-hover)) var(--opencodian-scrollbar-thumb-hover-opacity),
        transparent
      ) 0%,
      color-mix(
        in srgb,
        var(--scrollbar-active-thumb-bg, var(--background-modifier-border-hover)) 46%,
        transparent
      ) 100%
    );
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--background-primary) 84%, transparent),
    0 3px 10px color-mix(
      in srgb,
      var(--background-modifier-border-hover) var(--opencodian-scrollbar-shadow-opacity),
      transparent
    );
}


/* components/permission-mode-selector.css */
/* ============================================================
   Permission Mode Selector
   ============================================================ */

.opencodian-permission-selector {
  flex-shrink: 0;
  position: relative;
  display: inline-flex;
  align-items: center;
}

/* Trigger Button */
.opencodian-permission-trigger {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: var(--opencodian-input-toolbar-control-height, 30px);
  padding: 4px 10px;
  border-radius: 8px;
  cursor: pointer;
  background: color-mix(in srgb, var(--background-primary) 54%, transparent);
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 54%, transparent);
  box-shadow: 0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 30%, transparent) inset;
  transition: color 0.15s ease-out, opacity 0.15s ease-out, background-color 0.15s ease-out, border-color 0.15s ease-out, box-shadow 0.15s ease-out, transform 0.15s ease-out;
  user-select: none;
  font-size: 13px;
  color: var(--text-muted);
}

.opencodian-permission-trigger:hover {
  background: color-mix(in srgb, var(--opencodian-composer-embedded-fill) 24%, var(--background-primary));
  border-color: color-mix(in srgb, var(--background-modifier-border) 78%, var(--text-muted));
  color: var(--text-normal);
  transform: translateY(-1px);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--opencodian-glass-shadow-strong) 20%, transparent), 0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 30%, transparent) inset;
}

.opencodian-permission-trigger.is-open {
  background: color-mix(in srgb, var(--opencodian-composer-embedded-fill) 24%, transparent);
  border-color: color-mix(in srgb, var(--interactive-accent) 52%, var(--background-modifier-border));
