/* Permission Dropdown - Linear glass style */
.opencodian-permission-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 4px;
  box-sizing: border-box;
  width: 280px;
  min-width: 220px;
  max-width: 280px;
  z-index: 1000;
}

/* Dropdown option items */
.opencodian-permission-option {
  width: 100%;
  cursor: pointer;
  font-size: 13px;
  color: var(--text-normal);
  user-select: none;
}

/*
 * Permission semantics: danger/safe only color the icon, check, and
 * compact label — never the full row. The selected row shares the
 * same neutral `--background-modifier-hover` surface as every other
 * Command item; no rail, outline, box-shadow, or row tint is allowed.
 *
 * The accent color is exposed as a CSS variable on the semantic scope
 * and consumed by `.is-selected` descendants, so the danger/safe tint
 * never depends on combining `data-permission-semantic` and the
 * selected state in a single selector.
 */
.opencodian-permission-option[data-permission-semantic='danger'] {
  --opencodian-permission-option-accent: var(--background-modifier-error);
}

.opencodian-permission-option[data-permission-semantic='safe'] {
  --opencodian-permission-option-accent: var(--background-modifier-success);
}

.opencodian-permission-option.is-selected .opencodian-permission-option-icon,
.opencodian-permission-option.is-selected .opencodian-permission-option-check,
.opencodian-permission-option.is-selected .opencodian-permission-option-label {
  color: var(--opencodian-permission-option-accent, var(--interactive-accent));
}

.opencodian-permission-option.is-selected .opencodian-permission-option-label {
  font-weight: 600;
}

.opencodian-permission-option-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  margin-top: 1px;
  color: var(--text-muted);
  transition: color 0.15s ease;
}

.opencodian-permission-option:hover .opencodian-permission-option-icon {
  color: var(--text-normal);
}

.opencodian-permission-option-icon svg {
  width: 14px;
  height: 14px;
}

.opencodian-permission-option-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.opencodian-permission-option-label {
  font-weight: 500;
  color: var(--text-normal);
  line-height: 1.3;
}

.opencodian-permission-option-desc {
  font-size: 11px;
  color: var(--text-muted);
  line-height: 1.3;
}

.opencodian-permission-option-check {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  color: var(--interactive-accent);
  opacity: 0;
  transition: opacity 0.12s ease;
}

.opencodian-permission-option.is-selected .opencodian-permission-option-check {
  opacity: 1;
}

.opencodian-permission-option-check svg {
  width: 14px;
  height: 14px;
}

.opencodian-permission-option[data-mode="yolo"] .opencodian-permission-option-icon {
  color: color-mix(in srgb, var(--background-modifier-success) 78%, var(--text-muted));
}

.opencodian-permission-option[data-mode="plan"] .opencodian-permission-option-icon {
  color: color-mix(in srgb, var(--background-modifier-error) 78%, var(--text-muted));
}

.opencodian-permission-option[data-mode="normal"] .opencodian-permission-option-icon {
  color: color-mix(in srgb, var(--interactive-accent) 78%, var(--text-muted));
}

/* Stagger animation for options on dropdown open */
/* Custom thin scrollbar for dropdown */
.opencodian-permission-dropdown {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--scrollbar-thumb-bg, var(--background-modifier-border)) 44%, transparent) transparent;
}

.opencodian-permission-dropdown::-webkit-scrollbar {
  width: 5px;
}

.opencodian-permission-dropdown::-webkit-scrollbar-track {
  background: transparent;
}

.opencodian-permission-dropdown::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--scrollbar-thumb-bg, var(--background-modifier-border)) 42%, transparent);
  border-radius: 999px;
  transition: background 0.15s ease;
}

.opencodian-permission-dropdown::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--scrollbar-active-thumb-bg, var(--background-modifier-border-hover)) 62%, transparent);
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  .opencodian-permission-trigger,
  .opencodian-permission-trigger-chevron,
  .opencodian-permission-option,
  .opencodian-permission-option-check,
  .opencodian-permission-option-icon {
    transition: none !important;
    animation: none !important;
    transform: none !important;
  }

  .opencodian-permission-trigger:hover {
    transform: none !important;
  }

  .opencodian-permission-trigger.is-open {
    transform: none !important;
  }
}

