/* ============================================================
   History Dropdown Styles
   ============================================================ */

.opencodian-history-dropdown {
  background:
    linear-gradient(
      180deg,
      var(--opencodian-glass-specular) 0%,
      color-mix(in srgb, var(--opencodian-glass-specular-soft) 88%, transparent) 42%,
      transparent 100%
    ),
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--opencodian-glass-base-strong) 98%, transparent) 0%,
      color-mix(in srgb, var(--opencodian-glass-base) 84%, transparent) 100%
    ),
    radial-gradient(
      circle at top,
      var(--opencodian-glass-highlight) 0%,
      transparent 68%
    );
  border: 1px solid var(--opencodian-glass-border);
  border-radius: 14px;
  backdrop-filter: blur(22px) saturate(1.2);
  -webkit-backdrop-filter: blur(22px) saturate(1.2);
  box-shadow:
    0 18px 42px var(--opencodian-glass-shadow-strong),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 92%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border) 52%, transparent) inset;
  min-width: 240px;
  max-width: 320px;
  max-height: 400px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.opencodian-history-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 6px 0;
  padding-right: var(--opencodian-scrollbar-edge-padding);
  min-height: 0;
  scrollbar-gutter: stable;
}

/* Scope label - styled as a subtle section header */
.opencodian-history-scope {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: color-mix(in srgb, var(--text-muted) 74%, var(--text-normal) 26%);
  padding: 6px 14px 8px;
  margin-bottom: 2px;
  line-height: 1.2;
}

.opencodian-history-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease;
  border-left: 3px solid transparent;
}

.opencodian-history-item:hover {
  background: var(--opencodian-highlight);
}

.opencodian-history-item.is-active {
  background: var(--opencodian-highlight-soft);
  border-left-color: var(--text-accent);
}

.opencodian-history-item.is-selected {
  background: var(--opencodian-highlight);
}

.opencodian-history-item.is-active.is-selected {
  background: var(--opencodian-highlight-strong);
  border-left-color: var(--text-accent);
}

.opencodian-history-item-checkbox {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
}

.opencodian-history-item-checkbox input {
  width: 14px;
  height: 14px;
  margin: 0;
  cursor: pointer;
  accent-color: var(--text-accent);
}

.opencodian-history-item-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  color: var(--text-muted);
}

.opencodian-history-item.is-active .opencodian-history-item-icon {
  color: var(--text-accent);
}

.opencodian-history-item-icon svg {
  width: 14px;
  height: 14px;
}

.opencodian-history-item-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.opencodian-history-item-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.opencodian-history-item-title {
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--text-normal);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.opencodian-history-item-date {
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--text-faint, var(--text-muted));
}

.opencodian-history-item-status {
  font-size: 10px;
  font-weight: 500;
  line-height: 1;
  padding: 2px 6px;
  border-radius: 4px;
  white-space: nowrap;
}

.opencodian-history-item-status.is-pending {
  color: var(--opencodian-status-warning);
  background: var(--opencodian-status-warning-subtle);
  border: 1px solid var(--opencodian-status-warning-border);
}

.opencodian-history-item-status.is-failed {
  color: var(--opencodian-status-error);
  background: var(--opencodian-status-error-subtle);
  border: 1px solid var(--opencodian-status-error-border);
}

.opencodian-history-item-controls {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.opencodian-history-item-edit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.opencodian-history-item-edit:hover {
  background: var(--opencodian-highlight);
  border-color: var(--opencodian-border-soft);
  color: var(--text-normal);
}

.opencodian-history-item-edit svg {
  width: 14px;
  height: 14px;
}

.opencodian-history-separator {
  height: 1px;
  background: var(--opencodian-border-soft);
  margin: 4px 12px;
}

.opencodian-history-actions {
  padding: 4px 0;
}

.opencodian-history-action {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  cursor: pointer;
  transition: background-color 0.15s ease;
  color: var(--text-muted);
}

.opencodian-history-action:hover {
  background: var(--opencodian-highlight);
  color: var(--text-normal);
}

.opencodian-history-action-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
}

.opencodian-history-action-icon svg {
  width: 14px;
  height: 14px;
}

.opencodian-history-action-text {
  font-size: 13px;
}

/* Fixed footer for delete actions */
.opencodian-history-footer {
  flex-shrink: 0;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-secondary) 52%, transparent),
      color-mix(in srgb, var(--background-primary) 96%, transparent)
    ),
    transparent;
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-top: 1px solid var(--opencodian-border-soft);
}

.opencodian-history-footer .opencodian-history-separator {
  display: none;
}


/* components/relevant-notes.css */
/* ── Relevant notes side panel (advantage-parity R-E3) ─────────────────── */

.opencodian-relevant-notes {
  padding: 12px 10px;
  font-size: var(--font-ui-small, 13px);
  color: var(--text-normal);
}

.opencodian-relevant-notes-header {
  margin-bottom: 12px;
}

.opencodian-relevant-notes-title {
  font-size: var(--font-ui-medium, 14px);
  font-weight: 700;
  color: var(--text-normal);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-relevant-notes-subtitle {
  margin-top: 2px;
  font-size: var(--font-ui-smaller, 11px);
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-relevant-notes-section {
  margin-bottom: 14px;
}

.opencodian-relevant-notes-section-title {
  font-size: var(--font-ui-small, 13px);
  font-weight: 700;
  color: var(--text-normal);
}

.opencodian-relevant-notes-section-desc {
  margin: 2px 0 8px;
  font-size: var(--font-ui-smaller, 11px);
  color: var(--text-muted);
}

.opencodian-relevant-notes-hint {
  padding: 8px 10px;
  border-radius: var(--radius-s, 4px);
  background-color: var(--background-secondary);
  color: var(--text-muted);
  font-size: var(--font-ui-smaller, 11px);
}

.opencodian-relevant-notes-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.opencodian-relevant-notes-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-radius: var(--radius-s, 4px);
  cursor: pointer;
}

.opencodian-relevant-notes-item:hover {
  background-color: var(--background-modifier-hover);
}

.opencodian-relevant-notes-item-content {
  min-width: 0;
  flex: 1;
}

.opencodian-relevant-notes-item-title {
  color: var(--text-normal);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-relevant-notes-item-meta {
  margin-top: 1px;
  font-size: var(--font-ui-smaller, 11px);
  color: var(--text-muted);
}

.opencodian-relevant-notes-item-attach {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: var(--radius-s, 4px);
  background-color: transparent;
  color: var(--text-muted);
  cursor: pointer;
}

.opencodian-relevant-notes-item-attach:hover {
  background-color: var(--background-modifier-hover);
  color: var(--text-normal);
}

.opencodian-relevant-notes-empty {
  padding: 16px 12px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller, 11px);
  text-align: center;
}


/* components/queued-followup-bar.css */
/* ── Queued follow-up message bar (advantage-parity R-F1) ──────────────── */

.opencodian-queued-followup-bar {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 6px;
  padding: 8px 10px;
  border-radius: var(--radius-m, 6px);
  background-color: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
}

.opencodian-queued-followup-bar.is-hidden {
  display: none;
}

.opencodian-queued-followup-title {
  font-size: var(--font-ui-smaller, 11px);
  font-weight: 700;
  color: var(--text-muted);
}

.opencodian-queued-followup-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.opencodian-queued-followup-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: var(--radius-s, 4px);
  background-color: var(--background-primary);
}

.opencodian-queued-followup-item-content {
  flex: 1;
  min-width: 0;
  font-size: var(--font-ui-smaller, 11px);
  color: var(--text-normal);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

button.opencodian-queued-followup-action {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: var(--radius-s, 4px);
  background-color: transparent;
  color: var(--text-muted);
  cursor: pointer;
}

button.opencodian-queued-followup-action:hover {
  background-color: var(--background-modifier-hover);
  color: var(--text-normal);
}

/*
 * The chat surface remaps --interactive-accent into the plugin's monochrome
 * accent family (src/style/base/core.css), so a hue-only distinction from
 * the retract button is not achievable there. The steer affordance is a
 * filled accent chip instead — structurally distinct in mono and colored
 * themes alike, mirroring the send button's accent treatment.
 */
button.opencodian-queued-followup-steer {
  background-color: var(--interactive-accent);
  color: var(--text-on-accent);
}

button.opencodian-queued-followup-steer:hover {
  background-color: var(--interactive-accent-hover);
  color: var(--text-on-accent);
}

.opencodian-queued-followup-status {
  font-size: var(--font-ui-smaller, 11px);
  color: var(--text-faint);
}


/* components/context-window-override-modal.css */
/* ── Context window override modal (advantage-parity R-F8) ─────────────── */

.opencodian-context-window-override-form {
  display: flex;
  gap: 6px;
  margin-bottom: 12px;
}

.opencodian-context-window-override-form input {
  flex: 1;
  min-width: 0;
}

.opencodian-context-window-override-form input[type='number'] {
  max-width: 120px;
  flex: none;
}

.opencodian-context-window-override-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.opencodian-context-window-override-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border-radius: var(--radius-s, 4px);
  background-color: var(--background-secondary);
}

.opencodian-context-window-override-ref {
  flex: 1;
  min-width: 0;
  font-family: var(--font-monospace);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-context-window-override-window {
  flex: none;
  color: var(--text-muted);
}

.opencodian-context-window-override-empty {
  color: var(--text-muted);
  font-size: var(--font-ui-smaller, 11px);
  padding: 8px 0;
}


/* components/environment-variables-modal.css */
/* ── Environment variables domains modal (advantage-parity R-F7) ────────── */

.opencodian-env-domains-section-title {
  font-weight: 600;
  margin: 10px 0 6px 0;
}

.opencodian-env-domains-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 8px;
}

.opencodian-env-domains-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: var(--radius-s, 4px);
  background-color: var(--background-secondary);
}

.opencodian-env-domains-row input {
  flex: 1;
  min-width: 0;
}

.opencodian-env-domains-row input:first-child {
  flex: 0 0 40%;
  font-family: var(--font-monospace);
}

.opencodian-env-domains-picker {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.opencodian-env-domains-picker select {
  flex: 0 1 auto;
  min-width: 0;
}

.opencodian-env-domains-picker input {
  flex: 1;
  min-width: 0;
}

.opencodian-env-domains-add {
  margin-bottom: 4px;
}

.opencodian-env-domains-empty {
  color: var(--text-muted);
  font-size: var(--font-ui-smaller, 11px);
  padding: 8px 0;
}


/* components/backend-session-browser.css */
/* Backend Session Browser Modal */

.opencodian-backend-session-browser .modal-content {
  padding: 0;
}

.opencodian-backend-session-browser-container {
  display: flex;
  min-height: 360px;
  max-height: 500px;
}

.opencodian-backend-session-browser-list {
  flex: 0 0 240px;
  border-right: 1px solid var(--background-modifier-border);
  overflow-y: auto;
  padding: 4px 0;
}

.opencodian-backend-session-browser-list-inner {
  display: flex;
  flex-direction: column;
}

.opencodian-backend-session-browser-list-inner .opencodian-backend-session-browser-loading,
.opencodian-backend-session-browser-list-inner .opencodian-backend-session-browser-empty {
  padding: 16px 12px;
  color: var(--text-muted);
  font-size: 12px;
}

.opencodian-backend-session-browser-item {
  padding: 8px 12px;
  cursor: pointer;
  border-bottom: 1px solid var(--background-modifier-border);
  transition: background-color 0.15s ease;
}

.opencodian-backend-session-browser-item:hover {
  background-color: var(--background-modifier-hover);
}

.opencodian-backend-session-browser-item.is-selected {
  background-color: var(--interactive-accent);
  color: var(--text-on-accent);
}

.opencodian-backend-session-browser-item.is-archived {
  opacity: 0.65;
}

.opencodian-backend-session-browser-item.is-archived.is-selected {
  opacity: 1;
}

.opencodian-backend-session-browser-item-title {
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.opencodian-backend-session-browser-item-archived {
  display: inline-block;
  margin-top: 4px;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--background-modifier-border);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
}

.opencodian-backend-session-browser-item-date {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 2px;
}

.is-selected .opencodian-backend-session-browser-item-archived {
  background: rgba(255, 255, 255, 0.2);
  color: var(--text-on-accent);
}

.is-selected .opencodian-backend-session-browser-item-date {
  color: var(--text-on-accent);
  opacity: 0.8;
}

.opencodian-backend-session-browser-preview {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
  min-width: 0;
}

.opencodian-backend-session-browser-preview-hint,
.opencodian-backend-session-browser-preview-loading,
.opencodian-backend-session-browser-preview-empty {
  color: var(--text-muted);
  font-size: 12px;
  text-align: center;
  padding-top: 40px;
}

.opencodian-backend-session-browser-preview-header {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 8px;
}

.opencodian-backend-session-browser-preview-header h4 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
}

.opencodian-backend-session-browser-preview-count {
  font-size: 11px;
  color: var(--text-muted);
}

.opencodian-backend-session-browser-preview-messages {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.opencodian-backend-session-browser-preview-msg {
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  max-height: 80px;
  overflow: hidden;
}

.opencodian-backend-session-browser-preview-msg-user {
  background-color: var(--background-modifier-hover);
}

.opencodian-backend-session-browser-preview-msg-assistant {
  background-color: var(--background-primary-alt);
}

.opencodian-backend-session-browser-preview-role {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  margin-bottom: 2px;
}

.opencodian-backend-session-browser-preview-text {
  white-space: pre-wrap;
  word-break: break-word;
  line-height: 1.4;
}

.opencodian-backend-session-browser-footer {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-backend-session-browser-resume-btn:disabled,
.opencodian-backend-session-browser-detail-btn:disabled,
.opencodian-backend-session-browser-fork-btn:disabled,
.opencodian-backend-session-browser-archive-btn:disabled,
.opencodian-backend-session-browser-unarchive-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Preview notice */
.opencodian-backend-session-browser-preview-notice {
  margin-bottom: 8px;
}
.opencodian-backend-session-browser-preview-notice p {
  font-size: 11px;
  color: var(--text-muted);
  font-style: italic;
  margin: 0;
}

/* Detail view */
.opencodian-backend-session-browser-detail-metadata {
  margin-bottom: 16px;
}
.opencodian-backend-session-browser-detail-metadata h4 {
  margin: 0 0 8px 0;
  font-size: 13px;
  font-weight: 600;
}
.opencodian-backend-session-browser-detail-unavailable {
  color: var(--text-muted);
  font-size: 12px;
  font-style: italic;
}
.opencodian-backend-session-browser-detail-field {
  display: flex;
  gap: 8px;
  padding: 3px 0;
  font-size: 12px;
  line-height: 1.4;
  border-bottom: 1px solid var(--background-modifier-border);
}
.opencodian-backend-session-browser-detail-field:last-child {
  border-bottom: none;
}
.opencodian-backend-session-browser-detail-field-label {
  flex: 0 0 100px;
  color: var(--text-muted);
  font-weight: 500;
}
.opencodian-backend-session-browser-detail-field-value {
  flex: 1;
  word-break: break-all;
  min-width: 0;
}

/* Detail transcript */
.opencodian-backend-session-browser-detail-transcript {
  border-top: 1px solid var(--background-modifier-border);
  padding-top: 12px;
}
.opencodian-backend-session-browser-detail-transcript h4 {
  margin: 0 0 4px 0;
  font-size: 13px;
  font-weight: 600;
}
.opencodian-backend-session-browser-detail-transcript-notice {
  margin-bottom: 8px;
}
.opencodian-backend-session-browser-detail-transcript-notice p {
  font-size: 11px;
  color: var(--text-muted);
  font-style: italic;
  margin: 0;
}
.opencodian-backend-session-browser-detail-transcript-empty {
  color: var(--text-muted);
  font-size: 12px;
  padding: 12px 0;
}
.opencodian-backend-session-browser-detail-transcript-count {
  font-size: 11px;
  color: var(--text-muted);
  margin: 0 0 8px 0;
}
.opencodian-backend-session-browser-detail-messages {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.opencodian-backend-session-browser-detail-msg {
  padding: 6px 10px;
  border-radius: 4px;
  font-size: 12px;
}
.opencodian-backend-session-browser-detail-msg-user {
  background-color: var(--background-modifier-hover);
}
.opencodian-backend-session-browser-detail-msg-assistant {
  background-color: var(--background-primary-alt);
}
.opencodian-backend-session-browser-detail-msg-role {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  margin-bottom: 2px;
}
.opencodian-backend-session-browser-detail-msg-text {
  white-space: pre-wrap;
  word-break: break-word;
  line-height: 1.5;
  max-height: 300px;
  overflow-y: auto;
}

/* Search box */
.opencodian-backend-session-browser-search {
  padding: 6px 8px;
  border-bottom: 1px solid var(--background-modifier-border);
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--background-primary);
}
.opencodian-backend-session-browser-search-input {
  width: 100%;
  font-size: 12px;
  padding: 4px 8px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 4px;
  background: var(--background-primary);
  color: var(--text-normal);
}
.opencodian-backend-session-browser-search-input:focus {
  outline: none;
  border-color: var(--interactive-accent);
}

/* Activity lines (preview) */
.opencodian-backend-session-browser-preview-activity {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  font-size: 11px;
  color: var(--text-muted);
  font-style: italic;
}
.opencodian-backend-session-browser-preview-activity-icon {
  font-size: 12px;
  flex-shrink: 0;
}
.opencodian-backend-session-browser-preview-activity-label {
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  font-size: 9px;
  font-style: normal;
}
.opencodian-backend-session-browser-preview-activity-text {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

/* Activity lines (detail) */
.opencodian-backend-session-browser-detail-activity {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  font-size: 11px;
  color: var(--text-muted);
  border-left: 2px solid var(--background-modifier-border);
  margin-left: 8px;
}
.opencodian-backend-session-browser-detail-activity[data-activity="tool_call"] {
  border-left-color: var(--color-blue, #4a90d9);
}
.opencodian-backend-session-browser-detail-activity[data-activity="file_change"] {
  border-left-color: var(--color-green, #4a9d4a);
}
.opencodian-backend-session-browser-detail-activity[data-activity="web_search"] {
  border-left-color: var(--color-purple, #9b59b6);
}
.opencodian-backend-session-browser-detail-activity-icon {
  font-size: 13px;
  flex-shrink: 0;
}
.opencodian-backend-session-browser-detail-activity-label {
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  font-size: 9px;
  flex-shrink: 0;
}
.opencodian-backend-session-browser-detail-activity-text {
  white-space: pre-wrap;
  word-break: break-word;
  min-width: 0;
}


/* components/streaming-content.css */
/* ============================================================
   Streaming Content Styles
   ============================================================ */

/* Streaming text block */
.streaming-text-block {
  margin: 0.5em 0;
}

/* Thinking block - Claudian style */
.streaming-thinking-block {
  margin: 0.3em 0;
  overflow: hidden;
}

.streaming-thinking-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
  cursor: pointer;
  user-select: none;
  color: var(--text-accent); /* Orange/red accent color */
  font-size: 13px;
}

.streaming-thinking-header:hover {
  opacity: 0.8;
}

.streaming-thinking-header::before {
  content: '';
  display: none;
}

.streaming-thinking-label {
  font-size: 13px;
  color: var(--text-accent);
  font-weight: 400;
}

.streaming-thinking-content {
  padding: 8px 12px;
  margin: 4px 0;
  font-size: 13px;
  color: var(--text-normal);
  line-height: 1.5;
  border-left: 2px solid var(--background-modifier-border);
  background: transparent;
}

/* Tool call block - Claudian style */
.streaming-tool-call {
  margin: 8px 0;
  overflow: hidden;
}

.streaming-tool-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
  cursor: pointer;
  overflow: hidden;
}

.streaming-tool-header:hover {
  opacity: 0.85;
}

.streaming-tool-icon {
  display: flex;
  align-items: center;
  color: var(--text-accent);
  flex-shrink: 0;
}

.streaming-tool-icon svg {
  width: 16px;
  height: 16px;
}

.streaming-tool-name {
  font-family: var(--font-monospace);
  font-size: 13px;
  font-weight: 400;
  color: var(--text-normal);
  white-space: nowrap;
  flex-shrink: 0;
}

.streaming-tool-summary {
  flex: 1;
  font-size: 13px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.streaming-tool-summary:empty {
  display: none;
}

/* Status icon on the right side */
.streaming-tool-status {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  margin-left: auto;
}

.streaming-tool-status svg {
  width: 14px;
  height: 14px;
}

/* Status colors */
.streaming-tool-status.status-running {
  color: var(--text-accent);
  animation: spin 1s linear infinite;
}

.streaming-tool-status.status-completed {
  color: var(--color-green);
}

.streaming-tool-status.status-error {
  color: var(--color-red);
}

.streaming-tool-status.status-blocked {
  color: var(--color-orange);
}

.streaming-tool-server-chip {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  margin-left: auto;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--background-modifier-form-field);
  color: var(--text-muted);
  font-size: 11px;
  font-family: var(--font-monospace);
  line-height: 1.4;
}

.streaming-tool-server-chip.is-interactive {
  border: 1px solid var(--background-modifier-border);
  cursor: pointer;
  transition: background 100ms ease, border-color 100ms ease, color 100ms ease;
}

.streaming-tool-server-chip.is-interactive:hover {
  background: var(--background-modifier-hover);
  border-color: var(--interactive-accent);
  color: var(--text-normal);
}

.streaming-tool-server-chip.is-interactive:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 1px;
}

.streaming-mcp-server-link {
  display: inline-block;
  margin-top: 4px;
  padding: 0;
  border: none;
  background: none;
  color: var(--text-accent);
  font-size: 12px;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.streaming-mcp-server-link:hover {
  color: var(--text-accent-hover, var(--interactive-accent));
}

.streaming-tool-auth-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  margin-left: 4px;
  padding: 1px 8px;
  border: 1px solid var(--interactive-accent);
  border-radius: 4px;
  background: var(--interactive-accent);
  color: var(--text-on-accent);
  font-size: 11px;
  font-weight: 500;
  line-height: 1.4;
  cursor: pointer;
  transition: opacity 100ms ease, transform 80ms ease;
}

.streaming-tool-auth-btn:hover {
  opacity: 0.88;
}

.streaming-tool-auth-btn:active {
  transform: scale(0.97);
}

.streaming-tool-auth-btn:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 1px;
}

.streaming-tool-auth-btn-icon {
  display: inline-flex;
  align-items: center;
  --icon-size: 12px;
}

.streaming-tool-auth-btn-icon svg {
  width: 12px;
  height: 12px;
}

.streaming-mcp-auth-hint {
  margin-top: 4px;
  padding: 4px 8px;
  border-radius: 4px;
  background: var(--background-modifier-error);
  color: var(--text-normal);
  font-size: 12px;
  line-height: 1.5;
}

.streaming-mcp-auth-hint.is-done {
  background: var(--background-modifier-success);
}

.streaming-mcp-auth-hint.is-pending {
  background: var(--background-modifier-cover);
}

.streaming-mcp-auth-hint.is-failed {
  background: var(--background-modifier-error);
}

.streaming-tool-auth-done {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  margin-left: 4px;
  padding: 1px 8px;
  border: 1px solid var(--color-green, var(--text-success, var(--interactive-accent)));
  border-radius: 4px;
  color: var(--text-success, var(--interactive-accent));
  font-size: 11px;
  font-weight: 500;
  line-height: 1.4;
}

.streaming-tool-auth-done-icon {
  display: inline-flex;
  align-items: center;
  --icon-size: 12px;
}

.streaming-tool-auth-done-icon svg {
  width: 12px;
  height: 12px;
}

.streaming-tool-retry-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  margin-left: 4px;
  padding: 1px 8px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 4px;
  background: var(--background-secondary);
  color: var(--text-normal);
  font-size: 11px;
  font-weight: 500;
  line-height: 1.4;
  cursor: pointer;
  transition: opacity 100ms ease, transform 80ms ease;
}

.streaming-tool-retry-btn:hover:not(:disabled) {
  border-color: var(--interactive-accent);
  color: var(--interactive-accent);
}

.streaming-tool-retry-btn:active:not(:disabled) {
  transform: scale(0.97);
}

.streaming-tool-retry-btn:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 1px;
}

.streaming-tool-retry-btn.is-busy {
  opacity: 0.6;
  cursor: progress;
}

.streaming-tool-retry-btn-icon {
  display: inline-flex;
  align-items: center;
  --icon-size: 12px;
}

.streaming-tool-retry-btn-icon svg {
  width: 12px;
  height: 12px;
}

.streaming-tool-retry-btn.is-busy .streaming-tool-retry-btn-icon svg {
  animation: spin 1s linear infinite;
}

.streaming-tool-retry-result {
  display: flex;
  align-items: flex-start;
  gap: 4px;
  margin-top: 4px;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  line-height: 1.5;
}

.streaming-tool-retry-result.is-ok {
  background: var(--background-modifier-success);
  color: var(--text-normal);
}

.streaming-tool-retry-result.is-fail {
  background: var(--background-modifier-error);
  color: var(--text-normal);
}

.streaming-tool-retry-result-icon {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  --icon-size: 14px;
}

.streaming-tool-retry-result-icon svg {
  width: 14px;
  height: 14px;
}

.streaming-tool-retry-result-text {
  flex: 1;
  word-break: break-word;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.streaming-tool-content {
  padding: 4px 0;
  padding-inline-start: 16px;
  margin-inline-start: 7px;
  border-inline-start: 2px solid var(--background-modifier-border);
  font-size: 13px;
  color: var(--text-normal);
  line-height: 1.5;
}

.streaming-tool-pending {
  font-size: 12px;
  color: var(--text-muted);
  font-style: italic;
}

.streaming-tool-empty {
  font-size: 12px;
  color: var(--text-muted);
  font-style: italic;
}

.streaming-tool-lines {
  font-family: var(--font-monospace);
  font-size: 11px;
  line-height: 1.4;
}

.streaming-tool-line {
  padding: 2px 0;
  border-bottom: 1px solid var(--background-modifier-border-hover);
}

.streaming-tool-line:last-child {
  border-bottom: none;
}

.streaming-tool-truncated {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed var(--background-modifier-border);
  font-size: 11px;
  color: var(--text-muted);
  font-style: italic;
}

/* Error block */
.streaming-error-block {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 0.5em 0;
  padding: 10px 12px;
  background: color-mix(in srgb, var(--background-secondary) 90%, var(--opencodian-status-error-subtle));
  border: 1px solid var(--opencodian-status-error-border);
  border-radius: 10px;
  color: var(--text-normal);
}

.streaming-error-icon {
  flex-shrink: 0;
}

.streaming-error-body {
  min-width: 0;
  flex: 1;
}

.streaming-error-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-normal);
}

.streaming-error-text {
  font-size: 13px;
  white-space: pre-wrap;
  line-height: 1.5;
  color: var(--text-muted);
  word-break: break-word;
}

.opencodian-server-action-card {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 10px 0;
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid var(--background-modifier-border);
  background: var(--opencodian-surface-mix);
  box-shadow: var(--opencodian-shadow);
}

.opencodian-server-action-card.is-starting {
  border-color: var(--opencodian-accent-border);
}

.opencodian-server-action-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-normal);
}

.opencodian-server-action-desc,
.opencodian-server-action-status {
  font-size: 13px;
  line-height: 1.5;
  white-space: pre-wrap;
}

.opencodian-server-action-desc {
  color: var(--text-normal);
}

.opencodian-server-action-status {
  color: var(--text-muted);
}

.opencodian-server-action-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.opencodian-server-action-btn {
  border: none;
  border-radius: 8px;
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-normal);
  background: var(--background-secondary);
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease, background 0.15s ease;
}

.opencodian-server-action-btn:hover:not(:disabled) {
  transform: translateY(-1px);
  background: var(--background-modifier-hover);
}

.opencodian-server-action-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.opencodian-server-action-btn.mod-cta {
  background: var(--interactive-accent);
  color: var(--text-on-accent);
}

/* Expand/collapse animation helpers */
.streaming-thinking-block.is-expanded .streaming-thinking-content,
.streaming-tool-call.is-expanded .streaming-tool-content {
  animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Pending indicator - "Getting to work..." style */
.opencodian-pending {
  font-size: 13px;
  color: var(--text-accent);
  font-style: italic;
  margin: 8px 0;
  opacity: 0.8;
}

.opencodian-pending-text {
  color: var(--text-accent);
}

.opencodian-pending-hint {
  color: var(--text-muted);
  font-size: 12px;
}




/* components/inline-permission.css */
/* ==================== Inline Permission Card Styles ==================== */
.opencodian-permission-inline {
  background: var(--background-primary);
  border: 2px solid var(--interactive-accent);
  border-radius: 8px;
  padding: 16px;
  margin: 12px 0;
  box-shadow: var(--opencodian-shadow-xs);
}

.opencodian-permission-inline-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--background-modifier-border);
}

.opencodian-permission-inline-icon {
  font-size: 18px;
}

.opencodian-permission-inline-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-permission-inline-info {
  margin-bottom: 12px;
}

.opencodian-permission-inline-tool {
  font-size: 14px;
  color: var(--text-accent);
  font-weight: 500;
  margin-bottom: 4px;
}

.opencodian-permission-inline-desc {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.4;
}

.opencodian-permission-inline-patterns {
  background: var(--background-secondary);
  border-radius: 6px;
  padding: 10px 12px;
  margin: 12px 0;
}

.opencodian-permission-inline-label {
  font-size: var(--font-ui-smaller);
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}

.opencodian-permission-inline-pattern-item {
  font-size: 13px;
  color: var(--text-normal);
  font-family: var(--font-monospace);
  padding: 2px 0;
}

.opencodian-permission-inline-command {
  background: var(--background-secondary);
  border-radius: 6px;
  padding: 10px 12px;
  margin: 12px 0;
  font-size: 13px;
}

.opencodian-permission-inline-command code {
  background: var(--background-primary);
  padding: 2px 6px;
  border-radius: 4px;
  font-family: var(--font-monospace);
  color: var(--text-accent);
}

.opencodian-permission-inline-buttons {
  display: flex;
  gap: 8px;
  margin-top: 16px;
  flex-wrap: wrap;
}

.opencodian-permission-inline-btn {
  padding: 8px 16px;
  border: none;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.opencodian-permission-inline-btn:hover:not(:disabled) {
  transform: translateY(-1px);
  opacity: 0.9;
}

.opencodian-permission-inline-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.opencodian-permission-inline-once {
  background: var(--interactive-accent);
  color: var(--text-on-accent);
}

.opencodian-permission-inline-always {
  background: var(--background-modifier-success);
  color: var(--text-on-accent);
}

.opencodian-permission-inline-session {
  background: var(--interactive-accent);
  color: var(--text-on-accent);
  opacity: 0.85;
}

.opencodian-permission-inline-reject {
  background: var(--background-modifier-error);
  color: var(--text-on-accent);
}

.opencodian-question-inline {
  margin-top: 12px;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--interactive-accent) 24%, var(--opencodian-glass-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--interactive-accent) 8%, transparent) 0%,
      transparent 100%
    ),
    color-mix(in srgb, var(--opencodian-glass-base) 92%, transparent);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.opencodian-question-inline--resolved {
  border-color: color-mix(in srgb, var(--interactive-accent) 22%, var(--opencodian-glass-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--interactive-accent) 6%, transparent) 0%,
      transparent 100%
    ),
    color-mix(in srgb, var(--background-secondary) 92%, transparent);
}

.opencodian-question-inline-details {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.opencodian-question-inline-summary-toggle {
  list-style: none;
  cursor: pointer;
}

.opencodian-question-inline-summary-toggle::-webkit-details-marker {
  display: none;
}

.opencodian-question-inline-details-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.opencodian-question-inline-header {
  display: flex;
  align-items: center;
  gap: 8px;
}

.opencodian-question-inline-icon {
  width: 22px;
  height: 22px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--interactive-accent) 16%, transparent);
  color: var(--interactive-accent);
  font-weight: 700;
}

.opencodian-question-inline-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-normal);
}

.opencodian-question-inline-collapse-hint {
  margin-left: auto;
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
}

.opencodian-question-inline-progress {
  margin-left: auto;
  padding: 4px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--interactive-accent) 12%, transparent);
  color: var(--interactive-accent);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  line-height: 1;
}

.opencodian-question-inline-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.opencodian-question-inline-header-text {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-normal);
}

.opencodian-question-inline-body-text {
  font-size: 13px;
  color: var(--text-muted);
}

.opencodian-question-inline-options {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.opencodian-question-inline-option {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 8px 10px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--background-primary) 74%, transparent);
  border: 1px solid color-mix(in srgb, var(--opencodian-glass-border) 76%, transparent);
}

.opencodian-question-inline-option-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.opencodian-question-inline-option-label {
  font-size: 13px;
  color: var(--text-normal);
}

.opencodian-question-inline-option-description {
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
}

.opencodian-question-inline-option-preview {
  font-size: var(--font-ui-smaller);
  color: var(--text-faint, var(--text-muted));
  background: color-mix(in srgb, var(--background-primary) 62%, transparent);
  border: 1px dashed color-mix(in srgb, var(--opencodian-glass-border) 56%, transparent);
  border-radius: 8px;
  padding: 6px 8px;
  margin-top: 8px;
  white-space: pre-wrap;
  word-break: break-word;
}

.opencodian-question-inline-option-preview.is-hidden {
  display: none;
}

.opencodian-question-inline-custom {
  width: 100%;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--opencodian-border-soft);
  background: color-mix(in srgb, var(--background-primary) 82%, transparent);
  color: var(--text-normal);
}

.opencodian-question-inline-buttons {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.opencodian-question-inline-summary-list {
  margin: 0;
  padding-left: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.opencodian-question-inline-summary-item {
  color: var(--text-normal);
  line-height: 1.55;
}

.opencodian-question-inline-summary-label {
  font-weight: 700;
}

.opencodian-question-inline-summary-value {
  color: var(--text-muted);
}

.opencodian-question-inline-btn {
  border: none;
  border-radius: 10px;
  padding: 8px 12px;
  cursor: pointer;
  font-size: var(--font-ui-smaller);
  font-weight: 600;
}

.opencodian-question-inline-btn.is-submit {
  background: var(--interactive-accent);
  color: var(--text-on-accent);
}

.opencodian-question-inline-btn.is-reject {
  background: var(--background-modifier-error);
  color: var(--text-on-accent);
}

.opencodian-context-file-modal .modal-content {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-top: 6px;
}

.opencodian-context-file-modal .modal-title {
  font-size: 28px;
  font-weight: 800;
  letter-spacing: -0.03em;
}

.opencodian-context-file-modal .modal-close-button {
  border-radius: 12px;
}

.opencodian-context-file-search-section,
.opencodian-context-file-filter-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.opencodian-context-file-search {
  width: 100%;
  padding: 12px 14px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--opencodian-glass-border) 82%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-primary) 98%, transparent) 0%,
      color-mix(in srgb, var(--background-secondary) 94%, transparent) 100%
    );
  color: var(--text-normal);
  box-shadow:
    0 10px 24px color-mix(in srgb, var(--opencodian-glass-shadow) 14%, transparent),
    0 1px 0 color-mix(in srgb, var(--background-primary) 80%, transparent) inset;
}

.opencodian-context-file-search:focus {
  border-color: color-mix(in srgb, var(--interactive-accent) 36%, var(--opencodian-glass-border));
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--interactive-accent) 12%, transparent),
    0 10px 24px color-mix(in srgb, var(--opencodian-glass-shadow) 14%, transparent),
    0 1px 0 color-mix(in srgb, var(--background-primary) 80%, transparent) inset;
}

.opencodian-context-file-search:disabled {
  opacity: 0.7;
}

.opencodian-context-file-filter-heading {
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.opencodian-context-file-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  max-height: 132px;
  overflow-y: auto;
  padding: 2px 4px 2px 0;
}

.opencodian-context-file-filter {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 6px 12px;
  line-height: 1.2;
  border-radius: 999px;
  border: 1px solid var(--opencodian-border-soft);
  background: color-mix(in srgb, var(--background-secondary) 96%, transparent);
  color: var(--text-normal);
  cursor: pointer;
  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease,
    transform 0.16s ease,
    box-shadow 0.16s ease;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.opencodian-context-file-filter:hover {
  transform: translateY(-1px);
  background: var(--opencodian-highlight);
  border-color: var(--opencodian-border-strong);
  box-shadow: 0 8px 20px color-mix(in srgb, var(--text-normal) 10%, transparent);
}

.opencodian-context-file-filter.is-active {
  border-color: color-mix(in srgb, var(--interactive-accent) 34%, var(--opencodian-border-soft));
  background: color-mix(in srgb, var(--interactive-accent) 14%, var(--background-secondary));
  color: var(--text-normal);
}

.opencodian-context-file-filter-label {
  font-size: var(--font-ui-smaller);
  font-weight: 500;
}

.opencodian-context-file-filter-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 21px;
  height: 21px;
  padding: 0 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--background-primary) 86%, transparent);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  color: var(--text-muted);
}

.opencodian-context-file-filter.is-active .opencodian-context-file-filter-count {
  background: color-mix(in srgb, var(--interactive-accent) 18%, var(--background-secondary));
  color: var(--interactive-accent);
}

.opencodian-context-file-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 440px;
  overflow-y: auto;
  padding: 8px 4px 0 0;
}

.opencodian-context-file-item {
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: stretch;
  gap: 10px;
  padding: 16px 18px;
  min-height: 104px;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--opencodian-glass-border) 78%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-primary) 100%, transparent) 0%,
      color-mix(in srgb, var(--background-secondary) 95%, transparent) 100%
    );
  cursor: pointer;
  text-align: left;
  box-shadow:
    0 8px 18px color-mix(in srgb, var(--opencodian-glass-shadow) 12%, transparent),
    0 1px 0 color-mix(in srgb, var(--background-primary) 80%, transparent) inset;
  transition:
    transform 0.16s ease,
    border-color 0.16s ease,
    box-shadow 0.16s ease,
    background 0.16s ease;
}

.opencodian-context-file-item-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.opencodian-context-file-item:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--interactive-accent) 28%, var(--opencodian-glass-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--interactive-accent) 8%, var(--background-primary)) 0%,
      color-mix(in srgb, var(--interactive-accent) 4%, var(--background-secondary)) 100%
    );
  box-shadow:
    0 12px 24px color-mix(in srgb, var(--opencodian-glass-shadow) 16%, transparent),
    0 1px 0 color-mix(in srgb, var(--background-primary) 84%, transparent) inset;
}

.opencodian-context-file-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 15px;
  line-height: 1.5;
  font-weight: 700;
  color: var(--text-normal);
  word-break: break-word;
  white-space: normal;
  margin: 0;
}

.opencodian-context-file-ext {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  min-height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--interactive-accent) 10%, var(--background-secondary));
  color: var(--interactive-accent);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1;
}

.opencodian-context-file-path,
.opencodian-context-file-empty {
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
  line-height: 1.55;
}

.opencodian-context-file-path {
  display: block;
  word-break: break-word;
  margin: 0;
  padding-right: 4px;
  opacity: 0.92;
}

.opencodian-context-file-empty {
  padding: 18px 14px;
  border-radius: 16px;
  border: 1px dashed color-mix(in srgb, var(--opencodian-glass-border) 72%, transparent);
  background: color-mix(in srgb, var(--background-secondary) 82%, transparent);
  text-align: center;
}

.opencodian-context-file-empty.is-loading {
  color: var(--text-accent);
}

.opencodian-context-file-summary {
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
  padding: 0 4px 2px;
  line-height: 1.5;
}

.opencodian-permission-inline-status {
  margin-top: 12px;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  text-align: center;
}

.opencodian-permission-inline-granted {
  background: color-mix(in srgb, var(--background-modifier-success) 20%, transparent);
  color: var(--opencodian-status-success);
}

.opencodian-permission-inline-rejected {
  background: color-mix(in srgb, var(--background-modifier-error) 20%, transparent);
  color: var(--opencodian-status-error);
}

/* -- Multi-select + folders (R-A7) --------------------------------- */

.opencodian-context-file-item .opencodian-context-file-item-check {
  display: none;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 20px;
  height: 20px;
  margin-top: 2px;
  border-radius: 50%;
  background: var(--interactive-accent);
  color: var(--text-on-accent);
}

.opencodian-context-file-item .opencodian-context-file-item-check .svg-icon {
  width: 12px;
  height: 12px;
}

.opencodian-context-file-item.is-selected {
  border-color: color-mix(in srgb, var(--interactive-accent) 55%, var(--opencodian-glass-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--interactive-accent) 12%, var(--background-primary)) 0%,
      color-mix(in srgb, var(--interactive-accent) 6%, var(--background-secondary)) 100%
    );
}

.opencodian-context-file-item.is-selected .opencodian-context-file-item-check {
  display: inline-flex;
}

.opencodian-context-file-item-glyph {
  display: inline-flex;
  align-items: center;
  flex: none;
  margin-top: 2px;
  color: var(--text-muted);
}

.opencodian-context-file-ext.is-folder {
  text-transform: none;
  letter-spacing: normal;
}

.opencodian-context-file-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 4px;
  border-top: 1px solid color-mix(in srgb, var(--opencodian-glass-border) 60%, transparent);
}

.opencodian-context-file-selected-count {
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
}

.opencodian-context-file-confirm:disabled {
  opacity: 0.55;
  cursor: default;
}


/* components/config-status.css */
/* ==================== Config Status Indicator ==================== */

.opencodian-status-warning .setting-item-description {
  color: var(--text-warning) !important;
  font-weight: 500;
}

.opencodian-status-yolo .setting-item-description {
  color: var(--text-success) !important;
}

.opencodian-status-normal .setting-item-description {
  color: var(--interactive-accent) !important;
}

.opencodian-status-plan .setting-item-description {
  color: var(--background-modifier-error) !important;
}

.opencodian-status-custom .setting-item-description {
  color: var(--text-muted) !important;
}

.opencodian-title-model-warning-button {
  color: var(--opencodian-status-warning);
}

.opencodian-title-model-warning-button:hover {
  color: var(--opencodian-status-warning);
  background: var(--opencodian-status-warning-subtle);
}



/* components/navigation-sidebar.css */
/* ==================== Navigation Sidebar ==================== */

.workspace-leaf-content[data-type="opencodian-view"] {
  position: relative;
}

.opencodian-nav-sidebar-host {
  position: absolute;
  inset: 0;
  z-index: 220;
  pointer-events: none;
}

.opencodian-nav-sidebar {
  position: absolute;
  left: 4px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 4px;
  z-index: 100;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

.opencodian-nav-sidebar.visible {
  opacity: 0.08;
  pointer-events: auto;
}

.opencodian-nav-sidebar.visible:hover,
.opencodian-nav-sidebar.visible:focus-within {
  opacity: 1;
}

.opencodian-nav-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border-radius: 6px;
  background: var(--opencodian-glass-base);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--opencodian-glass-border);
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.15s ease;
  box-shadow: 0 2px 8px var(--opencodian-glass-shadow);
  appearance: none;
}

.opencodian-nav-btn:hover {
  background: var(--background-modifier-hover);
  color: var(--text-normal);
  border-color: var(--opencodian-glass-border-strong);
  transform: scale(1.05);
}

.opencodian-nav-btn:active {
  transform: scale(0.98);
}

.opencodian-nav-btn:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

.opencodian-nav-btn svg {
  width: 16px;
  height: 16px;
}



/* components/modified-files-sidebar.css */
/* ==================== Modified Files Sidebar ==================== */

.opencodian-modified-files-sidebar-host {
  --opencodian-modified-files-expanded-height: min(420px, calc(100% - 160px));
  position: absolute;
  inset: 0;
  z-index: 220;
  pointer-events: none;
}

.opencodian-modified-files-hover-zone {
  position: absolute;
  right: 0;
  top: 76px;
  width: 48px;
  height: 40px;
  pointer-events: auto;
}

.opencodian-modified-files-trigger-strip {
  position: absolute;
  right: 8px;
  top: 4px;
  box-sizing: border-box;
  min-width: 44px;
  height: 32px;
  padding: 0 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 999px;
  background: var(--background-primary);
  color: var(--text-muted);
  cursor: pointer;
  font-size: var(--font-ui-smaller);
  line-height: 1;
  opacity: 0;
  pointer-events: none;
  transform: translateX(6px);
  transition: opacity 160ms ease-out, transform 160ms ease-out, background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out;
}

/* The hidden-state hit area stays narrow; focus preserves keyboard discovery. */
.opencodian-modified-files-hover-zone:hover .opencodian-modified-files-trigger-strip,
.opencodian-modified-files-hover-zone:focus-within .opencodian-modified-files-trigger-strip,
.opencodian-modified-files-hover-zone.is-expanded .opencodian-modified-files-trigger-strip {
  opacity: 1;
  pointer-events: auto;
  transform: translateX(0);
}

.opencodian-modified-files-trigger-strip:hover {
  background: var(--background-modifier-hover);
  border-color: var(--interactive-accent);
  color: var(--text-normal);
}

.opencodian-modified-files-trigger-strip[aria-expanded='true'] {
  border-color: var(--interactive-accent);
  background: var(--background-modifier-hover);
  color: var(--text-normal);
}

.opencodian-modified-files-trigger-strip:focus-visible,
.opencodian-modified-files-sidebar-collapse:focus-visible,
.opencodian-modified-files-sidebar-path:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

.opencodian-modified-files-trigger-icon {
  display: inline-flex;
  width: 16px;
  height: 16px;
}

.opencodian-modified-files-strip-badge {
  box-sizing: border-box;
  flex: 0 0 auto;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  outline: 2px solid var(--background-primary);
  background: var(--interactive-accent);
  color: var(--text-on-accent);
  font-size: 9px;
  font-weight: 700;
  text-align: center;
}

.opencodian-modified-files-strip-badge.is-hidden {
  display: none;
}

.opencodian-modified-files-trigger-strip.is-unavailable {
  color: var(--text-muted);
}

.opencodian-modified-files-trigger-strip.is-unavailable::after {
  position: absolute;
  right: 5px;
  bottom: 5px;
  width: 5px;
  height: 5px;
  border: 1px solid var(--background-primary);
  border-radius: 50%;
  background: var(--text-muted);
  content: '';
}

.opencodian-modified-files-sidebar {
  position: absolute;
  right: 8px;
  top: 40px;
  box-sizing: border-box;
  width: min(288px, calc(100% - 16px));
  max-height: calc(var(--opencodian-modified-files-expanded-height) - 40px);
  display: flex;
  flex-direction: column;
  color: var(--text-normal);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: opacity 160ms ease-out, transform 160ms ease-out;
}

/* Expansion is click-driven; hover/focus reveal only the quiet trigger. */
.opencodian-modified-files-hover-zone.is-expanded {
  width: min(304px, calc(100% - 8px));
  height: var(--opencodian-modified-files-expanded-height);
  pointer-events: auto;
}

.opencodian-modified-files-hover-zone.is-expanded .opencodian-modified-files-sidebar,
.opencodian-modified-files-sidebar.is-expanded {
  opacity: 1;
  pointer-events: auto;
  transform: translateX(0);
}

.opencodian-modified-files-sidebar-header {
  gap: 6px;
}

.opencodian-modified-files-sidebar-title {
  flex: 1;
  min-width: 0;
}

.opencodian-modified-files-sidebar-summary {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 46%;
  color: var(--text-muted);
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-modified-files-sidebar-collapse {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
}

.opencodian-modified-files-sidebar-collapse:hover {
  background: var(--background-modifier-hover);
  color: var(--text-normal);
}

.opencodian-modified-files-sidebar-list {
  min-height: 0;
  overflow-y: auto;
  padding: 4px;
}

.opencodian-modified-files-sidebar-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  border-radius: 6px;
}

.opencodian-modified-files-sidebar-item:hover {
  background: var(--background-modifier-hover);
}

.opencodian-modified-files-sidebar-item > summary {
  display: flex;
  align-items: center;
  min-width: 0;
  cursor: pointer;
  list-style-position: inside;
}

.opencodian-modified-files-sidebar-item > summary::-webkit-details-marker {
  color: var(--text-muted);
}

.opencodian-modified-files-sidebar-path {
  min-width: 0;
  flex: 1;
  /* The binding row renders this class on a <button>, which the host styles as
     a flex container with a fixed input height; `text-overflow` does not apply
     to a flex container's anonymous item, so the path clipped mid-glyph with no
     ellipsis marker, and the fixed height inflated a one-line path to 30px. An
     explicit block display and auto height make the text container eligible for
     the ellipsis in both the button (binding row) and span (change row) cases. */
  display: block;
  height: auto;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-normal);
  cursor: pointer;
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  line-height: 1.35;
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-modified-files-sidebar-path:hover {
  color: var(--text-accent);
  text-decoration: underline;
}

.opencodian-modified-files-sidebar-meta,
.opencodian-modified-files-sidebar-stats {
  display: flex;
  align-items: center;
  gap: 8px;
}

.opencodian-modified-files-sidebar-meta {
  justify-content: space-between;
}

.opencodian-modified-files-sidebar-stats {
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
}

.opencodian-modified-files-sidebar-additions {
  color: var(--text-success);
}

.opencodian-modified-files-sidebar-deletions {
  color: var(--text-error);
}

.opencodian-modified-files-sidebar-status {
  padding: 2px 6px;
  border-radius: 999px;
  background: var(--background-modifier-border);
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  text-transform: uppercase;
}

.opencodian-modified-files-linked-note {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 6px 8px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.opencodian-modified-files-linked-note[data-linked-note-state='locked'] {
  color: color-mix(in srgb, var(--text-error) 62%, var(--text-normal));
}

.opencodian-modified-files-linked-note[data-linked-note-state='locked']
  .opencodian-modified-files-linked-note-badge {
  color: color-mix(in srgb, var(--text-error) 62%, var(--text-normal));
}

.opencodian-modified-files-linked-note-badge {
  flex: 0 0 auto;
  padding: 1px 5px;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s);
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.opencodian-modified-files-linked-note-section {
  padding: 8px 10px 10px;
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-modified-files-linked-note-section-title {
  color: var(--text-normal);
  font-size: var(--font-ui-small);
  font-weight: 600;
}

.opencodian-modified-files-linked-note-section-hint {
  padding: 0 8px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  line-height: 1.4;
}

.opencodian-modified-files-sidebar-status.status-added {
  background: color-mix(in srgb, var(--text-success) 18%, transparent);
  color: var(--text-success);
}

.opencodian-modified-files-sidebar-status.status-deleted {
  background: color-mix(in srgb, var(--text-error) 18%, transparent);
  color: var(--text-error);
}

.opencodian-modified-files-sidebar-empty {
  padding: 16px 12px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  text-align: center;
}

.opencodian-modified-files-sidebar-empty.is-unavailable {
  text-align: left;
}

.opencodian-modified-files-sidebar-host.is-disabled {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-modified-files-trigger-strip,
  .opencodian-modified-files-sidebar {
    transition: none;
  }
}

/* ==================== Edit revert section (R-B3) ==================== */

.opencodian-edit-revert-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 4px 4px 4px;
  border-bottom: 1px solid var(--background-modifier-border);
}

.opencodian-edit-revert-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 4px 8px;
}

.opencodian-edit-revert-title {
  min-width: 0;
  flex: 1;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-edit-revert-hint {
  padding: 2px 8px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  line-height: 1.4;
}

.opencodian-edit-revert-all {
  flex: 0 0 auto;
  padding: 2px 10px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 999px;
  background: var(--background-primary);
  color: var(--text-muted);
  cursor: pointer;
  font-size: var(--font-ui-smaller);
  line-height: 1.6;
}

.opencodian-edit-revert-all:hover {
  border-color: var(--interactive-accent);
  color: var(--text-normal);
}

.opencodian-edit-revert-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 220px;
  overflow-y: auto;
}

.opencodian-edit-revert-item {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 6px 8px;
  border-radius: 6px;
}

.opencodian-edit-revert-item:hover {
  background: var(--background-modifier-hover);
}

.opencodian-edit-revert-path {
  min-width: 0;
  flex: 1;
  color: var(--text-normal);
  cursor: pointer;
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  line-height: 1.35;
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-edit-revert-path:hover {
  color: var(--text-accent);
  text-decoration: underline;
}

.opencodian-edit-revert-action {
  flex: 0 0 auto;
  padding: 1px 8px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: var(--font-ui-smaller);
  line-height: 1.6;
}

.opencodian-edit-revert-action:hover:not(:disabled) {
  border-color: var(--interactive-accent);
  color: var(--text-normal);
}

.opencodian-edit-revert-action:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.opencodian-edit-revert-excluded {
  flex: 0 1 auto;
  padding: 2px 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text-muted) 14%, transparent);
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-modified-files-sidebar-list.is-hidden {
  display: none;
}

.opencodian-edit-revert-action:focus-visible,
.opencodian-edit-revert-all:focus-visible,
.opencodian-edit-revert-path:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

/* ==================== Revert preview modal (R-F3) ==================== */

.opencodian-edit-revert-preview-modal .modal-content {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-modal-section-inner-gap, 12px);
}

.opencodian-edit-revert-preview-copy {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
  line-height: 1.5;
}

.opencodian-edit-revert-preview-list {
  display: flex;
  max-height: 280px;
  flex-direction: column;
  gap: 6px;
  overflow: auto;
  scrollbar-gutter: stable;
}

.opencodian-edit-revert-preview-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 12px;
  padding: 8px 10px;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s, 6px);
  background: var(--background-secondary);
}

.opencodian-edit-revert-preview-row.is-conflict {
  border-color: var(--text-warning);
}

.opencodian-edit-revert-preview-path {
  min-width: 0;
  overflow: hidden;
  color: var(--text-normal);
  font-family: var(--font-monospace);
  font-size: var(--font-ui-small);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-edit-revert-preview-lines {
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  white-space: nowrap;
}

.opencodian-edit-revert-preview-conflict {
  display: inline-flex;
  grid-column: 1 / -1;
  align-items: center;
  gap: 6px;
  color: color-mix(in srgb, var(--text-warning) 52%, var(--text-normal));
  font-size: var(--font-ui-smaller);
  font-weight: 600;
}

.opencodian-edit-revert-preview-conflict-icon,
.opencodian-edit-revert-preview-failure-icon {
  display: inline-flex;
  flex: 0 0 auto;
}

.opencodian-edit-revert-preview-failure {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--text-error);
  border-radius: var(--radius-s, 6px);
  color: var(--text-error);
}

.opencodian-edit-revert-preview-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--opencodian-modal-action-gap, 8px);
  padding-top: var(--opencodian-modal-section-inner-gap, 12px);
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-edit-revert-preview-actions button:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

button.opencodian-edit-revert-preview-confirm {
  border-color: var(--interactive-accent);
  background: color-mix(in srgb, var(--interactive-accent) 14%, var(--background-primary));
  color: var(--text-normal);
  font-weight: 600;
}

button.opencodian-edit-revert-preview-confirm:hover {
  background: color-mix(in srgb, var(--interactive-accent) 22%, var(--background-primary));
}

button.opencodian-edit-revert-preview-confirm.is-conflict {
  border-color: color-mix(in srgb, var(--text-error) 64%, var(--background-modifier-border));
  background: color-mix(in srgb, var(--text-error) 12%, var(--background-primary));
  color: color-mix(in srgb, var(--text-error) 62%, var(--text-normal));
}


/* components/effort-selector.css */
/* ==================== Effort Selector ==================== */
.opencodian-effort-slot,
.opencodian-effort-selector {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.opencodian-effort-group {
  display: flex;
  align-items: center;
  gap: 5px;
  min-height: var(--opencodian-input-toolbar-control-height, 30px);
  padding: 3px 7px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--background-secondary) 36%, transparent);
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 38%, transparent);
  box-shadow: none;
  font-size: 11px;
  transition: background-color 0.15s ease-out, border-color 0.15s ease-out, box-shadow 0.15s ease-out;
}

.opencodian-effort-group:hover,
.opencodian-effort-group:has(.opencodian-effort-gears.is-open) {
  background: color-mix(in srgb, var(--background-secondary) 48%, transparent);
  border-color: color-mix(in srgb, var(--background-modifier-border) 62%, var(--text-muted));
}

.opencodian-effort-gears {
  position: relative;
  display: flex;
  align-items: center;
  gap: 2px;
}

.opencodian-effort-current {
  padding: 1px 0;
  border-radius: 5px;
  background: transparent;
  color: color-mix(in srgb, var(--text-normal) 82%, var(--text-muted));
  font-weight: 650;
  cursor: pointer;
  transition: color 0.15s ease, background 0.15s ease;
  min-width: 48px;
  max-width: 74px;
  text-align: center;
  white-space: nowrap;
}

.opencodian-effort-current:hover {
  background: transparent;
  color: var(--text-normal);
}

.opencodian-effort-options {
  position: absolute;
  bottom: calc(100% + 4px);
  right: 0;
  box-sizing: border-box;
  display: none;
  flex-direction: column;
  gap: 2px;
  padding: 4px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--background-primary) 94%, var(--background-secondary));
  border: 1px solid color-mix(in srgb, var(--opencodian-glass-border-strong) 70%, var(--background-modifier-border));
  box-shadow:
    0 16px 28px color-mix(in srgb, var(--opencodian-glass-shadow-strong) 72%, transparent),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 34%, transparent) inset;
  z-index: 100;
  min-width: 72px;
}

.opencodian-effort-gears.is-open .opencodian-effort-options,
.opencodian-effort-options:has(:hover) {
  display: flex;
}

.opencodian-effort-gear {
  padding: 6px 12px;
  border-radius: 6px;
  color: var(--text-muted);
  cursor: pointer;
  transition: background-color 0.15s ease-out, color 0.15s ease-out;
  text-align: center;
  white-space: nowrap;
}

.opencodian-effort-gear:hover {
  background: var(--background-modifier-hover);
  color: var(--text-normal);
}

.opencodian-effort-gear.selected {
  background: color-mix(in srgb, var(--interactive-accent) 18%, transparent);
  color: var(--text-normal);
  font-weight: 600;
}

.opencodian-effort-current:focus-visible,
.opencodian-effort-gear:focus-visible {
  outline: 2px solid var(--background-modifier-border-focus);
  outline-offset: 2px;
}

.opencodian-composer-shell--action-buttons-etched .opencodian-effort-group {
  padding: 3px 5px;
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}

.opencodian-composer-shell--action-buttons-etched .opencodian-effort-group:hover,
.opencodian-composer-shell--action-buttons-etched .opencodian-effort-group:has(.opencodian-effort-gears.is-open) {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  filter: brightness(1.04) saturate(1.02);
}

.opencodian-composer-shell--action-buttons-etched .opencodian-effort-current {
  color: color-mix(in srgb, var(--text-normal) 86%, var(--text-muted));
  min-width: 48px;
}

.opencodian-composer-shell--action-buttons-etched .opencodian-effort-current:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--interactive-accent) 58%, transparent);
  outline-offset: 3px;
}



/* components/lsp-status-indicator.css */
.opencodian-lsp-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: var(--font-smallest);
  padding: 2px 6px;
  border-radius: var(--radius-s);
  cursor: pointer;
  opacity: 0.8;
  color: var(--text-muted);
}

.opencodian-lsp-status:hover {
  opacity: 1;
  color: var(--text-normal);
}

.opencodian-lsp-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.opencodian-lsp-status-dot.connected {
  background: var(--interactive-success);
}

.opencodian-lsp-status-dot.error {
  background: var(--interactive-error);
}

.opencodian-lsp-status-dot.partial {
  background: var(--text-warning);
}


/* components/settings-dropdown.css */
.opencodian-settings-native-select {
  position: fixed !important;
  inset: 0 auto auto 0 !important;
  width: 1px !important;
  height: 1px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

.opencodian-settings-dropdown {
  position: relative;
  width: 100%;
  min-width: min(180px, 100%);
  color: var(--text-normal);
}

.setting-item-control > .opencodian-settings-dropdown {
  flex: 0 1 240px;
}

.opencodian-settings-dropdown-trigger {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  min-height: 32px;
  margin: 0;
  padding: 5px 9px 5px 11px;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 86%, transparent);
  border-radius: 8px;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-primary) 96%, var(--background-secondary)) 0%,
      color-mix(in srgb, var(--background-primary) 88%, var(--background-secondary)) 100%
    );
  color: var(--text-normal);
  font-family: var(--font-interface);
  font-size: 13px;
  line-height: 1.35;
  text-align: left;
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, white 4%, transparent),
    0 2px 8px color-mix(in srgb, var(--background-modifier-box-shadow) 8%, transparent);
  transition: border-color 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
}

.opencodian-settings-dropdown-trigger:hover,
.opencodian-settings-dropdown.is-open .opencodian-settings-dropdown-trigger {
  border-color: color-mix(in srgb, var(--interactive-accent) 34%, var(--background-modifier-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-primary) 92%, var(--interactive-accent)) 0%,
      color-mix(in srgb, var(--background-primary) 88%, var(--background-secondary)) 100%
    );
}

.opencodian-settings-dropdown-trigger:focus-visible {
  outline: none;
  border-color: color-mix(in srgb, var(--interactive-accent) 58%, var(--background-modifier-border));
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--interactive-accent) 22%, transparent),
    0 0 0 4px color-mix(in srgb, var(--interactive-accent) 12%, transparent);
}

.opencodian-settings-dropdown-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-settings-dropdown-chevron {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  color: var(--text-muted);
  transition: color 0.16s ease, transform 0.16s ease;
}

.opencodian-settings-dropdown-chevron svg {
  width: 15px;
  height: 15px;
}

.opencodian-settings-dropdown.is-open .opencodian-settings-dropdown-chevron {
  color: color-mix(in srgb, var(--interactive-accent) 76%, var(--text-normal));
  transform: rotate(180deg);
}

.opencodian-settings-dropdown-menu {
  position: absolute;
  z-index: 1000;
  top: calc(100% + 5px);
  left: 0;
  right: 0;
  display: grid;
  grid-auto-rows: min-content;
  gap: 2px;
  max-height: min(280px, calc(100vh - 96px));
  padding: 5px;
  overflow-y: hidden;
  overflow-x: hidden;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border-hover) 82%, transparent);
  border-radius: 10px;
  background: color-mix(in srgb, var(--background-primary) 96%, var(--background-secondary));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, white 4%, transparent),
    0 18px 36px color-mix(in srgb, var(--background-modifier-box-shadow) 22%, transparent);
}

.opencodian-settings-dropdown-menu.is-hidden {
  display: none;
}

.opencodian-settings-dropdown-menu.is-scrollable {
  overflow-y: auto;
}

/*
 * Portal mode: menu is portaled to document.body via JS to escape
 * overflow:hidden clipping on ancestor card containers.
 * z-index 2001 clears Obsidian's .modal-container at z-index 1000.
 * box-sizing ensures inline width matches trigger dimensions exactly.
 */
.opencodian-settings-dropdown-menu.is-portal {
  position: fixed;
  top: auto;
  left: auto;
  right: auto;
  z-index: 2001;
  box-sizing: border-box;
}

.opencodian-settings-dropdown-option {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  justify-self: stretch;
  min-height: 30px;
  margin: 0;
  padding: 5px 8px 5px 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-normal);
  font-family: var(--font-interface);
  font-size: 13px;
  line-height: 1.35;
  text-align: left;
}

.opencodian-settings-dropdown-option-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: visible;
  white-space: normal;
  overflow-wrap: anywhere;
}

.opencodian-settings-dropdown-option:hover,
.opencodian-settings-dropdown-option.is-highlighted {
  background: color-mix(in srgb, var(--interactive-accent) 13%, transparent);
  color: var(--text-normal);
}

.opencodian-settings-dropdown-option[aria-selected='true'] {
  color: color-mix(in srgb, var(--interactive-accent) 78%, var(--text-normal));
  font-weight: 600;
}

.opencodian-settings-dropdown-option.is-disabled {
  color: var(--text-faint);
  cursor: default;
}

.opencodian-settings-dropdown-option.is-category-header {
  justify-content: center;
  padding-top: 10px;
  padding-bottom: 3px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: default;
  user-select: none;
}

.opencodian-settings-dropdown-option.is-category-header .opencodian-settings-dropdown-option-label {
  flex: 1 1 100%;
  text-align: center;
}

.opencodian-settings-dropdown-option.is-category-header:first-child {
  padding-top: 4px;
}

.opencodian-settings-dropdown-option.is-category-header:hover,
.opencodian-settings-dropdown-option.is-category-header.is-highlighted {
  background: transparent;
  color: var(--text-muted);
}

.opencodian-settings-dropdown-option-check {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
}

.opencodian-settings-dropdown-option-check svg {
  width: 14px;
  height: 14px;
}

.opencodian-settings-dropdown.is-disabled {
  opacity: 0.65;
}

.opencodian-settings-native-select ~ .opencodian-model-picker-provider-select-chevron,
.opencodian-settings-native-select ~ .opencodian-builtin-icon-picker-filter-chevron {
  display: none;
}

.opencodian-model-picker-provider-select-wrap > .opencodian-settings-dropdown,
.opencodian-builtin-icon-picker-filter-wrap > .opencodian-settings-dropdown {
  min-width: 0;
}

.opencodian-model-picker-provider-select-wrap .opencodian-settings-dropdown-trigger,
.opencodian-builtin-icon-picker-filter-wrap .opencodian-settings-dropdown-trigger {
  min-height: 40px;
  padding-left: 14px;
}


/* components/settings-layout-contract.css */
.setting-item.opencodian-settings-direct-host {
  display: block;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.opencodian-settings {
  --opencodian-settings-section-bg:
    color-mix(in srgb, var(--background-secondary) 88%, var(--background-primary));
  --opencodian-settings-section-border:
    color-mix(in srgb, var(--background-modifier-border) 92%, transparent);
  --opencodian-settings-row-bg:
    var(--opencodian-settings-form-row-bg);
  --opencodian-settings-row-border:
    var(--opencodian-settings-form-row-border);
  --opencodian-settings-form-row-bg:
    color-mix(in srgb, var(--background-primary) 94%, var(--background-secondary) 6%);
  --opencodian-settings-form-row-border:
    color-mix(in srgb, var(--background-modifier-border) 88%, transparent);
  --opencodian-settings-form-row-hover-bg:
    color-mix(in srgb, var(--background-primary) 88%, var(--background-secondary) 12%);
  --opencodian-settings-form-row-hover-border:
    color-mix(in srgb, var(--background-modifier-border-hover) 78%, var(--background-modifier-border));
  --opencodian-settings-form-row-radius: 10px;
  --opencodian-settings-form-row-shadow: none;
  --opencodian-settings-object-bg:
    color-mix(in srgb, var(--background-primary) 78%, var(--background-secondary));
  --opencodian-settings-object-border:
    color-mix(in srgb, var(--background-modifier-border-hover) 72%, transparent);
  --opencodian-settings-inline-bg:
    color-mix(in srgb, var(--background-secondary-alt, var(--background-secondary)) 72%, transparent);
  --opencodian-settings-inline-border:
    color-mix(in srgb, var(--background-modifier-border) 64%, transparent);
  --opencodian-settings-nav-bg:
