/* components/settings-claude-code.css */
/* ─── Claude Code settings semantic groups ───────────────────────────── */
/* Spacing tokens scoped to the Claude Code settings block so all five tabs
   (Runtime, Model & Thinking, Permissions, Context & Sources, Tools) share
   the same vertical rhythm. Mirrors the Codex account surface tokens so the
   two backend settings areas feel like one surface. */
.opencodian-settings .opencodian-settings-claude-code-block {
  --oc-claude-card-gap: 10px;
  --oc-claude-group-header-gap: 12px;
  --oc-claude-card-title-body-gap: 8px;
  --oc-claude-card-body-gap: 10px;
  --oc-claude-card-padding: 12px 14px;
  --oc-claude-control-min-width: 220px;
  --oc-claude-readback-row-bg:
    color-mix(in srgb, var(--background-primary) 74%, var(--background-secondary));
  --oc-claude-readback-row-border:
    color-mix(in srgb, var(--background-modifier-border) 72%, transparent);
}

.opencodian-settings .opencodian-claude-code-tab-body,
.opencodian-settings .opencodian-settings-claude-code-tab-body {
  display: flex;
  flex-direction: column;
  gap: var(--oc-claude-card-gap);
}

/* Group is a FLAT semantic container (margin only), not a card.
   Card base (border + radius + bg + padding) is applied to the
   setting-items / notices / readbacks inside the group stack, keeping
   the DOM at two card levels max: section-card → setting-item-card. */
.opencodian-settings .opencodian-claude-code-group,
.opencodian-settings .opencodian-settings-claude-code-group {
  display: flex;
  flex-direction: column;
  margin: 0;
}

.opencodian-settings .opencodian-claude-code-group + .opencodian-claude-code-group,
.opencodian-settings .opencodian-settings-claude-code-group + .opencodian-settings-claude-code-group {
  margin-top: var(--oc-claude-card-gap);
}

.opencodian-settings .opencodian-claude-code-group-header,
.opencodian-settings .opencodian-settings-claude-code-group-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: var(--opencodian-settings-space-sm);
  margin: 0;
  padding: 0;
}

.opencodian-settings .opencodian-claude-code-group-title,
.opencodian-settings .opencodian-settings-claude-code-group-title {
  margin: 0;
  padding: 0;
  padding-inline-start: 0;
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--text-normal);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
}

/* Group description collapsed into a compact help-circle button beside the
   title. The full description shows on hover/focus via data-settings-tooltip.
   Mirrors the opencodian-skill-permission-help-button affordance. */
.opencodian-settings .opencodian-claude-code-group-help-button {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: var(--opencodian-settings-radius-inline);
  background: transparent;
  padding: 0;
  color: var(--text-faint);
  cursor: help;
}

.opencodian-settings .opencodian-claude-code-group-help-button:hover,
.opencodian-settings .opencodian-claude-code-group-help-button:focus-visible {
  background: var(--opencodian-settings-inline-bg);
  color: var(--text-normal);
}

.opencodian-settings .opencodian-claude-code-group-help-button:focus-visible {
  outline: 2px solid var(--opencodian-settings-focus-ring);
  outline-offset: 2px;
  border-radius: var(--opencodian-settings-radius-inline);
}

.opencodian-settings .opencodian-claude-code-group-desc,
.opencodian-settings .opencodian-settings-claude-code-group-desc {
  margin: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

/* Group controls (the inner stack) sit one header-gap below the header.
   setting-items / notices / readbacks inside the stack become the
   level-2 card surfaces. */
.opencodian-settings .opencodian-claude-code-stack,
.opencodian-settings .opencodian-settings-claude-code-group-stack {
  display: flex;
  flex-direction: column;
  gap: var(--oc-claude-card-gap);
  margin-top: var(--oc-claude-group-header-gap);
}

/* Level-2 card base applied to every control/notice inside a Claude Code
   group, so they read as the same surface vocabulary as Codex. */
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-stack > .setting-item,
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-settings-claude-code-group-stack > .setting-item,
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-settings-proof-status,
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-settings-readback,
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-readback {
  margin: 0;
  padding: var(--oc-claude-card-padding);
  border: 1px solid var(--opencodian-settings-row-border);
  border-radius: var(--opencodian-settings-radius-row);
  background: var(--opencodian-settings-row-bg);
  box-shadow: none;
}

.opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-stack > .setting-item,
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-settings-claude-code-group-stack > .setting-item {
  display: grid;
  /* Container-relative floors: without a real min on the label track the
     fixed-floor control track wins all free space and the label collapses
     to 0 in narrow settings panes (viewport may still be above 720px). */
  grid-template-columns: minmax(min(160px, 45%), 1fr) minmax(min(var(--oc-claude-control-min-width), 50%), max-content);
  gap: var(--opencodian-settings-space-md) var(--opencodian-settings-space-xl);
  align-items: center;
}

.opencodian-settings .opencodian-settings-claude-code-block .setting-item-info {
  min-width: 0;
}

.opencodian-settings .opencodian-settings-claude-code-block .setting-item-name {
  color: var(--text-normal);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.4;
}

.opencodian-settings .opencodian-settings-claude-code-block .setting-item-description {
  max-width: 72ch;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.55;
}

.opencodian-settings .opencodian-settings-claude-code-block .setting-item-control {
  display: flex;
  flex-wrap: wrap;
  gap: var(--opencodian-settings-space-sm);
  justify-content: flex-end;
  min-width: 0;
}

.opencodian-settings .opencodian-settings-claude-code-block .setting-item-control input[type="text"],
.opencodian-settings .opencodian-settings-claude-code-block .setting-item-control input[type="password"],
.opencodian-settings .opencodian-settings-claude-code-block .setting-item-control select {
  min-height: 30px;
  border-radius: var(--opencodian-settings-radius-inline);
}

.opencodian-settings .opencodian-settings-claude-code-block .setting-item-control textarea {
  width: min(520px, 100%);
  min-height: 92px;
  border-radius: var(--opencodian-settings-radius-inline);
  line-height: 1.5;
  resize: vertical;
}

.opencodian-settings .opencodian-claude-code-inline-meta,
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-settings-inline-meta {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.opencodian-settings .opencodian-settings-claude-code-block h5 {
  margin: 0;
  color: var(--text-normal);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.35;
}

.opencodian-settings .opencodian-settings-claude-code-block p,
.opencodian-settings .opencodian-settings-claude-code-block ul,
.opencodian-settings .opencodian-settings-claude-code-block pre {
  margin-block: 0;
}

.opencodian-settings .opencodian-settings-claude-code-block ul {
  padding-inline-start: 18px;
}

/* Advanced sandbox: stays visually de-emphasized via opacity + a muted
   summary title, but no longer stacks a second border/background on top
   of the group card (the group itself is now flat). */
.opencodian-settings .opencodian-claude-code-advanced,
.opencodian-settings .opencodian-settings-advanced-sandbox {
  margin-top: var(--oc-claude-card-gap);
}

.opencodian-settings .opencodian-claude-code-advanced-summary {
  color: var(--text-normal);
  font-size: 12px;
  font-weight: 700;
}

.opencodian-settings .opencodian-claude-code-advanced .setting-item,
.opencodian-settings .opencodian-claude-code-advanced .opencodian-settings-inline-notice,
.opencodian-settings .opencodian-claude-code-advanced .opencodian-claude-code-group-desc,
.opencodian-settings .opencodian-settings-advanced-sandbox .setting-item,
.opencodian-settings .opencodian-settings-advanced-sandbox .opencodian-settings-inline-notice,
.opencodian-settings .opencodian-settings-advanced-sandbox .opencodian-settings-claude-code-group-desc {
  opacity: 0.86;
}

/* ─── Claude Code group notices (compact, state-honest) ─────────────── */
/* Inline notices inside a group stack are level-2 card strips, matching
   the setting-item card base but with state-tinted fills. */
.opencodian-settings .opencodian-claude-code-group .opencodian-settings-inline-notice,
.opencodian-settings .opencodian-settings-claude-code-group .opencodian-settings-inline-notice {
  margin: 0;
  padding: 8px 10px;
  border-radius: var(--opencodian-settings-radius-inline);
  font-size: 12px;
  line-height: 1.45;
}

.opencodian-settings .opencodian-claude-code-notice--boundary {
  background: color-mix(in srgb, var(--text-accent) 5%, var(--opencodian-settings-row-bg));
  border: 1px solid color-mix(in srgb, var(--text-accent) 14%, var(--opencodian-settings-row-border));
}

.opencodian-settings .opencodian-claude-code-notice--lifecycle {
  background: color-mix(in srgb, var(--text-warning, var(--color-yellow)) 4%, var(--opencodian-settings-row-bg));
  border: 1px solid color-mix(in srgb, var(--text-warning, var(--color-yellow)) 12%, var(--opencodian-settings-row-border));
  color: var(--text-muted);
}

/* ─── Claude Code settings proof-status notices ─────────────────────── */
.opencodian-settings .opencodian-settings-proof-status {
  display: flex;
  align-items: center;
  gap: var(--opencodian-settings-space-sm);
  padding: 8px 10px;
  border-radius: var(--opencodian-settings-radius-inline);
  background: var(--opencodian-settings-row-bg);
  border: 1px solid var(--opencodian-settings-row-border);
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.opencodian-settings .opencodian-settings-proof-status[data-proof-state="pass"] {
  background: color-mix(in srgb, var(--text-success, var(--color-green)) 6%, var(--opencodian-settings-row-bg));
  border-color: color-mix(in srgb, var(--text-success, var(--color-green)) 18%, var(--opencodian-settings-row-border));
  color: color-mix(in srgb, var(--text-success, var(--color-green)) 84%, var(--text-normal));
}

.opencodian-settings .opencodian-settings-proof-status[data-proof-state="readback"] {
  background: color-mix(in srgb, var(--text-accent) 6%, var(--opencodian-settings-row-bg));
  border-color: color-mix(in srgb, var(--text-accent) 16%, var(--opencodian-settings-row-border));
  color: color-mix(in srgb, var(--text-accent) 72%, var(--text-normal));
}

.opencodian-settings .opencodian-settings-proof-status[data-proof-state="wiring"] {
  background: color-mix(in srgb, var(--text-warning, var(--color-yellow)) 6%, var(--opencodian-settings-row-bg));
  border-color: color-mix(in srgb, var(--text-warning, var(--color-yellow)) 18%, var(--opencodian-settings-row-border));
  color: color-mix(in srgb, var(--text-warning, var(--color-yellow)) 78%, var(--text-normal));
}

.opencodian-settings .opencodian-claude-code-readback,
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-settings-readback {
  display: flex;
  flex-direction: column;
  gap: var(--oc-claude-card-body-gap);
  padding: var(--oc-claude-card-padding);
  border-radius: var(--opencodian-settings-radius-row);
  background: color-mix(in srgb, var(--text-accent) 4%, var(--opencodian-settings-row-bg));
  border: 1px solid color-mix(in srgb, var(--text-accent) 12%, var(--opencodian-settings-row-border));
}

.opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-runtime-ecosystem-row,
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-mcp-runtime-status-row {
  padding: 8px 10px;
  border: 1px solid var(--oc-claude-readback-row-border);
  border-radius: var(--opencodian-settings-radius-inline);
  background: var(--oc-claude-readback-row-bg);
}

.opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-runtime-ecosystem-row[data-runtime-ecosystem-state="loaded"],
.opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-runtime-ecosystem-row[data-runtime-ecosystem-state="all"] {
  border-color: color-mix(in srgb, var(--text-accent) 18%, var(--oc-claude-readback-row-border));
}

.opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-mcp-runtime-status-row {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-xs);
}

/* ─── Collapsed notice text (sr-only carrier) ───────────────────────── */
/* Boundary/lifecycle/proof notice text was collapsed out of the dense
   settings surface into help buttons + tooltips. To keep `textContent`
   assertions and screen readers honest, the text lives in a visually-hidden
   span attached to the setting-item. CSS visually hides it while keeping
   the text in the accessibility tree and DOM textContent. */
.opencodian-settings .opencodian-claude-code-notice-text {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ─── Proof-status chip ─────────────────────────────────────────────── */
/* Proof-status (pass/readback) collapsed from a full notice strip into a
   compact colored chip beside the setting control. Green = pass,
   blue/accent = readback. Tooltip (data-settings-tooltip) carries the
   evidence text. The data-proof-state attribute is preserved on the chip
   so proof-status semantics and tests remain stable. */
.opencodian-settings .opencodian-claude-code-proof-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 10px;
  height: 10px;
  margin-inline-start: var(--opencodian-settings-space-sm);
  border-radius: 999px;
  background: var(--opencodian-settings-row-border);
  vertical-align: middle;
  cursor: help;
}

.opencodian-settings .opencodian-claude-code-proof-chip:focus-visible {
  outline: 2px solid var(--opencodian-settings-focus-ring);
  outline-offset: 3px;
}

.opencodian-settings .opencodian-claude-code-proof-chip[data-proof-state="pass"] {
  background: var(--text-success, var(--color-green));
}

.opencodian-settings .opencodian-claude-code-proof-chip[data-proof-state="readback"] {
  background: var(--text-accent);
}

.opencodian-settings .opencodian-claude-code-proof-chip[data-proof-state="wiring"] {
  background: var(--text-warning, var(--color-yellow));
}

@media (max-width: 720px) {
  .opencodian-settings .opencodian-settings-claude-code-block .opencodian-claude-code-stack > .setting-item,
  .opencodian-settings .opencodian-settings-claude-code-block .opencodian-settings-claude-code-group-stack > .setting-item {
    grid-template-columns: minmax(0, 1fr);
  }

  .opencodian-settings .opencodian-settings-claude-code-block .setting-item-control {
    justify-content: flex-start;
  }

  .opencodian-settings .opencodian-settings-claude-code-block .setting-item-control input[type="text"],
  .opencodian-settings .opencodian-settings-claude-code-block .setting-item-control input[type="password"],
  .opencodian-settings .opencodian-settings-claude-code-block .setting-item-control select,
  .opencodian-settings .opencodian-settings-claude-code-block .setting-item-control textarea {
    width: 100%;
  }
}

/* Claude configuration workbench (context-sources tab). Flat, native, theme-driven. */
.opencodian-claude-configuration {
  display: flex;
  flex-direction: column;
  gap: var(--size-4-2, 8px);
  min-inline-size: 0;
}

.opencodian-claude-configuration-source-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--size-4-2, 8px);
  align-items: center;
  color: var(--text-normal);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-readonly {
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-target-path,
.opencodian-claude-configuration-summary-path,
.opencodian-claude-configuration-source-path {
  display: flex;
  flex-wrap: wrap;
  min-inline-size: 0;
  max-inline-size: 100%;
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
}

.opencodian-claude-configuration-path-segment {
  min-inline-size: 0;
  max-inline-size: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opencodian-claude-configuration-evidence {
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-source-meta {
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-editor {
  display: flex;
  flex-direction: column;
  gap: var(--size-4-2, 8px);
  min-inline-size: 0;
}

.opencodian-claude-configuration-draft {
  width: 100%;
  min-height: 18em;
  font-family: var(--font-monospace);
  font-size: var(--font-smaller);
  resize: vertical;
}

/* Compare is a read-only, inline evidence view. It preserves JSON whitespace
   while wrapping otherwise unbreakable lines inside narrow Obsidian panes;
   overflow remains locally scrollable rather than widening the Settings UI. */
.opencodian-claude-configuration-compare-output {
  box-sizing: border-box;
  max-inline-size: 100%;
  margin: 0;
  overflow: auto;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  line-height: 1.5;
}

.opencodian-claude-configuration-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--size-4-2, 8px);
  align-items: center;
}

.opencodian-claude-configuration-status[data-claude-config-status-level='ok'] { color: var(--text-success, var(--text-normal)); }
.opencodian-claude-configuration-status[data-claude-config-status-level='error'] { color: var(--text-error); }
.opencodian-claude-configuration-status[data-claude-config-status-level='warn'] { color: var(--text-warning, var(--text-muted)); }

.opencodian-claude-configuration-diagnostic {
  color: var(--text-error);
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  white-space: pre-wrap;
  word-break: break-word;
}

.opencodian-claude-configuration-error {
  color: var(--text-error);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-history-error {
  color: var(--text-error);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-form,
.opencodian-claude-configuration-hooks,
.opencodian-claude-configuration-history {
  display: flex;
  flex-direction: column;
  gap: var(--size-4-1, 4px);
}

.opencodian-claude-configuration-field-row,
.opencodian-claude-configuration-hook-group,
.opencodian-claude-configuration-hook-handler,
.opencodian-claude-configuration-history-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--size-4-1, 4px);
  padding: var(--size-4-1, 4px) 0;
}

.opencodian-claude-configuration-field-label {
  flex: 1 1 14rem;
  color: var(--text-normal);
}

.opencodian-claude-configuration-field,
.opencodian-claude-configuration-hook-group input,
.opencodian-claude-configuration-hook-handler input,
.opencodian-claude-configuration-hook-handler select {
  min-width: min(100%, 14rem);
  flex: 1 1 14rem;
}

.opencodian-claude-configuration-source-path,
.opencodian-claude-configuration-source-revision,
.opencodian-claude-configuration-hooks-evidence,
.opencodian-claude-configuration-history-meta {
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
  overflow-wrap: anywhere;
}

.opencodian-claude-configuration-source-path {
  overflow-wrap: normal;
}

.opencodian-claude-configuration-hook-event,
.opencodian-claude-configuration-history {
  border-block-start: 1px solid var(--background-modifier-border);
  padding-block-start: var(--size-4-2, 8px);
}

.opencodian-claude-configuration-hook-handler,
.opencodian-claude-configuration-history-row {
  background: var(--background-secondary-alt, var(--background-secondary));
}

.opencodian-claude-configuration button:focus-visible,
.opencodian-claude-configuration select:focus-visible,
.opencodian-claude-configuration input:focus-visible,
.opencodian-claude-configuration textarea:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

/* Current editing summary: compact context bar answering scope, target,
   presence, writable, dirty state, and the three independent evidence axes. */
.opencodian-claude-configuration-summary {
  display: flex;
  flex-direction: column;
  gap: var(--size-4-1, 4px);
  padding: var(--size-4-2, 8px) var(--size-4-3, 12px);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s, 6px);
  background: var(--background-secondary-alt, var(--background-secondary));
  min-inline-size: 0;
}

.opencodian-claude-configuration-summary-line {
  display: flex;
  flex-wrap: wrap;
  gap: var(--size-4-1, 4px) var(--size-4-2, 8px);
  align-items: center;
  min-inline-size: 0;
}

.opencodian-claude-configuration-summary-path {
  flex: 1 1 12rem;
  color: var(--text-normal);
}

.opencodian-claude-configuration-summary-evidence {
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-chip {
  display: inline-flex;
  align-items: center;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid var(--background-modifier-border);
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
  white-space: nowrap;
}

.opencodian-claude-configuration-summary-dirty.is-dirty {
  color: var(--text-warning, var(--color-yellow));
  border-color: color-mix(in srgb, var(--text-warning, var(--color-yellow)) 40%, var(--background-modifier-border));
}

.opencodian-claude-configuration-copy-path {
  padding: 0 4px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
}

.opencodian-claude-configuration-copy-path:hover {
  color: var(--text-normal);
}

/* Persistent Global-scope warning: visible only while Global is selected. */
.opencodian-claude-configuration-global-warning {
  padding: var(--size-4-2, 8px) var(--size-4-3, 12px);
  border: 1px solid color-mix(in srgb, var(--text-warning, var(--color-yellow)) 30%, var(--background-modifier-border));
  border-radius: var(--radius-s, 6px);
  background: color-mix(in srgb, var(--text-warning, var(--color-yellow)) 6%, var(--background-primary));
  color: var(--text-normal);
  font-size: var(--font-ui-smaller);
  overflow-wrap: anywhere;
}

/* Unsaved-draft switch decision: inline, quiet, with the target in context. */
.opencodian-claude-configuration-switch-confirm {
  display: flex;
  flex-wrap: wrap;
  gap: var(--size-4-2, 8px);
  align-items: center;
  padding: var(--size-4-2, 8px) var(--size-4-3, 12px);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s, 6px);
  background: var(--background-secondary-alt, var(--background-secondary));
}

.opencodian-claude-configuration-confirm-text {
  flex: 1 1 100%;
  color: var(--text-normal);
  font-size: var(--font-ui-smaller);
  overflow-wrap: anywhere;
}

/* Disclosure toggles: full-width quiet buttons, never another card layer. */
.opencodian-claude-configuration-disclosure-toggle {
  display: flex;
  align-items: center;
  gap: var(--size-4-2, 8px);
  inline-size: 100%;
  padding: var(--size-4-1, 4px) 2px;
  background: transparent;
  border: none;
  color: var(--text-normal);
  font-size: var(--font-ui-medium);
  font-weight: 600;
  text-align: start;
  cursor: pointer;
}

.opencodian-claude-configuration-disclosure-toggle::before {
  content: '▸';
  color: var(--text-faint);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-disclosure-toggle[aria-expanded='true']::before {
  content: '▾';
}

.opencodian-claude-configuration-disclosure-toggle:hover {
  color: var(--text-accent, var(--interactive-accent));
}

/* Source inventory rows: human layer first, technical details behind a
   per-row disclosure so first-screen weight stays low. */
.opencodian-claude-configuration-source-row {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--size-4-1, 4px);
  padding: var(--size-4-1, 4px) 0;
}

.opencodian-claude-configuration-source-head {
  display: flex;
  flex-wrap: wrap;
  gap: var(--size-4-1, 4px) var(--size-4-2, 8px);
  align-items: center;
  color: var(--text-normal);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-evidence-human {
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-source-tech {
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-configuration-source-tech > summary {
  color: var(--text-faint);
  cursor: pointer;
}

.opencodian-claude-configuration-source-tech > summary:hover {
  color: var(--text-muted);
}

.opencodian-claude-configuration-source-tech > span {
  display: block;
}

/* Screen-reader-only live-region carriers: visually hidden, still announced. */
.opencodian-claude-configuration-live-region {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.opencodian-claude-configuration-hooks-event-filter {
  min-width: min(100%, 10rem);
  flex: 1 1 10rem;
}

.opencodian-claude-configuration [aria-invalid='true'] {
  border-color: var(--text-error) !important;
}

@media (max-width: 520px) {
  .opencodian-claude-configuration-field-label,
  .opencodian-claude-configuration-field,
  .opencodian-claude-configuration-hook-group input,
  .opencodian-claude-configuration-hook-handler input,
  .opencodian-claude-configuration-hook-handler select {
    flex-basis: 100%;
    min-width: 0;
  }
}


/* components/settings-pi.css */
.opencodian-settings .opencodian-pi-settings {
  min-width: 0;
}

/* Native details lay out their contents as blocks; ordinary form hosts use
   the shared stack so gaps also survive nested editors and empty statuses. */
.opencodian-settings .opencodian-pi-model-editor > .setting-item + .setting-item {
  margin-top: var(--opencodian-settings-space-lg, 12px);
}

.opencodian-settings .opencodian-pi-settings .opencodian-settings-section-body,
.opencodian-pi-models {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-lg, 12px);
  min-width: 0;
}

.opencodian-pi-models:empty {
  display: none;
}

/* Keep live regions mounted, without an extra empty track between cards. */
.opencodian-pi-settings [role='status']:empty {
  position: absolute;
  margin: 0;
}

.opencodian-pi-settings h3 {
  margin: 0 0 var(--opencodian-settings-space-lg, 12px);
  font-size: var(--font-ui-medium);
}

.opencodian-pi-config-status {
  color: var(--text-normal);
  overflow-wrap: anywhere;
  margin-block: var(--opencodian-settings-space-md, 8px);
}

.opencodian-pi-settings .setting-item-description {
  overflow-wrap: anywhere;
}

/* Pi extensions report their status as text; show it verbatim, not as a card that
   implies the plugin parsed it into structure it does not have. */
.opencodian-pi-mcp-status {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: var(--opencodian-settings-space-md, 8px) var(--opencodian-settings-space-lg, 12px);
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
  background: var(--background-secondary);
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  color: var(--text-normal);
}

.opencodian-pi-mcp-status-line,
.opencodian-pi-mcp-status-message {
  overflow-wrap: anywhere;
}

.opencodian-pi-mcp-status-message {
  color: var(--text-muted);
}

.opencodian-pi-mcp-status:empty {
  display: none;
}

.opencodian-pi-mcp-sources {
  font-size: var(--font-ui-smaller);
  color: var(--text-faint);
}

.opencodian-pi-config-multiline {
  flex-wrap: wrap;
}

.opencodian-pi-config-multiline .setting-item-control {
  flex: 1 1 100%;
  min-width: 0;
}

.opencodian-pi-config-multiline textarea,
.opencodian-pi-json-editor {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  resize: vertical;
  font-family: var(--font-monospace);
  line-height: 1.5;
  color: var(--text-normal);
  background: var(--background-primary);
  caret-color: var(--text-accent);
}

.opencodian-pi-config-advanced,
.opencodian-pi-model-editor {
  margin-block: var(--opencodian-settings-space-xl, 16px);
}

.opencodian-settings-form-stack > .opencodian-pi-config-advanced,
.opencodian-pi-models > .opencodian-pi-model-editor {
  margin-block: 0;
}

.opencodian-pi-settings summary {
  cursor: pointer;
  color: var(--text-normal);
  font-weight: var(--font-semibold);
  padding-block: var(--opencodian-settings-space-md, 8px);
}

.opencodian-pi-settings summary:focus-visible,
.opencodian-pi-json-editor:focus-visible {
  outline: 2px solid var(--opencodian-settings-focus-ring, var(--interactive-accent));
  outline-offset: 2px;
}


/* components/settings-codex-account.css */
/* Codex account & capability product surface cards.
   Renders account identity, token usage, rate limits, and provider
   capabilities as real settings cards — not JSON-dump readbacks.
   Card interiors stay flat: stat rows, data rows, and capability rows
   never nest another card surface inside the card. */

/* Fixed spacing tokens for all Codex settings subtabs (Connection,
   Resume & Inspect, Account). Scoped to the Codex block so they do
   not leak into other settings surfaces. */
.opencodian-settings-codex-block {
  --oc-codex-card-gap: 12px;
  --oc-codex-group-title-desc-gap: 4px;
  --oc-codex-group-header-gap: 16px;
  --oc-codex-card-title-body-gap: 8px;
  --oc-codex-card-body-gap: 10px;
  --oc-codex-card-padding: 14px 16px;
}

/* Shared card base used by account cards, readback outputs, info notices,
   and the connection summary strip. */
.opencodian-codex-account-card,
.opencodian-settings-codex-card,
.opencodian-settings-codex-readback,
.opencodian-settings-codex-connection-summary,
.opencodian-settings .opencodian-settings-codex-block .opencodian-settings-codex-group-controls > .setting-item {
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  padding: var(--oc-codex-card-padding);
  background: var(--background-secondary);
  box-shadow: none;
}

/* Vertical stack for cards/setting rows inside a Codex subtab group. */
.opencodian-settings-codex-group-stack {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-gap);
}

.opencodian-codex-account-card {
  margin: 0;
}

.opencodian-codex-account-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: var(--oc-codex-card-title-body-gap);
}

.opencodian-settings .opencodian-codex-account-card-title {
  margin: 0;
  padding: 0;
  padding-inline-start: 0;
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: var(--font-ui-small);
  font-weight: 600;
  color: var(--text-normal);
}

/* Ghost refresh actions: per-card and group-level "refresh all" share one
   quiet treatment so repeated actions never compete with readback content. */
.opencodian-codex-account-card-refresh,
.opencodian-codex-account-refresh-all {
  flex-shrink: 0;
  appearance: none;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  box-shadow: none;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  font-weight: 500;
  line-height: 1.4;
  padding: 2px 8px;
  cursor: pointer;
  transition:
    color 150ms ease-out,
    background-color 150ms ease-out;
}

.opencodian-codex-account-card-refresh:hover,
.opencodian-codex-account-refresh-all:hover {
  background: var(--background-modifier-hover);
  color: var(--text-normal);
}

.opencodian-codex-account-card-refresh:focus-visible,
.opencodian-codex-account-refresh-all:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-codex-account-card-refresh,
  .opencodian-codex-account-refresh-all {
    transition: none;
  }
}

.opencodian-codex-account-card-body {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-body-gap);
}

.opencodian-codex-account-card-loading,
.opencodian-codex-account-card-muted {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

/* Identity summary */
.opencodian-codex-account-identity-overview {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-body-gap);
}

.opencodian-codex-account-identity-primary {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.opencodian-settings .opencodian-codex-account-identity-title {
  margin: 0;
  padding: 0;
  padding-inline-start: 0;
  font-size: var(--font-ui-small);
  font-weight: 600;
  color: var(--text-normal);
  line-height: 1.3;
}

.opencodian-codex-account-identity-detail {
  font-size: var(--font-ui-small);
  color: var(--text-muted);
  line-height: 1.4;
}

.opencodian-codex-account-identity-detail-label {
  margin-right: 4px;
}

.opencodian-codex-account-identity-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.opencodian-codex-account-identity-chip {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
  color: var(--text-muted);
  font-size: var(--font-smallest);
  line-height: 1.3;
}

.opencodian-codex-account-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: var(--font-smallest);
  font-weight: 600;
  letter-spacing: 0.02em;
  border: 1px solid transparent;
}

.opencodian-codex-account-badge.is-chatgpt {
  background: rgba(var(--color-green-rgb, 76, 175, 80), 0.16);
  color: var(--color-green, #4caf50);
  border-color: rgba(var(--color-green-rgb, 76, 175, 80), 0.4);
}

.opencodian-codex-account-badge.is-apikey {
  background: var(--background-modifier-hover);
  color: var(--text-muted);
  border-color: var(--background-modifier-border);
}

/* Key/value rows */
.opencodian-codex-account-rows {
  display: grid;
  grid-template-columns: repeat(2, minmax(180px, 1fr));
  gap: 8px 12px;
  min-width: 0;
}

.opencodian-codex-account-row {
  display: grid;
  grid-template-columns: minmax(84px, max-content) minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  font-size: var(--font-ui-small);
  padding: 0;
  min-width: 0;
}

.opencodian-codex-account-row-label {
  color: var(--text-muted);
  line-height: 1.4;
}

.opencodian-codex-account-row-value {
  color: var(--text-normal);
  word-break: break-word;
  line-height: 1.4;
}

@media (max-width: 720px) {
  .opencodian-codex-account-row {
    grid-template-columns: 1fr;
    gap: 2px;
  }

  .opencodian-codex-account-rows {
    grid-template-columns: 1fr;
  }
}

/* Usage stat row: flat value-over-label pairs. No tile borders or fills —
   the numbers carry the hierarchy, spacing carries the grouping. */
.opencodian-codex-account-tiles {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 28px;
}

.opencodian-codex-account-stat-tile {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 72px;
}

.opencodian-codex-account-stat-tile-value {
  margin: 0;
  font-size: var(--font-ui-medium);
  font-weight: 700;
  color: var(--text-normal);
  line-height: 1.25;
}

.opencodian-codex-account-stat-tile-label {
  margin: 0;
  font-size: var(--font-smallest);
  color: var(--text-muted);
}

/* Usage daily buckets bar chart: solid accent bars (no gradient), a real
   label row under the chart, and hover feedback instead of 8px overflow
   labels absolutely positioned outside the bar. */
.opencodian-codex-account-usage-buckets {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-title-body-gap);
  border-top: 1px solid var(--background-modifier-border);
  padding-top: var(--oc-codex-card-body-gap);
}

.opencodian-settings .opencodian-codex-account-usage-buckets-title {
  margin: 0;
  padding: 0;
  padding-inline-start: 0;
  font-size: var(--font-smallest);
  color: var(--text-muted);
  font-weight: 600;
}

.opencodian-codex-account-usage-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 48px;
}

.opencodian-codex-account-usage-bar {
  flex: 1;
  min-width: 6px;
  min-height: 3px;
  background: var(--interactive-accent);
  opacity: 0.55;
  border-radius: 2px 2px 0 0;
  transition: opacity 150ms ease-out;
}

.opencodian-codex-account-usage-bar:hover {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-codex-account-usage-bar {
    transition: none;
  }
}

.opencodian-codex-account-usage-labels {
  display: flex;
  gap: 3px;
  margin-top: 0;
}

.opencodian-codex-account-usage-bar-label {
  flex: 1;
  min-width: 6px;
  font-size: 9px;
  line-height: 1.3;
  color: var(--text-faint);
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
}

/* Rate-limit tier groups */
.opencodian-codex-account-rate-limit-groups {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-title-body-gap);
  margin-top: 0;
}

.opencodian-codex-account-rate-limit-group {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-title-body-gap);
  border-top: 1px solid var(--background-modifier-border);
  padding-top: 8px;
  margin-top: 0;
}

.opencodian-settings .opencodian-codex-account-rate-limit-group-title {
  margin: 0;
  padding: 0;
  padding-inline-start: 0;
  font-size: var(--font-smallest);
  font-weight: 600;
  color: var(--text-muted);
  text-transform: capitalize;
}

/* Capability rows: flat list with hairline separators and a status badge.
   No nested card borders/backgrounds inside the capabilities card. */
.opencodian-codex-account-capability-chips {
  display: flex;
  flex-direction: column;
}

.opencodian-codex-account-capability-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
}

.opencodian-codex-account-capability-chip + .opencodian-codex-account-capability-chip {
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-codex-account-capability-chip-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 700;
}

.opencodian-codex-account-capability-chip.is-enabled .opencodian-codex-account-capability-chip-icon {
  background: rgba(var(--color-green-rgb, 76, 175, 80), 0.2);
  color: var(--color-green, #4caf50);
}

.opencodian-codex-account-capability-chip.is-disabled .opencodian-codex-account-capability-chip-icon {
  background: var(--background-modifier-hover);
  color: var(--text-muted);
}

.opencodian-codex-account-capability-chip-text {
  flex: 1;
  min-width: 0;
}

.opencodian-codex-account-capability-chip-label {
  margin: 0;
  font-size: var(--font-ui-small);
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-codex-account-capability-chip-desc {
  margin: 1px 0 0;
  font-size: var(--font-smallest);
  color: var(--text-muted);
}

.opencodian-codex-account-capability-chip-status {
  flex-shrink: 0;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: var(--font-smallest);
  font-weight: 600;
  line-height: 1.4;
}

.opencodian-codex-account-capability-chip.is-enabled .opencodian-codex-account-capability-chip-status {
  background: rgba(var(--color-green-rgb, 76, 175, 80), 0.12);
  color: var(--color-green, #4caf50);
}

.opencodian-codex-account-capability-chip.is-disabled .opencodian-codex-account-capability-chip-status {
  background: var(--background-modifier-hover);
  color: var(--text-faint);
}

/* Auth-required / info notices. The full block form lives only on the
   identity card (authoritative explanation); usage and rate-limit cards
   use the compact single-line variant. */
.opencodian-codex-account-card-notice {
  border: 1px solid var(--color-yellow, #e8a33d);
  border-radius: 6px;
  padding: 8px 10px;
  background: rgba(var(--color-yellow-rgb, 232, 163, 61), 0.12);
  font-size: var(--font-ui-small);
  color: var(--text-normal);
  margin-top: 0;
}

.opencodian-codex-account-card-notice.is-auth-required {
  border-color: var(--color-yellow, #e8a33d);
}

.opencodian-codex-account-card-notice.is-compact {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 6px;
  padding: 6px 10px;
}

.opencodian-codex-account-card-notice-title {
  font-weight: 600;
}

.opencodian-codex-account-card-notice-hint {
  color: var(--text-muted);
}

.opencodian-codex-account-card-code {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--background-modifier-hover);
  border: 1px solid var(--background-modifier-border);
  font-family: var(--font-monospace);
  font-size: var(--font-smallest);
  color: var(--text-normal);
}

/* Codex settings section groups */
.opencodian-settings-codex-group {
  margin: 0;
}

.opencodian-settings-codex-group + .opencodian-settings-codex-group {
  margin-top: var(--oc-codex-card-gap);
}

/* Group header row: title/description on the left, the group-level
   refresh-all action pinned to the right of the first line. */
.opencodian-settings-codex-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.opencodian-settings-codex-group-header-text {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-group-title-desc-gap);
  min-width: 0;
}

.opencodian-settings .opencodian-settings-codex-group-title {
  margin: 0;
  /* Beat Obsidian's `.vertical-tab-content h4` horizontal padding so the
     title text starts at the same edge as the group description. */
  padding: 0;
  padding-inline-start: 0;
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: var(--font-ui-small);
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-settings-codex-group-desc {
  margin: 0;
  font-size: var(--font-ui-small);
  color: var(--text-muted);
  line-height: 1.4;
}

.opencodian-settings-codex-group-controls {
  margin-top: var(--oc-codex-group-header-gap);
}

.opencodian-settings .opencodian-settings-codex-block .opencodian-settings-codex-group-controls > .setting-item {
  margin: 0;
}

.opencodian-settings .opencodian-settings-codex-block .opencodian-settings-codex-group-controls > .setting-item .setting-item-name + .setting-item-description {
  margin-top: var(--oc-codex-card-title-body-gap);
}

/* Connection summary strip */
.opencodian-settings-codex-connection-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: var(--oc-codex-group-header-gap);
  font-size: var(--font-ui-small);
}

.opencodian-settings-codex-connection-summary-label {
  color: var(--text-muted);
  flex-shrink: 0;
}

.opencodian-settings-codex-connection-summary-value {
  color: var(--text-normal);
  font-weight: 500;
}

/* Native Codex Provider configuration is intentionally an external-managed
   read-only diagnostic. Keep this compact strip separate from the account
   cards so it does not imply a local save/edit surface. */
.opencodian-codex-provider-configuration-status {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 12px;
  align-items: start;
  margin-bottom: var(--oc-codex-group-header-gap);
  padding: 10px 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
  background: var(--background-secondary);
  min-width: 0;
}

.opencodian-codex-provider-configuration-status-header {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.opencodian-settings .opencodian-codex-provider-configuration-status-title {
  margin: 0;
  padding: 0;
  padding-inline-start: 0;
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: var(--font-ui-small);
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-codex-provider-configuration-status-state {
  justify-self: end;
  color: var(--text-muted);
  font-size: var(--font-smallest);
  font-weight: 600;
  white-space: nowrap;
}

.opencodian-codex-provider-configuration-status-description,
.opencodian-codex-provider-configuration-status-source,
.opencodian-codex-provider-configuration-status-capabilities {
  grid-column: 1 / -1;
  min-width: 0;
  color: var(--text-muted);
  font-size: var(--font-smallest);
  line-height: 1.4;
}

.opencodian-codex-provider-configuration-status-source {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 6px;
}

.opencodian-codex-provider-configuration-status-source-label {
  flex-shrink: 0;
}

.opencodian-codex-provider-configuration-status-source-value {
  min-width: 0;
  color: var(--text-normal);
  overflow-wrap: anywhere;
}

.opencodian-settings-codex-legacy-credential-status {
  min-width: 0;
}

.opencodian-settings-codex-legacy-credential-status-copy {
  margin-bottom: 8px;
  color: var(--text-muted);
  font-size: var(--font-ui-small);
  line-height: 1.4;
}

.opencodian-settings-codex-legacy-credential-status-error {
  margin: 0 0 8px;
  color: var(--text-error);
  font-size: var(--font-ui-small);
  line-height: 1.4;
}

.opencodian-settings-codex-legacy-credential-status .setting-item-control button:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

@media (max-width: 480px) {
  .opencodian-codex-provider-configuration-status {
    grid-template-columns: 1fr;
  }

  .opencodian-codex-provider-configuration-status-state {
    justify-self: start;
    white-space: normal;
  }
}

/* Readback outputs and info notices rendered inside Codex groups.
   They share the card base above and use the card body gap for
   internal blocks. */
.opencodian-settings-codex-readback {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-body-gap);
}

.opencodian-settings-codex-readback p {
  margin: 0;
}

.opencodian-settings-codex-readback pre {
  margin: 0;
  padding: 8px 10px;
  border-radius: 6px;
  background: var(--background-primary);
  border: 1px solid var(--background-modifier-border);
  font-family: var(--font-monospace);
  font-size: var(--font-smallest);
  overflow-x: auto;
}

/* ── Global Codex configuration summary card ─────────────────── */

.opencodian-codex-global-config-summary-card {
  /* card base shared via .opencodian-codex-account-card */
}

.opencodian-codex-global-config-summary-readonly-note {
  margin: 0 0 6px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.opencodian-codex-global-config-summary-state {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.opencodian-codex-global-config-summary-path {
  margin: 0;
  font-size: var(--font-smallest);
  color: var(--text-muted);
  word-break: break-all;
}

.opencodian-codex-global-config-summary-path-value {
  font-family: var(--font-monospace);
}

.opencodian-codex-global-config-summary-last-read {
  margin: 0;
  font-size: var(--font-smallest);
  color: var(--text-muted);
}

.opencodian-codex-global-config-summary-top-level {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.opencodian-codex-global-config-summary-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.opencodian-codex-global-config-summary-row-label {
  flex-shrink: 0;
  min-width: 120px;
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
}

.opencodian-codex-global-config-summary-row-value {
  min-width: 0;
  word-break: break-all;
  font-size: var(--font-ui-small);
}

/* Provider table — grid columns at desktop, stacked at narrow */
.opencodian-codex-global-config-summary-providers {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-title-body-gap);
  margin-top: 4px;
}

.opencodian-settings .opencodian-codex-global-config-summary-providers-title {
  margin: 0;
  padding: 0;
  padding-inline-start: 0;
  font-size: var(--font-ui-smaller);
  font-weight: 600;
  color: var(--text-muted);
}

.opencodian-settings .opencodian-codex-project-config-advanced-title {
  margin: 0;
  padding: 0;
  padding-inline-start: 0;
  min-width: 0;
  overflow-wrap: anywhere;
}

.opencodian-settings .opencodian-codex-project-config-advanced {
  display: flex;
  flex-direction: column;
  gap: var(--oc-codex-card-title-body-gap);
}

.opencodian-settings .opencodian-codex-project-config-advanced-desc {
  margin: 0;
}

.opencodian-codex-global-config-summary-provider-row {
  display: grid;
  grid-template-columns: minmax(80px, 1fr) minmax(80px, 1fr) minmax(120px, 2fr) minmax(60px, 0.75fr) auto;
  gap: 6px 10px;
  align-items: baseline;
  padding: 4px 0;
  border-bottom: 1px solid var(--background-modifier-border);
  font-size: var(--font-smallest);
}

