  font-size: 12px;
  line-height: 1.5;
  resize: vertical;
}

.opencodian-claude-resource-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-claude-resource-preview-pane {
  box-sizing: border-box;
  width: 100%;
  min-height: 320px;
  padding: 10px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 6px;
  background: var(--background-primary);
  color: var(--text-normal);
  overflow-wrap: anywhere;
}

.opencodian-resource-conflict {
  margin-top: 10px;
  padding: 8px 10px;
  border: 1px solid var(--text-warning, #e8a33d);
  border-radius: 6px;
  color: var(--text-warning, #b87700);
  font-size: var(--font-ui-smaller);
}

.opencodian-resource-read-error {
  margin-top: 10px;
  padding: 8px 10px;
  border: 1px solid var(--text-warning, #e8a33d);
  border-radius: 6px;
  color: var(--text-warning, #b87700);
  font-size: var(--font-ui-smaller);
}

.opencodian-resource-history-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.opencodian-resource-history-error {
  padding: 8px 10px;
  border: 1px solid var(--text-warning, #e8a33d);
  border-radius: 6px;
  color: var(--text-warning, #b87700);
  font-size: var(--font-ui-smaller);
}

.opencodian-resource-history-target {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
}

.opencodian-resource-history-target-path {
  font-family: var(--font-monospace);
  font-size: 11px;
  overflow-wrap: anywhere;
}

.opencodian-resource-history-entry {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: var(--font-ui-smaller);
}

.opencodian-resource-history-restore {
  flex-shrink: 0;
}

/* Global-but-disabled scope (user setting source off): warning tonal. */
.opencodian-claude-resource-scope.is-global-disabled {
  background: color-mix(in srgb, var(--text-warning, #e8a33d) 14%, transparent);
  color: var(--text-normal);
}

/* User-source notice: quiet full-border alert, no side-stripe. */
.opencodian-claude-resource-source-notice {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 12px;
  border: 1px solid var(--text-warning, #e8a33d);
  border-radius: 8px;
  background: color-mix(in srgb, var(--text-warning, #e8a33d) 10%, transparent);
  font-size: var(--font-ui-small);
  line-height: 1.45;
}

.opencodian-claude-resource-source-notice-title {
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-claude-resource-source-notice-desc {
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
}


/* components/settings-claude-providers.css */
/* Project-scoped Claude provider configuration. */
.opencodian-claude-provider-gate,
.opencodian-claude-provider-card,
.opencodian-claude-provider-config-layer {
  border: 1px solid var(--opencodian-settings-form-row-border, var(--background-modifier-border));
  border-radius: var(--opencodian-settings-form-row-radius, 10px);
  background: var(--opencodian-settings-form-row-bg, var(--background-primary));
}

.opencodian-claude-provider-gate {
  padding: 12px 14px;
  color: var(--text-normal);
  background: color-mix(in srgb, var(--background-primary) 88%, var(--color-yellow) 12%);
}

.opencodian-claude-provider-gate p,
.opencodian-claude-provider-card p {
  margin: 6px 0 0;
}

.opencodian-claude-provider-list {
  display: grid;
  gap: 10px;
  margin: 12px 0;
}

.opencodian-claude-provider-card {
  padding: 12px 14px;
}

.opencodian-claude-provider-card-heading,
.opencodian-claude-provider-card-actions,
.opencodian-claude-provider-modal-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.opencodian-claude-provider-card-heading {
  justify-content: space-between;
}

.opencodian-claude-provider-card-actions {
  margin-top: 10px;
  flex-wrap: wrap;
}

.opencodian-claude-provider-active-badge {
  padding: 2px 6px;
  border-radius: var(--radius-s, 4px);
  color: var(--text-accent);
  background: color-mix(in srgb, var(--interactive-accent) 14%, transparent);
  font-size: var(--font-ui-smaller);
}

.opencodian-claude-provider-warning {
  color: var(--text-error);
}

.opencodian-claude-provider-info,
.opencodian-claude-provider-global-summary,
.opencodian-claude-provider-config-path,
.opencodian-claude-provider-local-status {
  color: var(--text-muted);
}

.opencodian-claude-provider-local-status,
.opencodian-claude-provider-conflict,
.opencodian-claude-provider-partial-persistence {
  margin: 10px 0;
  padding: 10px 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s, 4px);
  overflow-wrap: anywhere;
  min-width: 0;
}

.opencodian-claude-provider-conflict {
  color: var(--text-normal);
  border-color: color-mix(in srgb, var(--text-error) 45%, var(--background-modifier-border));
  background: color-mix(in srgb, var(--background-primary) 90%, var(--text-error) 10%);
}

.opencodian-claude-provider-partial-persistence {
  color: var(--text-normal);
  border-color: color-mix(in srgb, var(--color-orange) 55%, var(--background-modifier-border));
  background: color-mix(in srgb, var(--background-primary) 92%, var(--color-orange) 8%);
}

.opencodian-claude-provider-partial-persistence p {
  margin: 6px 0 0;
}

.opencodian-claude-provider-global-summary {
  display: grid;
  gap: 3px;
  margin-top: 10px;
}

.opencodian-claude-provider-config-modal .opencodian-claude-provider-config-layer {
  margin: 12px 0;
  padding: 12px;
}

.opencodian-claude-provider-config-modal pre {
  max-height: min(38vh, 320px);
  overflow: auto;
  margin: 8px 0 0;
  padding: 8px;
  border-radius: var(--radius-s, 4px);
  background: var(--background-secondary);
  font-size: 11px;
}

.opencodian-claude-provider-modal-actions {
  justify-content: flex-end;
  margin-top: 16px;
}

@media (max-width: 720px) {
  .opencodian-claude-provider-card-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  /* The providers tab can be narrower than the viewport when the Settings
     modal keeps its navigation rail visible. Reset the native setting-item
     minimums and make every provider surface shrink with that actual block. */
  .opencodian-settings [data-claude-code-section='providers'],
  .opencodian-settings [data-claude-code-section='providers'] > .opencodian-settings-block-body {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    max-width: 100%;
  }

  .opencodian-settings [data-claude-code-section='providers'] > .opencodian-settings-block-body > * {
    box-sizing: border-box;
    min-width: 0;
    max-width: 100%;
  }

  .opencodian-settings [data-claude-code-section='providers'].opencodian-settings-block.opencodian-settings-section {
    flex: 0 0 auto;
    height: auto;
    max-height: none;
    overflow-x: clip;
    overflow-y: visible;
  }

  .opencodian-settings [data-claude-code-section='providers'] .opencodian-settings-section-heading {
    box-sizing: border-box;
    min-width: 0;
    max-width: 100%;
    overflow-wrap: anywhere;
    white-space: normal;
  }

  .opencodian-settings [data-claude-code-section='providers'] .setting-item {
    box-sizing: border-box;
    grid-template-columns: minmax(0, 1fr);
    min-width: 0;
    max-width: 100%;
  }

  .opencodian-settings [data-claude-code-section='providers'] .setting-item-info,
  .opencodian-settings [data-claude-code-section='providers'] .setting-item-control {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    max-width: 100%;
  }

  .opencodian-settings [data-claude-code-section='providers'] .setting-item-name,
  .opencodian-settings [data-claude-code-section='providers'] .setting-item-description {
    min-width: 0;
    max-width: 100%;
    overflow-wrap: anywhere;
  }

  .opencodian-settings [data-claude-code-section='providers'] .setting-item-control {
    justify-content: flex-start;
  }

  .opencodian-settings [data-claude-code-section='providers'] .setting-item-control button,
  .opencodian-settings [data-claude-code-section='providers'] .opencodian-claude-provider-card-actions button {
    box-sizing: border-box;
    max-width: 100%;
    white-space: normal;
    overflow-wrap: anywhere;
  }

  .opencodian-settings [data-claude-code-section='providers'] .opencodian-claude-provider-list,
  .opencodian-settings [data-claude-code-section='providers'] .opencodian-claude-provider-list > .opencodian-claude-provider-card {
    box-sizing: border-box;
    min-width: 0;
    max-width: 100%;
  }

  .opencodian-settings [data-claude-code-section='providers'] .opencodian-claude-provider-card-heading > * {
    min-width: 0;
    max-width: 100%;
    overflow-wrap: anywhere;
    white-space: normal;
  }

  .opencodian-settings [data-claude-code-section='providers'] .opencodian-claude-provider-global-summary > *,
  .opencodian-settings [data-claude-code-section='providers'] .opencodian-claude-provider-card code {
    box-sizing: border-box;
    min-width: 0;
    max-width: 100%;
    overflow-wrap: anywhere;
    white-space: normal;
  }
}

@media (max-width: 480px) {
  .opencodian-claude-provider-partial-persistence {
    padding: 8px 10px;
  }

  .opencodian-claude-provider-partial-persistence button {
    max-width: 100%;
    white-space: normal;
  }
}


/* components/settings-model-pricing.css */
.opencodian-model-pricing-modal .modal-content {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.opencodian-model-pricing-intro,
.opencodian-model-pricing-section-desc,
.opencodian-model-pricing-source-hint,
.opencodian-model-pricing-empty {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-ui-small);
  line-height: 1.45;
}

.opencodian-model-pricing-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-primary);
}

.opencodian-model-pricing-section-header,
.opencodian-model-pricing-override-row,
.opencodian-model-pricing-form-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.opencodian-model-pricing-section h3 {
  margin: 0;
  font-size: var(--font-ui-medium);
}

.opencodian-model-pricing-status {
  display: grid;
  gap: 3px;
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.opencodian-model-pricing-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.opencodian-model-pricing-field {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.opencodian-model-pricing-field label {
  color: var(--text-muted);
  font-size: var(--font-smallest);
}

.opencodian-model-pricing-field input {
  width: 100%;
  min-width: 0;
}

.opencodian-model-pricing-override-list {
  display: grid;
  gap: 8px;
}

.opencodian-model-pricing-override-row {
  align-items: flex-start;
  padding-top: 8px;
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-model-pricing-override-row:first-child {
  padding-top: 0;
  border-top: 0;
}

.opencodian-model-pricing-override-identity {
  min-width: 0;
}

.opencodian-model-pricing-override-model {
  color: var(--text-normal);
  font-family: var(--font-monospace);
  font-size: var(--font-ui-small);
  overflow-wrap: anywhere;
}

.opencodian-model-pricing-override-rates {
  margin-top: 3px;
  color: var(--text-muted);
  font-size: var(--font-smallest);
  line-height: 1.45;
}

.opencodian-model-pricing-override-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 4px;
}

@media (max-width: 520px) {
  .opencodian-model-pricing-form {
    grid-template-columns: 1fr;
  }

  .opencodian-model-pricing-override-row {
    align-items: stretch;
    flex-direction: column;
  }
}


/* components/settings-plugin-update.css */
.opencodian-plugin-update-section {
  display: grid;
  gap: 0;
  margin-top: 0;
  padding: 0;
  border: 1px solid var(--opencodian-settings-section-border);
  border-radius: var(--opencodian-settings-form-row-radius);
  background: var(--background-primary);
  overflow: hidden;
}

.opencodian-settings[data-settings-layout-mode='classic']
  > .opencodian-settings-general-merged-block
  + .opencodian-plugin-update-section {
  margin-top: var(--opencodian-settings-space-lg);
}

.opencodian-plugin-update-heading {
  display: grid;
  gap: var(--opencodian-settings-space-md);
}

.opencodian-plugin-update-section > .opencodian-settings-subsection-heading {
  margin: 0;
}

.opencodian-plugin-update-heading-button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  width: 100%;
  /* Obsidian's global button height is compact; this disclosure needs to grow
     when the narrow layout puts version metadata on its second grid row. */
  height: auto;
  min-width: 0;
  gap: var(--opencodian-settings-space-md);
  padding: var(--opencodian-settings-space-xl);
  border: 0;
  background: var(--background-primary);
  color: var(--text-normal);
  font: inherit;
  text-align: start;
  cursor: pointer;
}

.opencodian-plugin-update-heading-button:hover {
  background: var(--opencodian-settings-form-row-hover-bg);
  color: var(--text-accent);
}

/* Obsidian's button:not(.clickable-icon) rule sets background-color with
   greater specificity; keep the resting disclosure on the card's base. */
.opencodian-plugin-update-section > .opencodian-settings-subsection-heading > .opencodian-plugin-update-heading-button {
  background-color: var(--background-primary);
}

.opencodian-plugin-update-heading-button:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 3px;
  border-radius: var(--opencodian-settings-form-row-radius);
}

.opencodian-plugin-update-heading-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.opencodian-plugin-update-heading-title {
  min-width: 0;
}

.opencodian-plugin-update-heading-meta {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: var(--opencodian-settings-space-md) var(--opencodian-settings-space-lg);
  min-width: 0;
}

.opencodian-plugin-update-content {
  display: grid;
  grid-template-rows: 1fr;
  overflow: hidden;
  opacity: 1;
  transition: grid-template-rows 150ms ease-out, opacity 150ms ease-out;
}

.opencodian-plugin-update-content[aria-hidden='true'] {
  grid-template-rows: 0fr;
  opacity: 0;
  pointer-events: none;
}

.opencodian-plugin-update-content-inner {
  display: grid;
  min-height: 0;
  gap: var(--opencodian-settings-space-xl);
  overflow: hidden;
  padding: var(--opencodian-settings-space-xl);
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-plugin-update-content[aria-hidden='true'] .opencodian-plugin-update-content-inner {
  padding-block: 0;
  border-top-color: transparent;
}

.opencodian-plugin-update-description,
.opencodian-plugin-update-list-description,
.opencodian-plugin-update-version-meta,
.opencodian-plugin-update-empty {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.opencodian-plugin-update-panel {
  display: grid;
  gap: var(--opencodian-settings-space-md);
}

.opencodian-plugin-update-panel-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--opencodian-settings-space-md) var(--opencodian-settings-space-lg);
  min-width: 0;
}

.opencodian-plugin-update-version-block {
  display: grid;
  gap: var(--opencodian-settings-space-xs);
  min-width: 0;
}

.opencodian-plugin-update-version-label {
  color: var(--text-muted);
  font-size: var(--font-smallest);
  line-height: 1.4;
}

.opencodian-plugin-update-version-value {
  color: var(--text-normal);
  font-family: var(--font-monospace);
  font-size: var(--font-ui-medium);
  font-weight: 600;
  line-height: 1.3;
}

/* Status badge: quiet pill whose dot carries the state color. */

.opencodian-plugin-update-status-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--opencodian-settings-space-sm);
  flex-shrink: 0;
  padding: var(--opencodian-settings-space-xs) var(--opencodian-settings-space-md);
  border: 1px solid var(--background-modifier-border);
  border-radius: 999px;
  background: var(--background-primary);
  color: var(--text-muted);
  font-size: var(--font-smallest);
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
}

.opencodian-plugin-update-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-faint);
}

.opencodian-plugin-update-status-badge[data-plugin-update-badge='checking'] .opencodian-plugin-update-status-dot {
  background: var(--interactive-accent);
  animation: opencodian-plugin-update-pulse 1.2s ease-in-out infinite;
}

.opencodian-plugin-update-status-badge[data-plugin-update-badge='update'] {
  border-color: rgba(var(--color-blue-rgb, 2, 132, 199), 0.45);
  background: rgba(var(--color-blue-rgb, 2, 132, 199), 0.12);
  color: var(--color-blue, #0284c7);
}

.opencodian-plugin-update-status-badge[data-plugin-update-badge='update'] .opencodian-plugin-update-status-dot {
  background: var(--color-blue, #0284c7);
}

.opencodian-plugin-update-status-badge[data-plugin-update-badge='current'] {
  border-color: rgba(var(--color-green-rgb, 76, 175, 80), 0.4);
  background: rgba(var(--color-green-rgb, 76, 175, 80), 0.12);
  color: var(--color-green, #4caf50);
}

.opencodian-plugin-update-status-badge[data-plugin-update-badge='current'] .opencodian-plugin-update-status-dot {
  background: var(--color-green, #4caf50);
}

.opencodian-plugin-update-status-badge[data-plugin-update-badge='error'] {
  border-color: rgba(var(--color-red-rgb, 224, 49, 49), 0.4);
  background: rgba(var(--color-red-rgb, 224, 49, 49), 0.1);
  color: var(--text-error);
}

.opencodian-plugin-update-status-badge[data-plugin-update-badge='error'] .opencodian-plugin-update-status-dot {
  background: var(--text-error);
}

@keyframes opencodian-plugin-update-pulse {
  0%,
  100% {
    opacity: 0.35;
  }

  50% {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-plugin-update-content,
  .opencodian-plugin-update-status-badge[data-plugin-update-badge='checking'] .opencodian-plugin-update-status-dot {
    animation: none;
    transition: none;
  }
}

/* Status detail: one muted line for idle/checking/ready; a tinted notice with
   a mono raw-error readout for failures. */

.opencodian-plugin-update-status-detail {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--font-ui-small);
  line-height: 1.45;
}

.opencodian-plugin-update-status-detail.is-error {
  display: grid;
  gap: var(--opencodian-settings-space-xs);
  padding: var(--opencodian-settings-space-md);
  border: 1px solid rgba(var(--color-red-rgb, 224, 49, 49), 0.35);
  border-radius: 6px;
  background: rgba(var(--color-red-rgb, 224, 49, 49), 0.08);
}

.opencodian-plugin-update-error-label {
  color: var(--text-error);
  font-size: var(--font-ui-small);
  font-weight: 600;
  line-height: 1.4;
}

.opencodian-plugin-update-error-raw {
  color: var(--text-muted);
  font-family: var(--font-monospace);
  font-size: var(--font-smallest);
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.opencodian-plugin-update-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--opencodian-settings-space-md);
  padding-top: var(--opencodian-settings-space-lg);
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-plugin-update-button {
  white-space: normal;
  height: auto;
  min-height: var(--input-height);
  overflow-wrap: anywhere;
}

.opencodian-plugin-update-progress {
  display: grid;
  gap: var(--opencodian-settings-space-sm);
  color: var(--text-normal);
  font-size: var(--font-ui-small);
  overflow-wrap: anywhere;
}

.opencodian-plugin-update-progress[hidden],
.opencodian-plugin-update-progress-bar[hidden],
.opencodian-plugin-update-history-controls button[hidden] {
  display: none;
}

.opencodian-plugin-update-progress[data-phase='failed'] {
  color: var(--text-error);
}

.opencodian-plugin-update-progress-bar {
  appearance: none;
  width: 100%;
  height: 6px;
  border: 0;
  border-radius: 3px;
  overflow: hidden;
  background: var(--background-modifier-border);
}

.opencodian-plugin-update-progress-bar::-webkit-progress-bar {
  background: var(--background-modifier-border);
  border-radius: 3px;
}

.opencodian-plugin-update-progress-bar:indeterminate {
  background-image: linear-gradient(var(--interactive-accent), var(--interactive-accent));
  background-size: 35% 100%;
  background-repeat: no-repeat;
  animation: opencodian-update-progress 1.4s ease-in-out infinite alternate;
}

.opencodian-plugin-update-progress-bar:indeterminate::-webkit-progress-bar {
  background: transparent;
}

@keyframes opencodian-update-progress {
  from { background-position: 0% 0; }
  to { background-position: 100% 0; }
}

.opencodian-plugin-update-history-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--opencodian-settings-space-md);
  padding-block-start: var(--opencodian-settings-space-sm);
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.opencodian-plugin-update-history-controls > span {
  margin-inline-end: auto;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-plugin-update-progress-bar:indeterminate {
    animation: none;
    background-position: 50% 0;
  }
}

.opencodian-plugin-update-button:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
}

.opencodian-plugin-update-downgrade-note {
  flex-basis: 100%;
  color: var(--text-warning);
  font-size: var(--font-ui-small);
  line-height: 1.4;
}

/* Release history / local backups */

.opencodian-plugin-update-list-group {
  display: grid;
  gap: var(--opencodian-settings-space-sm);
}

.opencodian-plugin-update-list-group h5 {
  margin: 0;
  color: var(--text-normal);
  font-size: var(--font-ui-small);
  font-weight: 600;
}

.opencodian-plugin-update-list {
  display: grid;
  background: transparent;
}

.opencodian-plugin-update-version-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--opencodian-settings-space-lg);
  min-height: 44px;
  padding: var(--opencodian-settings-space-md) var(--opencodian-settings-space-lg);
  border-bottom: 1px solid var(--background-modifier-border);
  transition: background-color 150ms ease-out;
}

.opencodian-plugin-update-version-row:hover {
  background: var(--background-modifier-hover);
}

.opencodian-plugin-update-version-row:last-child {
  border-bottom: 0;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-plugin-update-version-row {
    transition: none;
  }
}

.opencodian-plugin-update-version-identity {
  display: grid;
  min-width: 0;
  gap: var(--opencodian-settings-space-xs);
}

.opencodian-plugin-update-version {
  color: var(--text-normal);
  font-family: var(--font-monospace);
  font-size: var(--font-ui-small);
}

.opencodian-plugin-update-current-badge {
  width: fit-content;
  padding: var(--opencodian-settings-space-xs) var(--opencodian-settings-space-md);
  border: 1px solid var(--background-modifier-border);
  border-radius: 999px;
  background: var(--background-primary);
  color: var(--text-muted);
  font-size: var(--font-smallest);
  font-weight: 600;
  line-height: 1.4;
}

.opencodian-plugin-update-version-error {
  color: var(--text-error);
  font-size: var(--font-ui-smaller);
}

@media (max-width: 480px) {
  .opencodian-plugin-update-version-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .opencodian-plugin-update-version-row .opencodian-plugin-update-button {
    width: 100%;
  }
}

@media (max-width: 720px) {
  .opencodian-plugin-update-heading-button {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .opencodian-plugin-update-heading-meta {
    grid-column: 2;
    justify-content: flex-start;
  }
}


/* features/chat-user.css */
/* ============================================================
   User Message - Push-Up Sticky Header
   ============================================================ */

/* ============================================================
   User Message - Bubble Styles
   ============================================================ */

/*
 * Two rendering modes, chosen via data-opencodian-user-bubble-style on
 * .opencodian-container:
 * - solid (default, also when the attribute is absent): opaque background
 *   derived from the theme surface color, no backdrop-filter.
 * - glass: legacy glassmorphism bubble with blur backdrop and gradients.
 */
.opencodian-message--user {
  /* Right alignment for bubble style */
  align-self: flex-end;
  display: flex;
  flex-direction: column;
  align-items: flex-end;

  /* Base styles */
  padding: 4px var(--opencodian-message-pad-x) 4px;
  max-width: 95%;
  animation: messageSlideIn 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 0;
}

/* User message content bubble - Solid style (default) */
.opencodian-message--user .opencodian-message-content {
  display: inline-block;
  background: var(--opencodian-user-bubble-bg);
  border: 1px solid var(--opencodian-user-bubble-border);
  border-radius: var(--opencodian-user-radius);
  border-end-end-radius: var(--opencodian-user-tail-radius);
  padding: var(--opencodian-content-pad-y) var(--opencodian-content-pad-x) calc(var(--opencodian-content-pad-y) + 1px);
  box-shadow: 0 10px var(--opencodian-user-shadow-blur) var(--opencodian-glass-shadow);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
  transform-origin: right bottom;
  width: fit-content;
  max-width: 100%;
  align-self: flex-end;
}

/* Solid hover: slightly lifted surface, no glass effects */
.opencodian-message--user:hover .opencodian-message-content {
  transform: translateY(-1px);
  background: var(--opencodian-user-bubble-bg-hover);
  border-color: var(--opencodian-user-bubble-border-hover);
  box-shadow: 0 14px calc(var(--opencodian-user-shadow-blur) + 6px) var(--opencodian-glass-shadow-strong);
}

/* Glass style: layered gradients + backdrop blur over the chat surface */
.opencodian-container[data-opencodian-user-bubble-style="glass"] .opencodian-message--user .opencodian-message-content {
  background: linear-gradient(
    180deg,
    var(--opencodian-glass-specular) 0%,
    color-mix(in srgb, var(--opencodian-glass-specular-soft) 88%, transparent) 38%,
    transparent 100%
  ),
  linear-gradient(
    135deg,
    color-mix(in srgb, var(--opencodian-glass-base-strong) 96%, transparent) 0%,
    color-mix(in srgb, var(--opencodian-glass-base) 84%, transparent) 100%
  ),
  radial-gradient(
    circle at top left,
    var(--opencodian-glass-highlight) 0%,
    transparent 58%
  );
  backdrop-filter: blur(var(--opencodian-user-blur));
  -webkit-backdrop-filter: blur(var(--opencodian-user-blur));
  border-color: var(--opencodian-glass-border);
  box-shadow:
    0 10px var(--opencodian-user-shadow-blur) var(--opencodian-glass-shadow),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 90%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border) 52%, transparent) inset;
}

.opencodian-message--user .opencodian-message-content.opencodian-collapsible {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
}

.opencodian-collapsible-content {
  position: relative;
}

.opencodian-collapsible.is-collapsible.is-collapsed .opencodian-collapsible-content {
  max-height: var(--opencodian-collapsible-max-height, 168px);
  overflow: hidden;
  -webkit-mask-image: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 1) 0%,
    rgba(0, 0, 0, 1) calc(100% - 36px),
    rgba(0, 0, 0, 0) 100%
  );
  mask-image: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 1) 0%,
    rgba(0, 0, 0, 1) calc(100% - 36px),
    rgba(0, 0, 0, 0) 100%
  );
}

.opencodian-collapsible-toggle {
  display: none;
  align-self: flex-start;
  padding: 4px 10px;
  border: 1px solid color-mix(in srgb, var(--interactive-accent) 22%, var(--background-modifier-border));
  border-radius: 999px;
  background: color-mix(in srgb, var(--interactive-accent) 10%, var(--background-primary));
  color: var(--interactive-accent);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.4;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.15s ease, color 0.15s ease;
}

.opencodian-collapsible.is-collapsible .opencodian-collapsible-toggle {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
}

.opencodian-collapsible-toggle:hover {
  background: color-mix(in srgb, var(--interactive-accent) 16%, var(--background-modifier-hover));
  border-color: color-mix(in srgb, var(--interactive-accent) 44%, var(--background-modifier-border-hover));
  color: var(--text-accent-hover);
  transform: translateY(-1px);
}

.opencodian-collapsible-toggle:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 2px;
  border-radius: 999px;
}

/* Shimmer effect overlay (glass style only) */
.opencodian-container[data-opencodian-user-bubble-style="glass"] .opencodian-message--user .opencodian-message-content::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--opencodian-glass-specular) 88%, transparent),
    transparent
  );
  transition: left 0.5s ease;
}

.opencodian-container[data-opencodian-user-bubble-style="glass"] .opencodian-message--user:hover .opencodian-message-content::before {
  left: 100%;
}

/* Hover lift effect (glass style) */
.opencodian-container[data-opencodian-user-bubble-style="glass"] .opencodian-message--user:hover .opencodian-message-content {
  transform: translateY(-1px);
  box-shadow:
    0 14px calc(var(--opencodian-user-shadow-blur) + 6px) var(--opencodian-glass-shadow-strong),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 96%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border-hover) 64%, transparent) inset;
  border-color: var(--opencodian-glass-border-strong);
}

/* Message slide-in animation */
@keyframes messageSlideIn {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Stagger animation for multiple messages */
.opencodian-message--user:nth-child(1) { animation-delay: 0ms; }
.opencodian-message--user:nth-child(2) { animation-delay: 50ms; }
.opencodian-message--user:nth-child(3) { animation-delay: 100ms; }
.opencodian-message--user:nth-child(4) { animation-delay: 150ms; }
.opencodian-message--user:nth-child(5) { animation-delay: 200ms; }

/* Reduced motion: messages appear without the slide-in entrance */
@media (prefers-reduced-motion: reduce) {
  .opencodian-message--user {
    animation: none;
  }
}

/* Text selection in user messages */
.opencodian-message--user ::selection {
  background: color-mix(in srgb, var(--interactive-accent) 24%, transparent);
  color: inherit;
}

.cm-line .opencodian-selection-highlight,
.opencodian-selection-highlight {
  background: var(--text-selection) !important;
  border-radius: 2px;
  padding: 2px 0;
  margin: -2px 0;
}

::highlight(opencodian-selection) {
  background: var(--text-selection);
}

/* ============================================================
   Compaction Divider - Lightweight horizontal separator
   ============================================================ */

.opencodian-message--compaction-divider {
  align-self: stretch;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px var(--opencodian-message-pad-x) 4px;
  max-width: 100%;
  animation: none;
}

.opencodian-compaction-divider-line {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  color: var(--text-faint);
  font-size: 11px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.opencodian-compaction-divider-line::before,
.opencodian-compaction-divider-line::after {
  content: '';
  flex: 1;
  height: 1px;
  background: color-mix(in srgb, var(--background-modifier-border) 60%, transparent);
}

.opencodian-compaction-divider-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--background-modifier-border) 30%, transparent);
  white-space: nowrap;
}

.opencodian-compaction-divider-badge.is-overflow {
  color: var(--text-muted);
  font-style: italic;
  text-transform: none;
  letter-spacing: 0;
}

.opencodian-message--compaction-divider .opencodian-message-content {
  display: none;
}

.opencodian-message--compaction-divider .opencodian-user-message-footer {
  display: none;
}



/* features/chat-assistant.css */
/* ============================================================
   Assistant Message - Normal Flow (Not Sticky)
   ============================================================ */

/* 
 * Assistant messages flow normally under user section headers
 * They slide under sticky user messages as you scroll
 */
.opencodian-message--assistant {
  position: relative;
  background: transparent;
  align-self: stretch;
  width: 100%;
  max-width: 100%;
  border-radius: 12px;
  border-end-start-radius: 4px;
  text-align: start;
  padding: var(--opencodian-assistant-pad-y) var(--opencodian-assistant-pad-x);
  animation: messageSlideIn 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 1; /* Below sticky user messages (z-index: 100) */
}

.opencodian-message--assistant.is-streaming {
  animation: none;
  overflow-anchor: none;
}

/* Assistant message hover effect */
.opencodian-message--assistant:hover {
  background: transparent;
}

.opencodian-message--assistant .opencodian-message-content {
  position: relative;
  padding: var(--opencodian-assistant-content-pad-y) var(--opencodian-assistant-content-pad-x);
  border-radius: var(--opencodian-assistant-radius);
  transition:
    background 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease,
    transform 0.25s ease,
    backdrop-filter 0.25s ease;
}

.opencodian-message--assistant.is-streaming .opencodian-message-content {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .opencodian-message--assistant,
  .opencodian-message--assistant .opencodian-message-content {
    animation: none;
    transition: none;
  }

  .opencodian-message--assistant:hover .opencodian-message-content {
    transform: none;
  }
}

.opencodian-container--theme-background .opencodian-message--assistant .opencodian-message-content {
  background: color-mix(in srgb, var(--opencodian-glass-base-soft) calc(var(--opencodian-assistant-bg-opacity) - 14%), transparent);
  border-color: color-mix(in srgb, var(--background-modifier-border) 44%, transparent);
  box-shadow:
    0 8px calc(var(--opencodian-assistant-shadow-blur) * 0.72) color-mix(in srgb, var(--opencodian-glass-shadow) 54%, transparent),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular-soft) 56%, transparent) inset;
  backdrop-filter: blur(var(--opencodian-assistant-blur)) saturate(1.04);
  -webkit-backdrop-filter: blur(var(--opencodian-assistant-blur)) saturate(1.04);
}

.opencodian-message--assistant:hover .opencodian-message-content {
  background: color-mix(in srgb, var(--opencodian-glass-base-soft) var(--opencodian-assistant-bg-opacity), transparent);
  border-color: color-mix(in srgb, var(--background-modifier-border) 62%, transparent);
  box-shadow:
    0 10px var(--opencodian-assistant-shadow-blur) color-mix(in srgb, var(--opencodian-glass-shadow) 72%, transparent),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular-soft) 68%, transparent) inset;
  backdrop-filter: blur(var(--opencodian-assistant-blur)) saturate(1.04);
  -webkit-backdrop-filter: blur(var(--opencodian-assistant-blur)) saturate(1.04);
  transform: translateY(-1px);
}

.opencodian-message--notice:hover {
  background: transparent;
}

.opencodian-message-content {
  font-size: var(--opencodian-chat-font-size);
  line-height: 1.5;
  user-select: text;
  -webkit-user-select: text;
  unicode-bidi: plaintext;
  border: 1px solid transparent;
}

.opencodian-message-text {
  word-wrap: break-word;
}

.opencodian-message--user .opencodian-message-text {
  color: var(--text-normal);
  font-weight: 500;
  font-size: calc(var(--opencodian-chat-font-size) + 2px);
}

.opencodian-message--user .opencodian-message-highlight-agent {
  color: var(--text-warning);
  font-weight: 700;
  border-radius: 4px;
  padding: 0 2px;
  background: color-mix(in srgb, var(--text-warning) 12%, transparent);
}

.opencodian-message--user .opencodian-message-highlight-command {
  color: var(--color-blue, oklch(62% 0.14 255));
  font-weight: 700;
  border-radius: 4px;
  padding: 0 2px;
  background: color-mix(in srgb, var(--color-blue, oklch(62% 0.14 255)) 16%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--color-blue, oklch(62% 0.14 255)) 22%, transparent);
}

.opencodian-message--user .opencodian-message-highlight-skill {
  color: var(--text-success, var(--color-green));
  font-weight: 700;
  border-radius: 4px;
  padding: 0 2px;
  background: color-mix(in srgb, var(--text-success, var(--color-green)) 14%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--text-success, var(--color-green)) 24%, transparent);
}

.opencodian-message--user .opencodian-message-text > p {
  margin: 4px 0;
}

.opencodian-user-message-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.opencodian-user-message-controls:not(:has(> .opencodian-collapsible-toggle:not([hidden]), > .opencodian-user-context-list)) {
  display: none;
}

.opencodian-user-message-controls > .opencodian-collapsible-toggle {
  align-self: center;
}

.opencodian-user-message-controls > .opencodian-collapsible-toggle[hidden] {
  display: none;
}

.opencodian-user-context-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 0;
}

.opencodian-user-message-controls > .opencodian-user-context-list {
  display: contents;
}

.opencodian-user-context-chip {
  min-height: 24px;
  max-width: min(100%, 300px);
  justify-content: flex-start;
  padding-inline: 9px;
  border-radius: 9px;
  border-color: color-mix(in srgb, var(--opencodian-composer-embedded-border-strong) 72%, transparent) !important;
  background: color-mix(in srgb, var(--opencodian-composer-embedded-fill) 18%, transparent);
  color: var(--text-normal);
  font-size: var(--font-ui-smaller);
}

.opencodian-user-context-chip.is-selection {
  border-style: dashed;
  border-color: color-mix(in srgb, var(--text-muted) 56%, var(--opencodian-composer-embedded-border)) !important;
  background: color-mix(in srgb, var(--opencodian-composer-embedded-fill) 12%, transparent);
  color: var(--text-muted);
}

.opencodian-user-context-chip:hover {
  color: var(--text-normal);
}

.opencodian-message--assistant .opencodian-message-text {
  color: var(--text-normal);
}

.opencodian-omo-injection {
  margin-top: 10px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--interactive-accent) 24%, var(--background-modifier-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--interactive-accent) 7%, transparent),
      color-mix(in srgb, var(--background-secondary) 92%, transparent)
    );
}

.opencodian-omo-injection-header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.opencodian-omo-injection-badge {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--interactive-accent) 14%, transparent);
  color: var(--interactive-accent);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  letter-spacing: 0.02em;
}

.opencodian-omo-injection-title {
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  color: var(--text-normal);
}

.opencodian-omo-injection-summary {
  margin-top: 8px;
  font-size: var(--font-ui-smaller);
  line-height: 1.6;
  color: var(--text-muted);
}

.opencodian-omo-raw-block {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.opencodian-omo-raw-block--notice {
  margin-top: 12px;
}

.opencodian-omo-raw-label {
  margin-bottom: 6px;
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  color: var(--text-faint, var(--text-muted));
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.opencodian-omo-raw-content {
  margin: 0;
  padding: 12px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--background-primary) 78%, black 2%);
  border: 1px solid var(--background-modifier-border);
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: var(--font-monospace);
}

.opencodian-chat-notice-card {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 14px;
  border: 1px solid var(--background-modifier-border);
  background: var(--opencodian-surface-mix-soft);
  box-shadow: var(--opencodian-shadow);
}

.opencodian-chat-notice-card.is-warning {
  border-color: var(--opencodian-status-warning-border);
  background: color-mix(in srgb, var(--background-secondary) 90%, var(--opencodian-status-warning-subtle));
}

.opencodian-chat-notice-card.is-error {
  border-color: var(--opencodian-status-error-border);
  background: color-mix(in srgb, var(--background-secondary) 90%, var(--opencodian-status-error-subtle));
}

.opencodian-chat-notice-card.is-info {
  border-color: var(--opencodian-accent-border);
  background: color-mix(in srgb, var(--background-secondary) 90%, var(--opencodian-accent-subtle));
}

.opencodian-chat-notice-card.is-background-task {
  border-color: color-mix(in srgb, var(--interactive-accent) 44%, var(--background-modifier-border));
  background:
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--interactive-accent) 10%, var(--background-secondary)) 0%,
      color-mix(in srgb, var(--background-secondary) 92%, transparent) 100%
    );
}

.opencodian-chat-notice-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--text-muted);
}

.opencodian-chat-notice-card.is-warning .opencodian-chat-notice-icon {
  color: var(--opencodian-status-warning);
}

.opencodian-chat-notice-card.is-error .opencodian-chat-notice-icon {
  color: var(--opencodian-status-error);
}

.opencodian-chat-notice-card.is-info .opencodian-chat-notice-icon {
  color: var(--interactive-accent);
}

.opencodian-chat-notice-icon--background-task svg {
  animation: opencodian-spin 0.9s linear infinite;
}

.opencodian-chat-notice-task-list {
  margin-top: 10px;
  font-size: 13px;
  color: var(--text-muted);
}

.opencodian-chat-notice-task-list ul,
.opencodian-chat-notice-task-list ol {
  margin: 0.45em 0 0;
  padding-left: 1.35em;
}

.opencodian-chat-notice-task-list li {
  margin: 0.3em 0;
}

.opencodian-chat-notice-task-list code {
  white-space: break-spaces;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.opencodian-chat-notice-body {
  min-width: 0;
  flex: 1;
}

.opencodian-chat-notice-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-normal);
}

.opencodian-chat-notice-text {
  margin-top: 4px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-muted);
  white-space: normal;
}

.opencodian-chat-notice-text > :first-child {
  margin-top: 0;
}

.opencodian-chat-notice-text > :last-child {
  margin-bottom: 0;
}

.opencodian-chat-notice-meta {
  margin-top: 8px;
  font-size: var(--font-ui-smaller);
  color: var(--text-faint);
}

.opencodian-chat-notice-text p,
.opencodian-chat-notice-text ul,
.opencodian-chat-notice-text ol,
.opencodian-chat-notice-text pre,
.opencodian-chat-notice-text blockquote {
  margin: 0.4em 0 0;
}

.opencodian-chat-notice-text ul,
.opencodian-chat-notice-text ol {
  padding-left: 1.35em;
}

.opencodian-chat-notice-text li + li {
  margin-top: 0.18em;
}

.opencodian-chat-notice-text code {
  font-size: 0.94em;
}

.opencodian-omo-raw-block .opencodian-collapsible-toggle {
  margin-top: 2px;
  padding-inline: 12px;
  font-size: 13px;
}

.opencodian-chat-notice-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}

.opencodian-chat-notice-action-btn {
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
  color: var(--text-normal);
  font-size: var(--font-ui-smaller);
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.opencodian-chat-notice-action-btn:hover {
  background: var(--background-modifier-hover);
  border-color: var(--interactive-accent);
  transform: translateY(-1px);
}

/* Turn Change Record compact layout: single-line file rows, scoped to the
   dedicated .is-turn-diff card so generic notice icons/flex stay untouched. */
.opencodian-chat-notice-card.is-turn-diff {
  border: none;
  box-shadow: none;
}

.opencodian-chat-notice-card.is-turn-diff .opencodian-chat-notice-body {
  width: 100%;
}

.opencodian-turn-diff-header {
  display: flex;
  align-items: center;
  gap: 8px;
}

.opencodian-turn-diff-count {
  min-width: 20px;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--background-modifier-hover);
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.opencodian-turn-diff-list {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.opencodian-chat-notice-card.is-turn-diff button.opencodian-turn-diff-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 30px;
  padding: 4px 8px;
  border: none;
  border-radius: 8px;
  background: transparent;
  box-shadow: none;
  color: var(--text-normal);
  font-family: inherit;
  font-size: 13px;
  line-height: 1.4;
  text-align: left;
  white-space: nowrap;
  cursor: pointer;
}

.opencodian-chat-notice-card.is-turn-diff button.opencodian-turn-diff-row[hidden] {
  display: none;
}

.opencodian-chat-notice-card.is-turn-diff button.opencodian-turn-diff-row:hover:not(:disabled) {
  background: var(--background-modifier-hover);
  box-shadow: none;
}

.opencodian-chat-notice-card.is-turn-diff button.opencodian-turn-diff-row:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: -2px;
}

.opencodian-chat-notice-card.is-turn-diff button.opencodian-turn-diff-row:disabled {
  cursor: default;
  opacity: 0.7;
}

.opencodian-turn-diff-path {
  display: flex;
  align-items: baseline;
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}

.opencodian-turn-diff-parent {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-faint);
}

.opencodian-turn-diff-filename {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-normal);
  font-weight: 600;
}

.opencodian-turn-diff-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  white-space: nowrap;
}

.opencodian-turn-diff-status {
  padding: 1px 6px;
  border-radius: 6px;
  font-size: var(--font-ui-smaller);
  font-weight: 600;
  line-height: 1.5;
}

.opencodian-turn-diff-status.status-added {
  color: var(--opencodian-status-success);
  background: var(--opencodian-status-success-subtle);
}

.opencodian-turn-diff-status.status-deleted {
  color: var(--opencodian-status-error);
  background: var(--opencodian-status-error-subtle);
}

/* Reserved visual mapping only; SessionDiffEntry.status has no renamed value yet. */
.opencodian-turn-diff-status.status-renamed {
  color: var(--opencodian-status-warning);
  background: var(--opencodian-status-warning-subtle);
}

.opencodian-turn-diff-stat {
  padding: 1px 6px;
  border-radius: 6px;
  font-family: var(--font-monospace);
  font-size: var(--font-ui-smaller);
  font-variant-numeric: tabular-nums;
  line-height: 1.5;
}

.opencodian-turn-diff-stat.is-additions {
  color: var(--opencodian-status-success);
  background: var(--opencodian-status-success-subtle);
}

.opencodian-turn-diff-stat.is-deletions {
  color: var(--opencodian-status-error);
  background: var(--opencodian-status-error-subtle);
}

.opencodian-turn-diff-toggle {
  margin-top: 8px;
  padding: 4px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  font-weight: 600;
  cursor: pointer;
}

.opencodian-turn-diff-toggle:hover {
  background: var(--background-modifier-hover);
  color: var(--text-normal);
}

.opencodian-turn-diff-toggle:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 1px;
}

/* Copy button */
.opencodian-copy-btn-inline {
  border: 1px solid var(--opencodian-glass-border);
  background:
    linear-gradient(
      180deg,
      var(--opencodian-glass-specular) 0%,
      color-mix(in srgb, var(--opencodian-glass-specular-soft) 86%, transparent) 46%,
      transparent 100%
    ),
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--opencodian-glass-base-strong) 96%, transparent),
      color-mix(in srgb, var(--opencodian-glass-base) 82%, transparent)
    ),
    radial-gradient(
      circle at top,
      var(--opencodian-glass-highlight) 0%,
      transparent 62%
    );
  backdrop-filter: blur(20px) saturate(1.2);
  -webkit-backdrop-filter: blur(20px) saturate(1.2);
  box-shadow:
    0 12px 28px var(--opencodian-glass-shadow),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 94%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border) 52%, transparent) inset;
  color: var(--opencodian-text-strong);
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.15s ease,
    color 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    transform 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 30px;
  height: 30px;
  padding: 5px;
  border-radius: 10px;
  flex-shrink: 0;
}

.opencodian-copy-btn-inline svg {
  width: 18px;
  height: 18px;
}

.opencodian-copy-btn-inline:hover {
  color: var(--text-normal);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--opencodian-glass-specular) 100%, transparent) 0%,
      color-mix(in srgb, var(--opencodian-glass-specular-soft) 94%, transparent) 42%,
      transparent 100%
    ),
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--opencodian-glass-base-strong) 98%, transparent),
      color-mix(in srgb, var(--opencodian-glass-base) 84%, transparent)
    ),
    radial-gradient(
      circle at top,
      var(--opencodian-glass-highlight-strong) 0%,
      transparent 60%
    );
  border-color: var(--opencodian-glass-border-strong);
  box-shadow:
    0 16px 34px var(--opencodian-glass-shadow-strong),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 98%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border-hover) 64%, transparent) inset;
  opacity: 1;
  transform: translateY(-1px) scale(1.01);
}

/* Copied state feedback */
.opencodian-message-time {
  font-size: var(--font-ui-smaller);
  color: var(--text-muted);
  margin-top: 4px;
  text-align: right;
  opacity: 0.6;
}

.opencodian-message--assistant .opencodian-message-time {
  text-align: left;
  padding-left: var(--opencodian-assistant-content-pad-x);
}

/* Timestamp row with copy button for assistant messages */
.opencodian-message-time-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 4px;
  padding-left: var(--opencodian-assistant-content-pad-x);
  min-height: calc(max(
    var(--opencodian-assistant-meta-font-size),
    var(--opencodian-assistant-time-font-size),
    var(--opencodian-assistant-model-id-font-size)
  ) * 1.4);
  font-size: var(--opencodian-assistant-meta-font-size);
  line-height: 1.4;
  color: var(--opencodian-assistant-meta-color);
  opacity: 0.6;
}

.opencodian-message-time-row.is-pending {
  visibility: hidden;
  pointer-events: none;
  min-height: calc((
    max(
      var(--opencodian-assistant-meta-font-size),
      var(--opencodian-assistant-time-font-size),
      var(--opencodian-assistant-model-id-font-size)
    ) * 1.4
  ) + 16px);
}

.opencodian-message-time-row:hover {
  opacity: 1;
}

.opencodian-message-time-text {
  font-size: var(--opencodian-assistant-time-font-size);
  font-weight: var(--opencodian-assistant-time-font-weight);
  color: var(--opencodian-assistant-time-color);
}

.opencodian-message-model-id {
  color: var(--opencodian-assistant-model-id-color);
  flex: 1 1 auto;
  font-size: var(--opencodian-assistant-model-id-font-size);
  font-weight: var(--opencodian-assistant-model-id-font-weight);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
  font-family: var(--font-monospace);
  letter-spacing: 0.02em;
}

.opencodian-message-time-status {
  display: inline-flex;
  align-items: center;
  min-height: 18px;
  padding: 0 8px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 78%, transparent);
  font-size: max(10px, var(--opencodian-assistant-meta-font-size));
  font-weight: 600;
  letter-spacing: 0.01em;
}

.opencodian-message-time-status.is-warning {
  color: var(--text-warning);
  background: color-mix(in srgb, var(--text-warning) 12%, transparent);
  border-color: color-mix(in srgb, var(--text-warning) 28%, var(--background-modifier-border));
}

/* User message footer - actions and timestamp on the same row */
.opencodian-user-message-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  margin-top: 2px;
  margin-right: 4px;
  margin-bottom: 4px;
  gap: 8px;
  min-height: 30px;
  position: relative;
  z-index: 0;
}

.opencodian-user-message-time {
  font-size: var(--opencodian-user-time-font-size);
  font-weight: var(--opencodian-user-time-font-weight);
  color: var(--opencodian-user-time-color);
}

.opencodian-user-message-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(2px);
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.opencodian-message--user:hover .opencodian-user-message-actions,
.opencodian-message--user:focus-within .opencodian-user-message-actions {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.opencodian-copy-btn-inline--user {
  opacity: 1;
}

.opencodian-user-action-btn {
  padding: 0 12px;
  min-height: 30px;
  border-radius: 999px;
  border: 1px solid var(--opencodian-glass-border);
  background:
    linear-gradient(
      180deg,
      var(--opencodian-glass-specular) 0%,
      color-mix(in srgb, var(--opencodian-glass-specular-soft) 86%, transparent) 46%,
      transparent 100%
    ),
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--opencodian-glass-base-strong) 96%, transparent),
      color-mix(in srgb, var(--opencodian-glass-base) 82%, transparent)
    ),
    radial-gradient(
      circle at top,
      var(--opencodian-glass-highlight) 0%,
      transparent 62%
    );
  backdrop-filter: blur(20px) saturate(1.2);
  -webkit-backdrop-filter: blur(20px) saturate(1.2);
  box-shadow:
    0 12px 28px var(--opencodian-glass-shadow),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 94%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border) 52%, transparent) inset;
  color: var(--opencodian-text-strong);
  font-size: var(--font-ui-smaller);
  font-weight: 600;
  cursor: pointer;
  transition:
    color 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    transform 0.15s ease,
    opacity 0.15s ease;
}

.opencodian-user-action-btn--icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  min-width: 30px;
  min-height: 30px;
  padding: 0;
  border-radius: 10px;
}

.opencodian-user-action-btn--icon svg {
  width: 16px;
  height: 16px;
}

.opencodian-user-action-btn:hover:not(:disabled) {
  color: var(--text-normal);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--opencodian-glass-specular) 100%, transparent) 0%,
      color-mix(in srgb, var(--opencodian-glass-specular-soft) 94%, transparent) 42%,
      transparent 100%
    ),
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--opencodian-glass-base-strong) 98%, transparent),
      color-mix(in srgb, var(--opencodian-glass-base) 84%, transparent)
    ),
    radial-gradient(
      circle at top,
      var(--opencodian-glass-highlight-strong) 0%,
      transparent 60%
    );
  border-color: var(--opencodian-glass-border-strong);
  box-shadow:
    0 16px 34px var(--opencodian-glass-shadow-strong),
    0 1px 0 color-mix(in srgb, var(--opencodian-glass-specular) 98%, transparent) inset,
    0 -1px 0 color-mix(in srgb, var(--background-modifier-border-hover) 64%, transparent) inset;
  transform: translateY(-1px);
}

.opencodian-user-action-btn:disabled {
  opacity: 0.45;
  cursor: default;
}

/* Show copy button on assistant message hover */
.opencodian-message--assistant:hover .opencodian-copy-btn-inline {
  opacity: 1;
}

.opencodian-copy-btn-inline.copied {
  color: var(--text-accent);
  font-size: var(--font-ui-smaller);
  font-family: var(--font-monospace);
  width: auto;
  min-width: 30px;
  padding-inline: 10px;
}

.opencodian-fork-target-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 12px;
}

.opencodian-fork-target-option {
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid var(--background-modifier-border);
  background: var(--background-secondary);
  color: var(--text-normal);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.opencodian-fork-target-option:hover {
  background: var(--background-modifier-hover);
  border-color: var(--interactive-accent);
  transform: translateY(-1px);
}

.opencodian-fork-target-note {
  margin-top: 10px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  line-height: 1.4;
}

/* Tool use */
.opencodian-tool-use {
  margin: 8px 0;
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
  overflow: hidden;
  background: var(--background-secondary);
}

.opencodian-tool-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: var(--background-modifier-hover);
  font-weight: 500;
  font-size: 13px;
}

.opencodian-tool-icon {
  display: flex;
  align-items: center;
  color: var(--text-muted);
}

.opencodian-tool-input {
  margin: 0;
  padding: 12px;
  background: var(--background-primary);
  font-size: 13px;
  overflow-x: auto;
  max-height: 240px;
}

/* Input area */
.opencodian-input {
  flex: 0 0 auto;
  display: block;
  margin: 0;
  max-height: var(--opencodian-composer-max-height, 240px);
  padding: 8px 0 4px;
  width: 100%;
  background: transparent !important;
  background-image: none !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  resize: none;
  min-height: 68px;
  font-family: var(--opencodian-composer-font-family, "OpenCodian Newsreader", Georgia, serif);
  font-size: 14px;
  line-height: 1.5;
  color: transparent;
  caret-color: var(--text-normal);
  position: relative;
  z-index: 1;
  appearance: none;
  -webkit-appearance: none;
}

.opencodian-input:focus,
.opencodian-input:focus-visible,
.opencodian-input:hover {
  outline: none !important;
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}

.opencodian-input::placeholder {
  color: transparent;
}

/* ── Input highlight backdrop (renders styled @agent mentions behind the textarea) ── */

.opencodian-input-highlight-container {
  position: relative;
  width: 100%;
  min-height: 68px;
}

