/* ==================== Config Editor Modal Styles ==================== */

/* ------------------------------------------------------------------
 * Shared modal layout system
 * ------------------------------------------------------------------ */

/* Modal-scoped spacing tokens. Keep in sync with DESIGN.md spacing section. */
.modal .opencodian-modal-shell,
.modal .opencodian-help-modal-shell {
  --opencodian-modal-content-padding-x: 22px;
  --opencodian-modal-content-padding-y: 22px;
  --opencodian-modal-header-body-gap: 16px;
  --opencodian-modal-section-gap: 20px;
  --opencodian-modal-section-inner-gap: 12px;
  --opencodian-modal-card-gap: 12px;
  --opencodian-modal-form-row-gap: 12px;
  --opencodian-modal-form-label-control-gap: 16px;
  --opencodian-modal-action-gap: 8px;
  --opencodian-help-modal-section-gap: 16px;
}

/* Shell wrapper inside .modal-content. Replaces ad-hoc margins. */
.opencodian-modal-shell {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-modal-section-gap);
}

/* A section groups related controls/content. */
.opencodian-modal-section {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-modal-section-inner-gap);
}

/* Reusable card surface for modal content. No nested cards. */
.opencodian-modal-card {
  padding: 14px 16px;
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
}

/* Form grid: label/control rows with consistent vertical rhythm. */
.opencodian-modal-form-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--opencodian-modal-form-row-gap);
}

/* Action/footer row: right-aligned, compact, separated by top border. */
.opencodian-modal-actions {
  display: flex;
  gap: var(--opencodian-modal-action-gap);
  justify-content: flex-end;
  align-items: center;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-modal-actions button {
  margin: 0;
}

/* Help modals: compact shared layout. */
