  width: 100%;
  min-height: 34px;
  margin: 0;
  padding: 0 12px;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 84%, transparent);
  border-radius: 12px;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-primary) 96%, var(--background-secondary)) 0%,
      color-mix(in srgb, var(--background-primary) 88%, var(--background-secondary)) 100%
    );
  color: var(--text-normal);
  font-size: 13px;
  box-sizing: border-box;
}

.opencodian-session-settings-sharing-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  padding: 12px 20px 18px 0;
}

.opencodian-session-settings-sharing-button {
  min-height: 34px;
  margin: 0;
  padding: 0 14px;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 600;
}

.opencodian-session-settings-sharing-button:disabled {
  cursor: default;
  opacity: 0.62;
}

.opencodian-session-settings-sharing-status {
  min-width: 0;
  margin: 0;
  padding: 12px 0 18px 20px;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.55;
}

.opencodian-session-settings-sharing-url {
  margin-top: 6px;
  color: var(--text-accent);
  overflow-wrap: anywhere;
}

.opencodian-session-settings-sharing-hint {
  grid-column: 1 / -1;
  margin: 0 20px 14px;
  padding: 8px 12px;
  border: 1px solid color-mix(in srgb, var(--text-warning) 24%, var(--background-modifier-border));
  border-radius: 10px;
  background: color-mix(in srgb, var(--text-warning) 9%, var(--background-primary));
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.opencodian-session-settings-number-input:focus {
  outline: none;
  border-color: color-mix(in srgb, var(--interactive-accent) 48%, var(--background-modifier-border));
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--interactive-accent) 18%, transparent),
    0 0 0 4px color-mix(in srgb, var(--interactive-accent) 10%, transparent);
}

.opencodian-session-settings-error {
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--text-error) 28%, var(--background-modifier-border));
  border-radius: 12px;
  background: color-mix(in srgb, var(--text-error) 10%, var(--background-primary));
  color: var(--text-error);
  font-size: 12px;
  line-height: 1.45;
}

.opencodian-session-settings-error:empty {
  display: none;
}

.opencodian-session-settings-footer {
  position: sticky;
  bottom: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  flex: 0 0 auto;
  gap: 10px;
  margin: 8px -22px 0;
  padding: 8px 22px 0;
  background: transparent;
}

.opencodian-session-settings-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.opencodian-session-settings-actions button {
  min-height: 34px;
  margin: 0;
  padding: 0 16px;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 600;
}

.opencodian-session-settings-actions button:disabled,
.opencodian-session-settings-choice-button:disabled {
  cursor: default;
  opacity: 0.62;
}

/* ─── Summary divider ──────────────────────────────────────── */
.opencodian-session-settings-summary-divider {
  display: none;
}

/* ─── Summary rows ─────────────────────────────────────────── */
.opencodian-session-settings-summary-row {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) minmax(120px, 0.72fr) max-content;
  align-items: center;
  gap: 14px;
  padding: 9px 20px;
}

.opencodian-session-settings-summary-row + .opencodian-session-settings-summary-row {
  border-top: 1px solid color-mix(in srgb, var(--background-modifier-border) 74%, transparent);
}

.opencodian-session-settings-summary-label-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.opencodian-session-settings-summary-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-session-settings-summary-description {
  font-size: 11px;
  line-height: 1.4;
  color: var(--text-muted);
}

.opencodian-session-settings-summary-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  justify-content: flex-start;
  min-width: 0;
}

.opencodian-session-settings-summary-chip {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
  background: var(--background-modifier-hover);
  border-radius: 6px;
  padding: 3px 8px;
  white-space: nowrap;
}

.opencodian-session-settings-summary-link {
  font-size: 11px;
  font-weight: 500;
  color: var(--interactive-accent);
  background: none !important;
  border: none;
  box-shadow: none !important;
  height: auto;
  cursor: pointer;
  justify-self: end;
  min-height: 28px;
  padding: 5px 10px;
  border-radius: 8px;
  white-space: nowrap;
  transition: background 150ms ease;
}

.opencodian-session-settings-summary-link:hover {
  background: var(--background-modifier-hover) !important;
}

@media (max-width: 640px) {
  .opencodian-session-settings-modal {
    width: min(100vw - 24px, 720px);
  }

  .opencodian-session-settings-modal .modal-content {
    padding: 16px 16px 0;
  }

  .opencodian-session-settings-body {
    margin-right: -12px;
    padding-right: 12px;
  }

  .opencodian-conversation-compaction-help-modal {
    width: min(100vw - 24px, 920px);
  }

  .opencodian-conversation-compaction-help-modal .modal-content {
    padding: 8px 16px 18px;
  }

  .opencodian-compaction-help-grid {
    grid-template-columns: 1fr;
  }

  .opencodian-session-settings-hero {
    flex-direction: column;
    gap: 10px;
  }

  .opencodian-session-settings-section[data-section="sharing"] {
    grid-template-columns: 1fr;
  }

  .opencodian-session-settings-sharing-status {
    padding: 12px 16px 0;
  }

  .opencodian-session-settings-sharing-actions {
    justify-content: flex-start;
    padding: 8px 16px 16px;
  }

  .opencodian-session-settings-field {
    grid-template-columns: 1fr;
    gap: var(--opencodian-modal-section-inner-gap);
    padding: var(--opencodian-modal-form-row-gap) 16px;
  }

  .opencodian-session-settings-field-control {
    justify-content: flex-start;
  }

  .opencodian-session-settings-number-input {
    width: 100%;
    text-align: left;
  }

  .opencodian-session-settings-stepper {
    width: 100%;
  }

  .opencodian-session-settings-section[data-section="codex"] > .opencodian-session-settings-codex-goal-shell,
  .opencodian-session-settings-section[data-section="codex"] > .opencodian-session-settings-codex-review-shell {
    padding: var(--opencodian-modal-form-row-gap) 16px;
  }

  .opencodian-session-settings-codex-goal-set {
    grid-template-columns: 1fr;
  }

  .opencodian-session-settings-codex-goal-set-btn {
    justify-self: start;
  }

  .opencodian-session-settings-choice-group {
    width: 100%;
  }

  .opencodian-session-settings-choice-button {
    flex: 1 1 auto;
    min-width: 0;
    padding: 0 8px;
  }

  .opencodian-session-settings-choice-button[data-value="inherit"] {
    min-width: 0;
  }

  .opencodian-session-settings-summary-row {
    grid-template-columns: 1fr;
    gap: 8px;
    padding: 10px 16px;
  }

  .opencodian-session-settings-summary-label {
    min-width: unset;
  }

  .opencodian-session-settings-summary-label-group {
    min-width: 0;
  }

  .opencodian-session-settings-summary-link {
    justify-self: start;
    padding-left: 0;
  }

  .opencodian-session-settings-footer {
    margin-right: -16px;
    margin-left: -16px;
    padding-right: 16px;
    padding-left: 16px;
  }
}

.opencodian-context-detail-modal {
  width: min(1120px, calc(100vw - 32px)) !important;
  max-width: none !important;
}

.opencodian-context-detail-modal .modal-content {
  width: 100%;
  max-width: none;
  box-sizing: border-box;
}

.opencodian-context-modal-empty {
  padding: 12px 0;
  color: var(--text-muted);
}

.opencodian-context-modal-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px 16px;
  margin-top: 16px;
}

.opencodian-context-modal-row {
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
}

.opencodian-context-modal-label {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.opencodian-context-modal-value {
  font-size: 14px;
  color: var(--text-normal);
  word-break: break-word;
}

.opencodian-context-breakdown {
  margin-top: 18px;
}

.opencodian-context-breakdown-title {
  margin-bottom: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-context-breakdown-bar {
  display: flex;
  width: 100%;
  height: 12px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
}

.opencodian-context-breakdown-segment {
  height: 100%;
  min-width: 2px;
}

.opencodian-context-breakdown-segment.is-system {
  background: var(--text-accent);
}

.opencodian-context-breakdown-segment.is-user {
  background: var(--text-success);
}

.opencodian-context-breakdown-segment.is-assistant {
  background: color-mix(in srgb, var(--interactive-accent) 72%, var(--color-pink, #cc5de8));
}

.opencodian-context-breakdown-segment.is-tool {
  background: var(--text-warning);
}

.opencodian-context-breakdown-segment.is-other {
  background: var(--text-faint);
}

.opencodian-context-breakdown-legend {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 12px;
  margin-top: 12px;
}

.opencodian-context-breakdown-item {
  display: grid;
  grid-template-columns: 12px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
}

.opencodian-context-breakdown-swatch {
  width: 10px;
  height: 10px;
  border-radius: 999px;
}

.opencodian-context-breakdown-swatch.is-system {
  background: var(--text-accent);
}

.opencodian-context-breakdown-swatch.is-user {
  background: var(--text-success);
}

.opencodian-context-breakdown-swatch.is-assistant {
  background: color-mix(in srgb, var(--interactive-accent) 72%, var(--color-pink, #cc5de8));
}

.opencodian-context-breakdown-swatch.is-tool {
  background: var(--text-warning);
}

.opencodian-context-breakdown-swatch.is-other {
  background: var(--text-faint);
}

.opencodian-context-breakdown-name {
  min-width: 0;
  font-size: 13px;
  color: var(--text-normal);
}

.opencodian-context-breakdown-percent,
.opencodian-context-breakdown-tokens {
  font-size: 12px;
  color: var(--text-muted);
  white-space: nowrap;
}

.opencodian-context-modal-note {
  margin-top: 14px;
  font-size: 12px;
  color: var(--text-muted);
}

.opencodian-context-compaction-action-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  margin-top: 20px;
  padding-top: 14px;
  border-top: 1px solid var(--background-modifier-border);
}

.opencodian-context-compaction-copy {
  min-width: 0;
  flex: 1 1 auto;
}

.opencodian-context-compaction-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-context-compaction-target {
  min-width: 0;
  margin-top: 4px;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.opencodian-context-compaction-thread {
  color: var(--text-normal);
  font-family: var(--font-monospace);
  user-select: text;
  overflow-wrap: anywhere;
}

.opencodian-context-compaction-controls {
  display: flex;
  flex: 0 1 260px;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
}

.opencodian-context-compaction-button {
  max-width: 100%;
  min-width: 0;
  min-height: 30px;
  box-sizing: border-box;
  white-space: normal;
}

.opencodian-context-compaction-status {
  max-width: 100%;
  min-width: 0;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.opencodian-context-compaction-status.is-error {
  color: var(--text-error);
}

.opencodian-context-compaction-status.is-pending-verification {
  color: var(--text-warning);
}

.opencodian-context-compaction-status.is-success {
  color: var(--text-success);
}

.opencodian-context-raw-messages {
  margin-top: 18px;
}

.opencodian-context-raw-messages-title {
  margin-bottom: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-context-raw-messages-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.opencodian-context-raw-messages-state {
  padding: 12px;
  border-radius: 10px;
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
  font-size: 13px;
  color: var(--text-muted);
}

.opencodian-context-raw-message {
  border-radius: 10px;
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
  overflow: hidden;
}

.opencodian-context-raw-message-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  cursor: pointer;
  list-style: none;
}

.opencodian-context-raw-message-summary::-webkit-details-marker {
  display: none;
}

.opencodian-context-raw-message-summary-main {
  min-width: 0;
  font-size: 13px;
  color: var(--text-normal);
  word-break: break-word;
}

.opencodian-context-raw-message-summary-time {
  flex-shrink: 0;
  font-size: 12px;
  color: var(--text-muted);
}

.opencodian-context-raw-message-content {
  padding: 0 12px 12px;
}

.opencodian-context-raw-message-pre {
  margin: 0;
  padding: 12px;
  overflow: auto;
  border-radius: 8px;
  background: var(--background-primary);
  border: 1px solid var(--background-modifier-border);
}

.opencodian-context-raw-message-code {
  display: block;
  font-family: var(--font-monospace);
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-normal);
  white-space: pre;
}

@media (max-width: 720px) {
  .opencodian-context-modal-grid,
  .opencodian-context-breakdown-legend {
    grid-template-columns: minmax(0, 1fr);
  }

  .opencodian-context-compaction-action-row {
    flex-direction: column;
  }

  .opencodian-context-compaction-controls {
    width: 100%;
    flex-basis: auto;
  }

  .opencodian-context-compaction-button {
    width: 100%;
  }
}

/* Editor textarea sizing */
.opencodian-config-editor {
  width: 100%;
  min-height: 80px;
  max-height: 500px;
  font-family: var(--font-monospace);
  font-size: 13px;
  line-height: 1.5;
  padding: 12px;
  background: var(--background-secondary);
  border: 1px solid var(--background-modifier-border);
  border-radius: 6px;
  color: var(--text-normal);
  resize: vertical;
  tab-size: 2;
}

.opencodian-model-config-json-editor {
  min-height: clamp(160px, 22vh, 280px);
}

.opencodian-model-catalog {
  margin: 12px 0 18px;
}

.opencodian-settings-block {
  margin: 14px 0 18px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 14px;
  background: var(--background-secondary);
  overflow: hidden;
}

.opencodian-settings-general-merged-block {
  margin: 0;
}

.opencodian-settings-block > .opencodian-settings-subsection-heading,
.opencodian-settings-block-summary > .opencodian-settings-subsection-heading {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  color: var(--text-normal);
}

.opencodian-settings-block-desc {
  margin-top: 6px;
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-muted);
}

.opencodian-settings-block > .opencodian-settings-subsection-heading,
.opencodian-settings-block-desc,
.opencodian-settings-block-summary {
  padding-left: 16px;
  padding-right: 16px;
}

.opencodian-settings-block > .opencodian-settings-subsection-heading {
  padding-top: 14px;
}

.opencodian-settings-block > .opencodian-settings-block-desc {
  padding-bottom: 0;
}

.opencodian-settings-block-footer-desc {
  margin-top: 0;
  padding-top: 12px;
  padding-bottom: 24px;
  border-top: 1px solid var(--background-modifier-border-hover);
}

.opencodian-settings-block > .opencodian-settings-block-footer-desc {
  padding-bottom: 24px;
}

.opencodian-settings-block-body {
  padding: 14px 16px 16px;
}

.opencodian-settings-block-details[open] > .opencodian-settings-block-summary {
  border-bottom: 1px solid var(--background-modifier-border-hover);
}

.opencodian-settings-block-summary {
  list-style: none;
  cursor: pointer;
  padding-top: 14px;
  padding-bottom: 14px;
}

.opencodian-settings-block-summary:has(.opencodian-model-section-toggles) {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 15px;
  padding-bottom: 15px;
}

.opencodian-icon-cache-block > .opencodian-settings-block-summary > .opencodian-settings-block-desc {
  padding-left: 0;
  text-indent: 0;
}

.opencodian-settings-block-summary::-webkit-details-marker {
  display: none;
}

.opencodian-model-common-summary {
  margin-bottom: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 88%, transparent);
  background: color-mix(in srgb, var(--background-primary) 78%, transparent);
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

.opencodian-model-catalog-comparison {
  display: flex;
  align-items: center;
  min-height: 28px;
  margin: -4px 0 14px;
  padding: 5px 8px;
  border-left: 2px solid var(--background-modifier-border);
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.45;
}

.opencodian-model-catalog-comparison.is-match {
  border-left-color: var(--color-green);
}

.opencodian-model-catalog-comparison.is-drift {
  border-left-color: var(--color-yellow);
}

.opencodian-model-catalog-comparison.is-unavailable {
  border-left-color: var(--text-faint);
}

.opencodian-model-availability-controls {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) auto auto auto;
  align-items: center;
  gap: var(--opencodian-settings-space-md, 8px);
  margin-bottom: 0;
}

.opencodian-model-availability-search {
  min-width: 0;
}

.opencodian-model-availability-search-container {
  display: flex;
  align-items: center;
  gap: var(--opencodian-settings-space-md, 8px);
  min-height: 28px;
  padding: 0 9px;
  border-radius: var(--opencodian-settings-radius-inline, 6px);
  border: 1px solid var(--opencodian-settings-inline-border, var(--background-modifier-border));
  background: var(--opencodian-settings-inline-bg, var(--background-secondary));
  box-shadow: none;
  transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
}

.opencodian-model-availability-search-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: var(--text-muted);
  pointer-events: none;
}

.opencodian-model-availability-search-input {
  flex: 1 1 auto;
  width: auto;
  min-width: 0;
  min-height: 28px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-normal);
  box-shadow: none;
  font-size: 13px;
}

.opencodian-model-availability-search-input:focus {
  outline: none;
  box-shadow: none;
}

.opencodian-model-availability-search-input::placeholder {
  color: var(--text-faint);
}

.opencodian-model-availability-search-container:focus-within {
  border-color: color-mix(in srgb, var(--background-modifier-border-hover) 82%, transparent);
  background: color-mix(in srgb, var(--background-primary) 84%, var(--opencodian-settings-inline-bg, var(--background-secondary)));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--background-modifier-border-hover) 18%, transparent);
}

.opencodian-model-availability-filter-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
