  }

  .opencodian-model-toggle-provider:hover {
    transform: none;
  }
}

.opencodian-plugin-block {
  margin: var(--opencodian-settings-space-xl) 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

.opencodian-plugin-block > .opencodian-settings-subsection-heading {
  margin: 0;
  padding: 0;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  color: var(--text-normal);
}

.opencodian-plugin-block-desc {
  padding: 4px 0 0;
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-muted);
}

.opencodian-plugin-block-body {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-md);
  padding: var(--opencodian-settings-space-md) 0 0;
}

.opencodian-settings[data-settings-layout-mode="classic"] .opencodian-plugin-block {
  margin: var(--opencodian-settings-space-lg) 0 var(--opencodian-settings-space-xl);
  padding: 14px;
  border: 1px solid var(--opencodian-settings-object-border);
  border-radius: var(--opencodian-settings-radius-row);
  background: var(--opencodian-settings-object-bg);
  box-shadow: none;
}

.opencodian-settings[data-settings-layout-mode="classic"] .opencodian-plugin-block > .opencodian-settings-subsection-heading {
  padding: 0;
  font-size: 13px;
  line-height: 1.35;
  color: var(--text-normal);
}

.opencodian-settings[data-settings-layout-mode="classic"] .opencodian-plugin-block-body {
  margin-top: var(--opencodian-settings-space-lg);
  padding-top: var(--opencodian-settings-space-lg);
  border-top: 1px solid color-mix(in srgb, var(--opencodian-settings-object-border) 78%, transparent);
}

.opencodian-settings[data-settings-layout-mode="classic"] .opencodian-settings-catalog-scroll > .setting-item + .setting-item {
  margin-top: var(--opencodian-settings-space-md);
}

.opencodian-settings-catalog-scroll,
.opencodian-agent-catalog-scroll {
  max-height: min(460px, 52vh);
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 2px;
}

.opencodian-settings-catalog-scroll > .setting-item {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--opencodian-settings-row-border);
  border-radius: var(--opencodian-settings-radius-row);
  background: var(--opencodian-settings-row-bg);
  box-shadow: none;
}

.opencodian-settings-catalog-scroll > .setting-item + .setting-item {
  margin-top: var(--opencodian-settings-space-sm);
}

.opencodian-settings-catalog-scroll > .setting-item .setting-item-info {
  min-width: 0;
}

/* ── Command Catalog Card Layout ──────────────────────────── */

.opencodian-cmd-catalog-controls {
  display: flex;
  flex-wrap: wrap;
  gap: var(--opencodian-settings-space-md, 8px);
  margin-bottom: var(--opencodian-settings-space-md, 8px);
}

.opencodian-cmd-catalog-search {
  flex: 1 1 200px;
  min-width: 0;
}

.opencodian-cmd-catalog-search-container {
  display: flex;
  align-items: center;
  gap: var(--opencodian-settings-space-md, 8px);
  min-height: 36px;
  padding: 0 11px;
  border-radius: var(--opencodian-settings-radius-inline, 6px);
  border: 1px solid var(--opencodian-settings-inline-border, var(--background-modifier-border));
  background: var(--opencodian-settings-inline-bg, var(--background-secondary));
  box-shadow: none;
  transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
}

.opencodian-cmd-catalog-search-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: color-mix(in srgb, var(--interactive-accent) 54%, var(--text-muted));
  pointer-events: none;
}

.opencodian-cmd-catalog-search-input {
  flex: 1 1 auto;
  width: auto;
  min-width: 0;
  min-height: 36px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-normal);
  box-shadow: none;
  font-size: 13px;
}

.opencodian-cmd-catalog-search-input:focus {
  outline: none;
  box-shadow: none;
}

.opencodian-cmd-catalog-search-input::placeholder {
  color: var(--text-faint);
}

.opencodian-cmd-catalog-search-container:focus-within {
  border-color: var(--opencodian-settings-nav-active-border, var(--background-modifier-border-hover));
  background: color-mix(in srgb, var(--interactive-accent) 5%, var(--opencodian-settings-inline-bg, var(--background-secondary)));
  box-shadow: 0 0 0 2px var(--opencodian-settings-focus-ring, color-mix(in srgb, var(--interactive-accent) 18%, transparent));
}

.opencodian-cmd-catalog-filter-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
}

.opencodian-cmd-catalog-filter-pill {
  all: unset;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 14px;
  border: 1px solid var(--opencodian-settings-inline-border, var(--background-modifier-border));
  background: transparent;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.opencodian-cmd-catalog-filter-pill:hover {
  border-color: var(--opencodian-settings-nav-active-border, var(--background-modifier-border-hover));
  background: var(--opencodian-settings-inline-bg, var(--background-secondary));
  color: var(--text-normal);
}

.opencodian-cmd-catalog-filter-pill.is-active {
  border-color: var(--interactive-accent);
  background: color-mix(in srgb, var(--interactive-accent) 14%, transparent);
  color: var(--interactive-accent);
}

.opencodian-cmd-catalog-batch-bar {
  display: flex;
  align-items: center;
  gap: var(--opencodian-settings-space-md, 8px);
  margin-bottom: var(--opencodian-settings-space-md, 8px);
  padding: 6px 10px;
  border-radius: var(--opencodian-settings-radius-inline, 6px);
  border: 1px solid color-mix(in srgb, var(--interactive-accent) 30%, var(--opencodian-settings-inline-border, var(--background-modifier-border)));
  background: color-mix(in srgb, var(--interactive-accent) 6%, transparent);
}

.opencodian-cmd-catalog-batch-count {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
  flex: 1 1 auto;
}

.opencodian-cmd-catalog-batch-btn {
  all: unset;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--interactive-accent) 14%, transparent);
  color: var(--interactive-accent);
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease;
}

.opencodian-cmd-catalog-batch-btn:hover {
  background: color-mix(in srgb, var(--interactive-accent) 22%, transparent);
}

.opencodian-cmd-catalog-scroll {
  max-height: min(460px, 52vh);
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 2px;
}

.opencodian-cmd-catalog-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  align-items: start;
}

.opencodian-cmd-catalog-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 12px;
  border: 1px solid var(--opencodian-settings-row-border);
  border-radius: var(--opencodian-settings-radius-row, 8px);
  background: var(--opencodian-settings-row-bg);
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.opencodian-cmd-catalog-card:hover {
  border-color: var(--opencodian-settings-nav-active-border, var(--background-modifier-border-hover));
}

.opencodian-cmd-catalog-card.is-hidden {
  opacity: 0.6;
}

.opencodian-cmd-catalog-card-header {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  min-height: 0;
}

.opencodian-cmd-catalog-card-left {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  flex: 1 1 auto;
  min-width: 0;
}

.opencodian-cmd-catalog-select-checkbox {
  appearance: none;
  -webkit-appearance: none;
  display: inline-grid;
  place-content: center;
  width: 16px;
  height: 16px;
  margin: 0;
  flex: 0 0 auto;
  border: 1.5px solid color-mix(in srgb, var(--text-muted) 64%, var(--background-modifier-border));
  border-radius: 4px;
  background: color-mix(in srgb, var(--background-primary) 84%, transparent);
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}

.opencodian-cmd-catalog-select-checkbox::after {
  content: "";
  width: 8px;
  height: 5px;
  border: solid var(--text-on-accent, var(--background-primary));
  border-width: 0 0 2px 2px;
  opacity: 0;
  transform: rotate(-45deg);
}

.opencodian-cmd-catalog-select-checkbox:hover {
  border-color: color-mix(in srgb, var(--interactive-accent) 62%, var(--background-modifier-border-hover));
}

.opencodian-cmd-catalog-select-checkbox:checked {
  border-color: var(--interactive-accent);
  background: var(--interactive-accent);
}

.opencodian-cmd-catalog-select-checkbox:checked::after {
  opacity: 1;
}

.opencodian-cmd-catalog-select-checkbox:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--opencodian-settings-focus-ring, color-mix(in srgb, var(--interactive-accent) 22%, transparent));
}

.opencodian-cmd-catalog-card-name {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-normal);
  white-space: nowrap;
  min-width: 0;
}

.opencodian-cmd-catalog-chip {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: 8px;
  font-size: 10px;
  font-weight: 500;
  white-space: nowrap;
  line-height: 1.4;
}

.opencodian-cmd-catalog-chip-source-command {
  background: color-mix(in srgb, var(--interactive-accent) 14%, transparent);
  color: var(--interactive-accent);
}

.opencodian-cmd-catalog-chip-source-skill {
  background: color-mix(in srgb, #e67e22 14%, transparent);
  color: #e67e22;
}

.opencodian-cmd-catalog-chip-source-project {
  background: color-mix(in srgb, #2ecc71 14%, transparent);
  color: #2ecc71;
}

.opencodian-cmd-catalog-chip-source-md-command {
  background: color-mix(in srgb, #9b59b6 14%, transparent);
  color: #9b59b6;
}

.opencodian-cmd-catalog-chip-subtask {
  background: color-mix(in srgb, var(--text-muted) 14%, transparent);
  color: var(--text-muted);
}

.opencodian-cmd-catalog-chip-unavailable {
  background: color-mix(in srgb, #e74c3c 12%, transparent);
  color: #e74c3c;
}

.opencodian-cmd-catalog-chip-agent {
  background: color-mix(in srgb, var(--text-muted) 10%, transparent);
  color: var(--text-muted);
}

.opencodian-cmd-catalog-chip-model {
  background: color-mix(in srgb, var(--text-muted) 10%, transparent);
  color: var(--text-muted);
}

.opencodian-cmd-catalog-card-toggle {
  flex: 0 0 auto;
  margin: 0;
  cursor: pointer;
}

.opencodian-cmd-catalog-toggle-checkbox {
  cursor: pointer;
}

.opencodian-cmd-catalog-card-desc {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.4;
  max-height: 2.8em;
  overflow: hidden;
  cursor: pointer;
  transition: max-height 0.2s ease;
  padding-left: 2px;
}

.opencodian-cmd-catalog-card-desc.is-expanded {
  max-height: none;
}

.opencodian-cmd-catalog-empty {
  padding: var(--opencodian-settings-space-lg, 12px);
  color: var(--text-muted);
  font-size: 13px;
  text-align: center;
}

@media (max-width: 720px) {
  .opencodian-cmd-catalog-grid {
    grid-template-columns: 1fr;
  }
}

/* ── End Command Catalog Card Layout ──────────────────────── */

.opencodian-agent-editor-layout {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-md);
}

.opencodian-agent-editor-group {
  border: 1px solid var(--opencodian-settings-object-border);
  border-radius: var(--opencodian-settings-radius-row);
  background: var(--opencodian-settings-object-bg);
  box-shadow: none;
  overflow: hidden;
}

.opencodian-agent-editor-group-header,
.opencodian-agent-editor-group-summary {
  padding: 12px;
  background: transparent;
}

.opencodian-agent-editor-group-summary {
  display: flex;
  align-items: center;
  gap: var(--opencodian-settings-space-md);
  cursor: pointer;
  list-style: none;
}

.opencodian-agent-editor-group-summary::-webkit-details-marker {
  display: none;
}

.opencodian-agent-editor-group-summary::after {
  content: "▾";
  margin-left: auto;
  color: var(--text-faint);
  font-size: 13px;
  line-height: 1;
  transition: transform 0.16s ease, color 0.16s ease;
}

.opencodian-agent-editor-group-collapsible[open] > .opencodian-agent-editor-group-summary::after {
  transform: rotate(180deg);
  color: var(--text-muted);
}

.opencodian-agent-editor-group-summary-copy {
  min-width: 0;
}

.opencodian-agent-editor-group-title {
  color: var(--text-normal);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
}

.opencodian-agent-editor-group-description {
  margin-top: 4px;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

.opencodian-agent-editor-group-body {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-sm);
  padding: 0 12px 12px;
}

.opencodian-agent-editor-group-body > .setting-item {
  margin: 0;
  padding: 8px 0;
  border-top: 1px solid var(--opencodian-settings-row-border);
  background: transparent;
  box-shadow: none;
}

.opencodian-agent-editor-group-body > .setting-item:first-child {
  border-top: none;
}

.opencodian-mcp-settings-shell,
.opencodian-mcp-add-form-layout {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-lg);
  min-width: 0;
}

.opencodian-mcp-overview-shell,
.opencodian-mcp-server-list-shell {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-md);
  width: 100%;
  min-width: 0;
}

.opencodian-mcp-overview-section {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
}

.opencodian-mcp-overview-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.opencodian-mcp-overview-shell {
  padding: 14px 16px 12px;
  border: 1px solid var(--opencodian-settings-form-row-border);
  border-radius: var(--opencodian-settings-radius-row);
  background: color-mix(in srgb, var(--opencodian-settings-inline-bg) 82%, var(--background-secondary));
}

.opencodian-settings[data-settings-layout-mode="classic"] .opencodian-mcp-settings-shell {
  gap: var(--opencodian-settings-space-xl);
}

.opencodian-mcp-overview-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px 14px;
  align-items: start;
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.opencodian-mcp-overview-toolbar-copy {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 0;
}

.opencodian-mcp-overview-title-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  min-width: 0;
  width: fit-content;
  max-width: 100%;
}

.opencodian-mcp-overview-title {
  margin: 0;
  padding-inline-start: 0;
  flex: 0 1 auto;
}

.opencodian-mcp-overview-description,
.opencodian-mcp-server-list-description {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.55;
  overflow-wrap: anywhere;
  max-width: 64ch;
}

.opencodian-mcp-overview-toolbar-action,
.opencodian-mcp-overview-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  align-items: center;
  min-width: 0;
  width: fit-content;
  max-width: 100%;
}

.opencodian-mcp-refresh-setting,
.opencodian-mcp-toolbar-add,
.opencodian-mcp-toolbar-add-setting {
  display: inline-flex;
  flex: 0 0 auto;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  box-shadow: none;
  min-height: auto;
}

.opencodian-settings .opencodian-mcp-overview-actions .setting-item,
.opencodian-settings .opencodian-mcp-server-card-actions .setting-item,
.opencodian-settings .opencodian-mcp-server-row-actions .setting-item {
  display: inline-flex;
  grid-template-columns: none;
  align-items: center;
  width: auto;
  min-width: 0;
  max-width: 100%;
  gap: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.opencodian-mcp-refresh-setting .setting-item-info,
.opencodian-mcp-toolbar-add-setting .setting-item-info,
.opencodian-mcp-server-row-actions .setting-item-info,
.opencodian-mcp-server-card-actions .setting-item-info {
  display: none;
}

.opencodian-mcp-refresh-setting .setting-item-control,
.opencodian-mcp-toolbar-add .setting-item-control,
.opencodian-mcp-toolbar-add-setting .setting-item-control,
.opencodian-mcp-server-row-actions .setting-item-control,
.opencodian-mcp-server-card-actions .setting-item-control {
  display: inline-flex;
  padding: 0;
  margin: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  justify-content: flex-start;
}

.opencodian-mcp-overview-actions button {
  min-height: 32px;
  padding: 6px 14px;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 72%, var(--background-primary));
  border-radius: 10px;
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--text-on-accent) 7%, transparent),
    0 1px 2px color-mix(in srgb, var(--background-primary) 42%, transparent);
  background: color-mix(in srgb, var(--background-modifier-hover) 34%, var(--background-secondary));
  color: var(--text-normal);
  font-size: 12px;
  font-weight: 650;
  outline: none;
  appearance: none;
  -webkit-appearance: none;
}

.opencodian-mcp-overview-actions button:hover,
.opencodian-mcp-overview-actions button:focus-visible {
  background: color-mix(in srgb, var(--background-modifier-hover) 44%, var(--background-secondary));
  border-color: color-mix(in srgb, var(--background-modifier-border-hover) 76%, var(--background-primary));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--text-on-accent) 9%, transparent),
    0 2px 6px color-mix(in srgb, var(--background-primary) 36%, transparent);
}

.opencodian-mcp-toolbar-add-setting button {
  background: color-mix(in srgb, var(--background-modifier-hover) 34%, var(--background-secondary));
  border-color: color-mix(in srgb, var(--background-modifier-border) 72%, var(--background-primary));
  color: var(--text-normal);
}

.opencodian-mcp-overview {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  padding-top: 10px;
}

.opencodian-mcp-overview--title-rail {
  flex: 0 1 auto;
  justify-content: flex-start;
  padding-top: 0;
}

.opencodian-mcp-overview-cards {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding-top: 2px;
}

.opencodian-mcp-overview--title-rail .opencodian-mcp-overview-cards {
  justify-content: flex-start;
  padding-top: 0;
}

.opencodian-mcp-overview-card {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 26px;
  max-width: 100%;
  padding: 3px 9px;
  border: 1px solid color-mix(in srgb, var(--opencodian-settings-inline-border) 82%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--background-primary) 68%, transparent);
  box-shadow: none;
}

.opencodian-mcp-overview-card-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  flex: 0 0 auto;
  background: color-mix(in srgb, var(--text-muted) 72%, transparent);
}

.opencodian-mcp-overview-card--success .opencodian-mcp-overview-card-dot {
  background: color-mix(in srgb, var(--color-green) 70%, transparent);
}

.opencodian-mcp-overview-card--accent .opencodian-mcp-overview-card-dot {
  background: color-mix(in srgb, var(--interactive-accent) 72%, transparent);
}

.opencodian-mcp-overview-card--danger .opencodian-mcp-overview-card-dot {
  background: color-mix(in srgb, var(--color-red) 72%, transparent);
}

.opencodian-mcp-overview-card-value {
  color: var(--text-normal);
  font-size: 12px;
