/* Source scope filter (All / Global / Project) */
.opencodian-plugin-source-filter {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 3px;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--opencodian-settings-radius-inline);
  /* Shrink to fit content on wide screens (shadcn TabsList compact form).
   * The filter host is a column flex parent whose children stretch by
   * default; align-self + width:fit-content keeps the bar left-aligned
   * and compact instead of occupying the full row. */
  align-self: flex-start;
  width: fit-content;
  max-width: 100%;
  box-sizing: border-box;
  overflow: hidden;
  background: var(--background-secondary);
}

.opencodian-plugin-source-filter-button {
  appearance: none;
  border: 1px solid transparent;
  border-radius: var(--opencodian-settings-radius-inline);
  background: transparent;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.5;
  padding: 4px 10px;
  cursor: pointer;
  transition: background-color 120ms ease-out, color 120ms ease-out, border-color 120ms ease-out;
}

.opencodian-plugin-source-filter-button:hover {
  color: var(--text-normal);
  background: var(--background-modifier-hover);
}

.opencodian-plugin-source-filter-button:focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 1px;
}

.opencodian-plugin-source-filter-button.is-active {
  background: var(--interactive-accent);
  border-color: var(--interactive-accent);
  color: var(--text-on-accent, var(--background-primary));
}

.opencodian-plugin-source-filter-host {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-sm);
}

.opencodian-plugin-source-filter-host:empty {
  display: none;
}

/* Filter visibility: hide non-matching scopes without re-rendering the DOM. */
.opencodian-plugin-source-filter-host[data-source-filter="global"] [data-source-scope="project"],
.opencodian-plugin-source-filter-host[data-source-filter="project"] [data-source-scope="global"] {
  display: none;
}

/*
 * Per-scope empty placeholders.
 *
 * The placeholder is only emitted when its scope has zero sources, so the
 * `:has([data-source-scope="X"])` guard is technically redundant here — but
 * it is intentionally kept as defense-in-depth: if a future code path ever
 * renders both a real source and a placeholder for the same scope, the CSS
 * will still hide the placeholder.
 */
.opencodian-plugin-source-scope-empty {
  display: none;
  padding: 6px 0;
  color: var(--text-faint);
  font-size: 12px;
  font-style: italic;
  line-height: 1.55;
}

.opencodian-plugin-source-filter-host[data-source-filter="global"]:not(:has([data-source-scope="global"])) [data-empty-scope="global"],
.opencodian-plugin-source-filter-host[data-source-filter="project"]:not(:has([data-source-scope="project"])) [data-empty-scope="project"] {
  display: block;
}

/* Managed plugin entry row with toggle and delete */
.opencodian-plugin-source-item.is-plugin-disabled {
  opacity: 0.55;
}

.opencodian-plugin-source-item:has(.opencodian-plugin-toggle) {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
}

.opencodian-plugin-toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  flex-shrink: 0;
  margin: 0;
}

.opencodian-plugin-toggle input[type="checkbox"] {
  margin: 0;
  cursor: pointer;
  accent-color: var(--interactive-accent);
}

.opencodian-plugin-toggle-label {
  font-size: 10px;
  color: var(--text-muted);
  white-space: nowrap;
}

.opencodian-plugin-entry-desc {
  flex: 1;
  min-width: 0;
}

.opencodian-plugin-entry-delete {
  flex-shrink: 0;
  padding: 2px 8px;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--opencodian-settings-radius-row);
  background: transparent;
  color: var(--text-muted);
  font-size: 11px;
  cursor: pointer;
  line-height: 1.4;
}

.opencodian-plugin-entry-delete:hover {
  background: var(--background-modifier-hover);
  color: var(--text-normal);
}

.opencodian-plugin-entry-delete:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* SDK plugin evidence panel */
.opencodian-plugin-evidence-section {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-sm);
  padding: 12px 0;
  border-top: 1px solid var(--opencodian-settings-row-border);
}

.opencodian-plugin-evidence-section:first-child {
  padding-top: 0;
  border-top: none;
}

.opencodian-plugin-evidence-section-title {
  margin: 0;
  padding: 0;
  font-size: 13px;
  font-weight: 650;
  color: var(--text-normal);
  line-height: 1.35;
}

.opencodian-plugin-evidence-section-desc {
  margin: 0;
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-muted);
}

.opencodian-plugin-evidence-empty {
  margin: 0;
  font-size: 12px;
  color: var(--text-faint);
  font-style: italic;
}

.opencodian-plugin-evidence-subsection {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-xs);
  margin-top: var(--opencodian-settings-space-xs);
}

.opencodian-plugin-evidence-subsection-title {
  margin: 0;
  padding: 0;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.opencodian-plugin-evidence-list {
  display: flex;
  flex-direction: column;
  gap: var(--opencodian-settings-space-xs);
}

.opencodian-plugin-evidence-item {
  padding: 8px 10px;
  border: 1px solid var(--opencodian-settings-object-border);
  border-radius: var(--opencodian-settings-radius-row);
  background: var(--opencodian-settings-object-bg);
  word-break: break-word;
  overflow-wrap: anywhere;
}

.opencodian-plugin-evidence-code {
  font-family: var(--font-monospace);
  font-size: 12px;
  color: var(--text-normal);
}

.opencodian-plugin-evidence-meta {
  margin-top: 4px;
  font-family: var(--font-monospace);
  font-size: 11px;
  color: var(--text-faint);
  line-height: 1.5;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.opencodian-plugin-remote-notice {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--text-warning) 30%, var(--background-modifier-border));
  border-radius: var(--opencodian-settings-radius-row);
  background: color-mix(in srgb, var(--text-warning) 7%, var(--background-secondary));
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.55;
}

.opencodian-plugin-remote-notice-label {
  font-weight: 650;
  color: var(--text-warning);
}

.opencodian-plugin-local-only-label {
  margin-top: 6px;
  padding: 2px 8px;
  border: 1px solid var(--opencodian-settings-inline-border);
  border-radius: 999px;
  background: var(--opencodian-settings-inline-bg);
  color: var(--text-faint);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
  width: fit-content;
}

.opencodian-model-catalog-panel {
  border: none;
  border-radius: 0;
  background: transparent;
  overflow: hidden;
}

.opencodian-model-catalog-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 6px;
  margin-bottom: 0;
}

.opencodian-model-catalog-summary-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 2px;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 52px;
  padding: 7px 10px;
  border-radius: var(--opencodian-settings-radius-row, 8px);
  appearance: none;
  -webkit-appearance: none;
  background: var(--opencodian-model-card-bg, var(--opencodian-settings-object-bg, var(--background-primary)));
  border: 1px solid var(--opencodian-model-card-border, var(--opencodian-settings-object-border, var(--background-modifier-border)));
  box-shadow: none;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.opencodian-model-catalog-summary-card:hover {
  border-color: var(--opencodian-model-card-border-hover, color-mix(in srgb, var(--background-modifier-border-hover) 82%, transparent));
  background: var(--opencodian-model-card-bg-hover, color-mix(in srgb, var(--background-primary) 82%, var(--background-secondary)));
}

.opencodian-model-catalog-summary-card:focus-visible {
  outline: none;
  border-color: var(--opencodian-model-card-border-hover, color-mix(in srgb, var(--background-modifier-border-hover) 82%, transparent));
  box-shadow: 0 0 0 3px var(--opencodian-model-card-ring, color-mix(in srgb, var(--background-modifier-border-hover) 18%, transparent));
}

.opencodian-model-catalog-summary-card.is-active {
  border-color: var(--opencodian-model-card-border-hover, color-mix(in srgb, var(--background-modifier-border-hover) 82%, transparent));
  background: var(--opencodian-model-card-bg-hover, color-mix(in srgb, var(--background-primary) 82%, var(--background-secondary)));
  box-shadow: inset 0 0 0 1px var(--opencodian-model-card-ring, color-mix(in srgb, var(--background-modifier-border-hover) 18%, transparent));
}

.opencodian-model-catalog-summary-card.is-active .opencodian-model-catalog-summary-card-title {
  color: var(--text-normal);
}

.opencodian-model-catalog-summary-card-title {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text-normal);
}

.opencodian-model-catalog-summary-card-meta {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 11px;
  line-height: 1.3;
  color: var(--text-muted);
  white-space: nowrap;
}

.opencodian-model-picker-modal .modal-header {
  display: none;
}

.opencodian-model-picker-modal .modal-content {
  padding: 0;
}

.opencodian-model-picker-title {
  margin: 0;
  padding: 12px 20px 6px;
  font-size: 15px;
  font-weight: 700;
  color: var(--text-normal);
  line-height: 1.3;
}

.opencodian-model-picker-modal-desc {
  margin: 0;
  padding: 0 20px 10px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-faint);
}

.opencodian-model-picker-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 8px;
  padding: 0 20px 12px;
}

.opencodian-model-picker-provider-select-wrap {
  position: relative;
  flex: 0 0 150px;
}

.opencodian-model-picker-provider-select {
  width: 100%;
  min-height: 40px;
  height: 40px;
  padding: 0 28px 0 10px;
  border-radius: 8px;
  border: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
  color: var(--text-normal);
  font-size: 12px;
  line-height: 1;
  appearance: none;
  -webkit-appearance: none;
  box-sizing: border-box;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.opencodian-model-picker-provider-select:focus {
  outline: none;
  border-color: color-mix(in srgb, var(--interactive-accent) 50%, var(--background-modifier-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--interactive-accent) 12%, transparent);
}

.opencodian-model-picker-provider-select-wrap:focus-within .opencodian-model-picker-provider-select-chevron {
  color: var(--interactive-accent);
}

.opencodian-model-picker-provider-select-chevron {
  position: absolute;
  top: 50%;
  right: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  color: var(--text-muted);
  pointer-events: none;
  transform: translateY(-50%);
}

.opencodian-model-picker-provider-select-chevron svg {
  width: 12px;
  height: 12px;
}

.opencodian-model-picker-search {
  flex: 1 1 200px;
  min-width: 0;
}

.opencodian-model-picker-search-container {
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 40px;
  height: 40px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
  box-sizing: border-box;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.opencodian-model-picker-search-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: var(--text-muted);
  pointer-events: none;
}

.opencodian-model-picker-search-input {
  flex: 1 1 auto;
  width: auto;
  min-width: 0;
  height: 38px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-normal);
  font-size: 12px;
  box-shadow: none;
}

.opencodian-model-picker-search-input:focus {
  outline: none;
  box-shadow: none;
}

.opencodian-model-picker-search-container:focus-within {
  border-color: color-mix(in srgb, var(--interactive-accent) 50%, var(--background-modifier-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--interactive-accent) 12%, transparent);
}

.opencodian-settings-search-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 72%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--background-primary) 92%, var(--background-secondary));
  color: var(--text-muted);
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease, color 0.16s ease, opacity 0.16s ease;
}

.opencodian-settings-search-clear:disabled {
  cursor: default;
}

.opencodian-settings-search-clear:hover,
.opencodian-settings-search-clear:focus-visible {
  border-color: color-mix(in srgb, var(--interactive-accent) 34%, var(--background-modifier-border));
  background: color-mix(in srgb, var(--interactive-accent) 8%, var(--background-primary));
  color: var(--text-normal);
  outline: none;
}

.opencodian-settings-search-clear.is-disabled {
  opacity: 0.52;
  pointer-events: none;
}

.opencodian-settings-search-clear svg {
  width: 12px;
  height: 12px;
}

.opencodian-settings-search-history-popover {
  position: fixed;
  z-index: 2280;
  max-width: min(320px, calc(100vw - 24px));
  padding: 8px;
  border: 1px solid color-mix(in srgb, var(--background-modifier-border) 82%, transparent);
  border-radius: 14px;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-primary) 96%, var(--background-secondary)) 0%,
      color-mix(in srgb, var(--background-primary) 90%, var(--background-secondary)) 100%
    );
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, white 4%, transparent),
    0 16px 32px color-mix(in srgb, black 18%, transparent);
}

.opencodian-settings-search-history-popover.is-hidden {
  display: none;
}

.opencodian-settings-search-history-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 220px;
  overflow-y: auto;
}

.opencodian-settings-search-history-option {
  width: 100%;
  padding: 10px 12px;
  border: none;
  border-radius: 10px;
  background: transparent;
  color: var(--text-normal);
  text-align: left;
  font-size: 12px;
  line-height: 1.45;
  cursor: pointer;
  transition: background 0.16s ease, color 0.16s ease;
}

.opencodian-settings-search-history-option:hover,
.opencodian-settings-search-history-option:focus-visible {
  background: color-mix(in srgb, var(--interactive-accent) 10%, var(--background-primary));
  color: var(--text-normal);
  outline: none;
}

.opencodian-model-picker-list {
  max-height: 380px;
  overflow-y: auto;
  padding: 0 20px 16px;
}

.opencodian-model-picker-list-inner {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.opencodian-model-picker-option.is-empty {
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px dashed var(--background-modifier-border);
  background: color-mix(in srgb, var(--background-primary) 50%, transparent);
}

.opencodian-model-picker-option.is-empty:hover {
  background: color-mix(in srgb, var(--background-modifier-hover) 50%, transparent);
}

.opencodian-model-picker-option.is-empty.is-selected {
  border-color: color-mix(in srgb, var(--interactive-accent) 40%, var(--background-modifier-border));
  border-style: solid;
  background: color-mix(in srgb, var(--background-primary) 50%, transparent);
}

.opencodian-model-picker-option.is-empty.is-highlighted {
  background: color-mix(in srgb, var(--interactive-accent) 4%, var(--background-modifier-hover));
}

.opencodian-model-picker-divider {
  height: 1px;
  background: var(--background-modifier-border-hover);
}

.opencodian-model-picker-group {
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--background-modifier-border);
  background: color-mix(in srgb, var(--background-primary) 60%, var(--background-secondary));
}

.opencodian-model-picker-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--background-modifier-border-hover);
}

.opencodian-model-picker-group-title-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.opencodian-model-picker-group-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
  color: var(--text-muted);
}

.opencodian-model-picker-group-icon svg,
.opencodian-model-picker-group-icon img {
  width: 18px;
  height: 18px;
  object-fit: contain;
}

.opencodian-model-picker-group-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-normal);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.opencodian-model-picker-group-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.opencodian-model-picker-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 8px;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease;
}

.opencodian-model-picker-option:hover {
  background: color-mix(in srgb, var(--background-modifier-hover) 50%, transparent);
}

.opencodian-model-picker-option.is-selected {
  border-color: color-mix(in srgb, var(--interactive-accent) 35%, transparent);
  background: transparent;
}

.opencodian-model-picker-option.is-highlighted {
  background: color-mix(in srgb, var(--interactive-accent) 5%, var(--background-modifier-hover));
}

.opencodian-model-picker-option.is-selected.is-highlighted {
  background: color-mix(in srgb, var(--interactive-accent) 10%, var(--background-primary));
}

.opencodian-model-picker-option-info {
  min-width: 0;
}

.opencodian-model-picker-option-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-normal);
  line-height: 1.4;
}

.opencodian-model-picker-option-meta {
  margin-top: 2px;
  font-size: 11px;
  line-height: 1.4;
  color: var(--text-faint);
  word-break: break-word;
}

.opencodian-model-picker-option-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  color: var(--interactive-accent);
  opacity: 0;
  transition: opacity 0.12s ease;
}

.opencodian-model-picker-option.is-selected .opencodian-model-picker-option-check {
  opacity: 1;
}

.opencodian-model-picker-empty {
  padding: 20px 8px;
  text-align: center;
  font-size: 13px;
  color: var(--text-muted);
}

.opencodian-model-source-badge {
  flex: 0 0 auto;
  padding: 1px 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--background-secondary) 70%, transparent);
  color: var(--text-faint);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.02em;
  line-height: 1.5;
  text-transform: none;
}

@media (max-width: 520px) {
  .opencodian-model-picker-controls {
    flex-direction: column;
  }

  .opencodian-model-picker-provider-select-wrap {
    flex-basis: auto;
    width: 100%;
  }

  .opencodian-model-picker-search {
    flex-basis: auto;
    width: 100%;
  }

  .opencodian-model-picker-list {
    padding: 0 12px 12px;
  }

  .opencodian-model-picker-header,
  .opencodian-model-picker-modal-desc,
  .opencodian-model-picker-controls {
    padding-left: 12px;
    padding-right: 12px;
  }

  .opencodian-model-catalog-summary-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

.opencodian-model-catalog-header {
  padding: 2px 2px 10px;
}

.opencodian-model-catalog-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-normal);
}

.opencodian-model-catalog-desc,
.opencodian-model-catalog-summary {
  margin-top: 6px;
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.5;
}

.opencodian-model-catalog-body {
  max-height: 320px;
  overflow-y: auto;
  padding: 0 2px 2px;
}

.opencodian-model-catalog-empty {
  padding: 20px 0 4px;
  font-size: 12px;
  color: var(--text-faint);
}

.opencodian-model-catalog-provider {
  padding: 12px 0;
  border-top: 1px solid var(--background-modifier-border-hover);
}

.opencodian-model-catalog-provider:first-child {
  border-top: none;
  padding-top: 4px;
}

.opencodian-model-catalog-provider-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.opencodian-model-catalog-provider-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-normal);
}

.opencodian-model-catalog-provider-count {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--background-primary);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
}

.opencodian-model-catalog-provider-models {
  margin-top: 6px;
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.6;
  word-break: break-word;
}

.opencodian-model-config-defaults,
.opencodian-model-provider-grid,
.opencodian-model-provider-model-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.opencodian-model-config-defaults {
  margin-bottom: 16px;
}

.opencodian-model-config-intro {
  margin: 8px 0 12px;
  color: var(--text-muted);
  line-height: 1.5;
}

.opencodian-model-config-section-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 16px 0 12px;
}

.opencodian-model-config-section-title {
  margin: 0;
  font-size: 14px;
}

.opencodian-model-config-section-description {
  margin: 0;
  color: var(--text-muted);
  line-height: 1.45;
}

.opencodian-model-config-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.opencodian-model-config-field label {
  font-size: 12px;
  color: var(--text-muted);
}

.opencodian-model-config-field input,
.opencodian-model-config-field select {
  width: 100%;
}

.opencodian-model-config-field-description {
